INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0605', 'lever standing calf raise', 'lower legs', 'lower legs', 'leverage machine', 'Adjust the machine to your height and stand with your feet shoulder-width apart. Place your shoulders under the pads and hold onto the handles for stability. Raise your heels as high as possible by extending your ankles. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina a tu altura y ponte de pie con los pies separados a la altura de los hombros. Coloca los hombros debajo de las almohadillas y sujétate de las asas para mayor estabilidad. Eleva los talones tan alto como puedas extendiendo los tobillos. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'soleus', '["soleus","ankle stabilizers"]'::jsonb, 'calves', 'images/0605-ykUOVze.jpg', 'videos/0605-ykUOVze.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3758', 'lever standing chest press', 'chest', 'chest', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your feet flat on the ground. Grasp the handles with an overhand grip and position your hands at chest level. Push the handles forward until your arms are fully extended, keeping your elbows slightly bent. Pause for a moment, then slowly bring the handles back towards your chest, maintaining control throughout the movement. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con los pies planos en el suelo. Agarra las asas con un agarre prono y coloca las manos a la altura del pecho. Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, manteniendo los codos ligeramente flexionados. Haz una pausa por un momento y luego lleva lentamente las asas de vuelta hacia el pecho, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/3758-WbNq5Xu.jpg', 'videos/3758-WbNq5Xu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0606', 'lever t bar row', 'back', 'back', 'leverage machine', 'Adjust the seat height and footplate position to ensure proper alignment. Sit on the machine with your chest against the pad and your feet flat on the footplate. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and engage your core. Pull the handles towards your torso, squeezing your shoulder blades together. Pause for a moment at the peak contraction, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y la posición de la placa para los pies para asegurar una alineación correcta. Siéntate en la máquina con el pecho contra la almohadilla y los pies planos sobre la placa para los pies. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén la espalda recta y activa el core. Tira de las asas hacia el torso, juntando los omóplatos. Haz una pausa en el punto de máxima contracción y luego suelta lentamente las asas hasta la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/0606-aaXr7ld.jpg', 'videos/0606-aaXr7ld.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1351', 'lever t-bar reverse grip row', 'back', 'back', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the floor. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and engage your core. Pull the handles towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén la espalda recta y activa el core. Tira de las asas hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento, luego suelta lentamente y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1351-FVM1AUZ.jpg', 'videos/1351-FVM1AUZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0607', 'lever triceps extension', 'upper arms', 'upper arms', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back against the pad. Grasp the handles with an overhand grip and fully extend your arms in front of you. Keeping your upper arms stationary, slowly lower the handles towards your forehead by bending your elbows. Pause for a moment at the bottom, then push the handles back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda apoyada en la almohadilla. Agarra las asas con un agarre prono y extiende completamente los brazos frente a ti. Manteniendo la parte superior de los brazos inmóvil, baja lentamente las asas hacia tu frente flexionando los codos. Haz una pausa por un momento en la parte baja y luego empuja las asas de vuelta hacia arriba hasta la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0607-Ser9eQp.jpg', 'videos/0607-Ser9eQp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1313', 'lever unilateral row', 'back', 'back', 'leverage machine', 'Adjust the seat height and position yourself facing the machine. Grasp the handles with an overhand grip and keep your back straight. Pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release and extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate frente a la máquina. Agarra las asas con un agarre prono y mantén la espalda recta. Jala las agarraderas hacia el cuerpo, apretando los omóplatos entre sí. Haz una pausa en el punto máximo del movimiento y luego suelta lentamente, extendiendo los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1313-oROuvrX.jpg', 'videos/1313-oROuvrX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0609', 'london bridge', 'back', 'back', 'rope', 'Attach the rope to a high anchor point. Stand facing away from the anchor point with your feet shoulder-width apart. Grasp the rope with an overhand grip, palms facing down. Lean forward slightly, keeping your back straight and core engaged. Pull the rope towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la cuerda a un punto de anclaje alto. Ponte de pie de espaldas al punto de anclaje con los pies separados a la altura de los hombros. Agarra la cuerda con un agarre prono, con las palmas hacia abajo. Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado. Tira de la cuerda hacia tu cuerpo, juntando las escápulas. Haz una pausa por un momento en el punto más alto del movimiento, luego libera lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","biceps","forearms"]'::jsonb, 'upper back', 'images/0609-bLyQokI.jpg', 'videos/0609-bLyQokI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3013', 'low glute bridge on floor', 'upper legs', 'upper legs', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your arms by your sides, palms facing down. Engage your glutes and core, then lift your hips off the ground until your body forms a straight line from your knees to your shoulders. Pause for a moment at the top, squeezing your glutes. Slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca los brazos a los lados del cuerpo, con las palmas hacia abajo. Activa los glúteos y el core, y luego eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa breve en la parte alta, apretando los glúteos. Baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","core"]'::jsonb, 'glutes', 'images/3013-u0cNiij.jpg', 'videos/3013-u0cNiij.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1352', 'lower back curl', 'back', 'back', 'body weight', 'Lie flat on your stomach with your legs extended and your arms by your sides. Engage your glutes and hamstrings, and slowly lift your upper body off the ground, curling your back upwards. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo con las piernas extendidas y los brazos a los lados del cuerpo. Activa los glúteos y los isquiotibiales, y eleva lentamente la parte superior del cuerpo del suelo, curvando la espalda hacia arriba. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'spine', 'images/1352-ANbbry2.jpg', 'videos/1352-ANbbry2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3582', 'lunge with jump', 'upper legs', 'upper legs', 'body weight', 'Start by standing with your feet shoulder-width apart. Take a step forward with your right foot, lowering your body into a lunge position. Push off with your right foot and jump into the air, switching the position of your feet mid-air. Land softly with your left foot forward and immediately lower your body into a lunge position. Continue alternating between lunges and jumps for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Empújate con el pie derecho y salta al aire, cambiando la posición de los pies en pleno vuelo. Aterriza suavemente con el pie izquierdo hacia adelante y baja inmediatamente el cuerpo a una posición de zancada. Continúa alternando entre zancadas y saltos el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3582-PM1PZjg.jpg', 'videos/3582-PM1PZjg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1688', 'lunge with twist', 'waist', 'waist', 'body weight', 'Start by standing with your feet shoulder-width apart. Take a step forward with your right foot, lowering your body into a lunge position. As you lunge, twist your torso to the right, bringing your left elbow towards your right knee. Pause for a moment, then return to the starting position. Repeat on the other side, stepping forward with your left foot and twisting your torso to the left. Continue alternating sides for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Al hacer la zancada, gira el torso hacia la derecha, llevando el codo izquierdo hacia la rodilla derecha. Haz una pausa breve y luego vuelve a la posición inicial. Repite hacia el otro lado, dando un paso adelante con el pie izquierdo y girando el torso hacia la izquierda. Continúa alternando lados durante el número de repeticiones deseado.', 'quadriceps', '["quadriceps","glutes","hamstrings"]'::jsonb, 'abs', 'images/1688-K9VL0Jq.jpg', 'videos/1688-K9VL0Jq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0613', 'lying (side) quads stretch', 'upper legs', 'upper legs', 'body weight', 'Lie on your side with your legs straight. Bend your top leg and grab your ankle or foot with your hand. Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads. Hold the stretch for 20-30 seconds. Release the stretch and repeat on the other side.', 'Túmbate de lado con las piernas rectas. Flexiona la pierna de arriba y agarra tu tobillo o pie con la mano. Tira suavemente del tobillo o del pie hacia los glúteos hasta sentir un estiramiento en los cuádriceps. Mantén el estiramiento durante 20-30 segundos. Suelta el estiramiento y repite del otro lado.', 'hamstrings', '["hamstrings"]'::jsonb, 'quads', 'images/0613-BWnJR72.jpg', 'videos/0613-BWnJR72.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2312', 'lying elbow to knee', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engage your abs and lift your upper body off the ground, bringing your right elbow towards your left knee. At the same time, extend your right leg straight out and lift it off the ground. Pause for a moment, then return to the starting position. Repeat the movement, this time bringing your left elbow towards your right knee and extending your left leg. Continue alternating sides for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activa el abdomen y levanta la parte superior del cuerpo del suelo, llevando el codo derecho hacia la rodilla izquierda. Al mismo tiempo, extiende la pierna derecha en línea recta y levántala del suelo. Haz una pausa breve y luego vuelve a la posición inicial. Repite el movimiento, esta vez llevando el codo izquierdo hacia la rodilla derecha y extendiendo la pierna izquierda. Continúa alternando lados durante el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/2312-AQIhRjM.jpg', 'videos/2312-AQIhRjM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0620', 'lying leg raise flat bench', 'waist', 'waist', 'body weight', 'Lie flat on a flat bench with your back pressed against it. Place your hands under your glutes for support. Keep your legs straight and together, and lift them up towards the ceiling. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate en un banco plano con la espalda presionada contra él. Coloca las manos debajo de los glúteos como apoyo. Mantén las piernas rectas y juntas, y elévalas hacia el techo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0620-WhuFnR7.jpg', 'videos/0620-WhuFnR7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0865', 'lying leg-hip raise', 'waist', 'waist', 'body weight', 'Lie flat on your back with your legs extended and your arms by your sides. Place your hands under your glutes for support. Engage your core and lift your legs off the ground, raising them towards the ceiling. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Coloca las manos debajo de los glúteos como apoyo. Activa el core y levanta las piernas del suelo, elevándolas hacia el techo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0865-9IxJdtC.jpg', 'videos/0865-9IxJdtC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1301', 'machine inner chest press', 'chest', 'chest', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your back flat against the pad. Grasp the handles with an overhand grip and position your elbows at a 90-degree angle. Push the handles forward until your arms are fully extended, exhaling during the movement. Pause for a moment at the end of the movement, then slowly return to the starting position, inhaling as you do so. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con la espalda totalmente apoyada en la almohadilla. Sujeta las asas con un agarre prono y coloca los codos en un ángulo de 90 grados. Empuja las asas hacia adelante hasta que los brazos queden completamente extendidos, exhalando durante el movimiento. Haz una pausa al final del movimiento y luego vuelve lentamente a la posición inicial, inhalando mientras lo haces. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1301-wDN97Ca.jpg', 'videos/1301-wDN97Ca.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0624', 'march sit (wall)', 'upper legs', 'upper legs', 'body weight', 'Stand with your back against a wall and your feet hip-width apart. Slowly slide your back down the wall until your knees are bent at a 90-degree angle. Lift your right foot off the ground and bring your knee towards your chest. Lower your right foot back down and lift your left foot off the ground, bringing your knee towards your chest. Continue alternating between lifting your right and left foot for the desired number of repetitions.', 'Ponte de pie con la espalda contra una pared y los pies separados a la altura de las caderas. Desliza lentamente la espalda hacia abajo por la pared hasta que las rodillas formen un ángulo de 90 grados. Levanta el pie derecho del suelo y lleva la rodilla hacia el pecho. Baja el pie derecho de nuevo y levanta el pie izquierdo del suelo, llevando la rodilla hacia el pecho. Continúa alternando entre levantar el pie derecho y el izquierdo el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0624-sVQCCeG.jpg', 'videos/0624-sVQCCeG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1353', 'medicine ball catch and overhead throw', 'back', 'back', 'medicine ball', 'Stand with your feet shoulder-width apart, holding a medicine ball in both hands at chest level. Bend your knees slightly and engage your core. Lower your body into a squat position, keeping your back straight and chest up. Explosively extend your hips and legs, while simultaneously throwing the medicine ball overhead. Release the ball at the top of the movement and catch it on the way down. Lower your body back into the squat position and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos a la altura del pecho. Flexiona ligeramente las rodillas y activa el core. Baja el cuerpo a una posición de sentadilla, manteniendo la espalda recta y el pecho hacia arriba. Extiende explosivamente las caderas y las piernas, mientras lanzas simultáneamente el balón medicinal por encima de la cabeza. Suelta el balón en la parte más alta del movimiento y atrápalo cuando vaya bajando. Baja de nuevo el cuerpo a la posición de sentadilla y repite el número de repeticiones deseado.', 'shoulders', '["shoulders","core"]'::jsonb, 'lats', 'images/1353-PsVS1QP.jpg', 'videos/1353-PsVS1QP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1302', 'medicine ball chest pass', 'chest', 'chest', 'medicine ball', 'Stand with your feet shoulder-width apart, holding the medicine ball at chest level. Extend your arms forward, pushing the medicine ball away from your chest with force. As you release the ball, follow through with your arms and torso, transferring your weight from your back foot to your front foot. Catch the ball as it rebounds off the wall or partner, and immediately repeat the movement. Continue for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho. Extiende los brazos hacia adelante, empujando el balón medicinal con fuerza para alejarlo del pecho. Al soltar el balón, continúa el movimiento con los brazos y el torso, transfiriendo el peso del pie de atrás al pie de adelante. Atrapa el balón cuando rebote en la pared o en tu compañero, y repite el movimiento de inmediato. Continúa durante el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1302-aDoFKrE.jpg', 'videos/1302-aDoFKrE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1303', 'medicine ball chest push from 3 point stance', 'chest', 'chest', 'medicine ball', 'Start in a 3 point stance with one hand on the medicine ball and the other hand on the ground. Extend your legs and position your body in a straight line. Lower your chest towards the ground while keeping your back straight. Push the medicine ball away from your body, extending your arm fully. Return to the starting position and repeat for the desired number of repetitions.', 'Comienza en una posición de apoyo de 3 puntos con una mano sobre el balón medicinal y la otra en el suelo. Extiende las piernas y coloca tu cuerpo en línea recta. Baja el pecho hacia el suelo manteniendo la espalda recta. Empuja el balón medicinal alejándolo de tu cuerpo, extendiendo completamente el brazo. Vuelve a la posición inicial y repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/1303-dCJnuVq.jpg', 'videos/1303-dCJnuVq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1304', 'medicine ball chest push multiple response', 'chest', 'chest', 'medicine ball', 'Stand with your feet shoulder-width apart, holding a medicine ball at chest level. Extend your arms forward, pushing the medicine ball away from your chest. Pause for a moment, then slowly bring the medicine ball back to your chest. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho. Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho. Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1304-7aolH9D.jpg', 'videos/1304-7aolH9D.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1305', 'medicine ball chest push single response', 'chest', 'chest', 'medicine ball', 'Stand with your feet shoulder-width apart, holding the medicine ball at chest level. Extend your arms forward, pushing the medicine ball away from your chest. Pause for a moment, then slowly bring the medicine ball back to your chest. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal a la altura del pecho. Extiende los brazos hacia adelante, alejando el balón medicinal de tu pecho. Haz una pausa por un momento y luego lleva lentamente el balón medicinal de vuelta al pecho. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1305-jeHtrlO.jpg', 'videos/1305-jeHtrlO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1312', 'medicine ball chest push with run release', 'chest', 'chest', 'medicine ball', 'Stand with your feet shoulder-width apart, holding a medicine ball at chest level. Step forward with your right foot and simultaneously push the medicine ball forward, extending your arms fully. As you push the ball forward, release it and let it roll forward. Quickly run forward and catch the ball before it hits the ground. Once you catch the ball, bring it back to your chest and repeat the movement with your left foot forward. Continue alternating legs and repeating the exercise for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal a la altura del pecho. Da un paso adelante con el pie derecho y, al mismo tiempo, empuja el balón medicinal hacia adelante, extendiendo completamente los brazos. Mientras empujas el balón hacia adelante, suéltalo y déjalo rodar. Corre rápidamente hacia adelante y atrapa el balón antes de que toque el suelo. Una vez que atrapes el balón, llévalo de vuelta al pecho y repite el movimiento con el pie izquierdo adelante. Continúa alternando piernas y repitiendo el ejercicio el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/1312-pX9Elbe.jpg', 'videos/1312-pX9Elbe.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1701', 'medicine ball close grip push up', 'upper arms', 'upper arms', 'medicine ball', 'Start in a high plank position with your hands on the medicine ball, shoulder-width apart. Lower your body towards the ground by bending your elbows, keeping them close to your sides. Push back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Empuja de vuelta hasta la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1701-8K7m2SS.jpg', 'videos/1701-8K7m2SS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1354', 'medicine ball overhead slam', 'back', 'back', 'medicine ball', 'Stand with your feet shoulder-width apart, holding a medicine ball with both hands above your head. Engage your core and keep your back straight. Bend your knees slightly and forcefully slam the medicine ball down to the ground in front of you. As you slam the ball down, use your entire body to generate power, including your shoulders and core. Catch the ball on the bounce and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un balón medicinal con ambas manos por encima de la cabeza. Activa el core y mantén la espalda recta. Flexiona ligeramente las rodillas y lanza con fuerza el balón medicinal contra el suelo frente a ti. Al lanzar el balón al suelo, utiliza todo el cuerpo para generar potencia, incluidos los hombros y el core. Atrapa el balón al rebotar y repite el número de repeticiones deseado.', 'shoulders', '["shoulders","core"]'::jsonb, 'upper back', 'images/1354-oHg8eop.jpg', 'videos/1354-oHg8eop.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1750', 'medicine ball supine chest throw', 'upper arms', 'upper arms', 'medicine ball', 'Lie flat on your back on a bench with your knees bent and feet flat on the ground. Hold the medicine ball with both hands, extending your arms straight up above your chest. Lower the medicine ball towards your chest, keeping your elbows close to your body. Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible. Catch the medicine ball and repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco con las rodillas flexionadas y los pies planos en el suelo. Sostén el balón medicinal con ambas manos, extendiendo los brazos rectos por encima del pecho. Baja el balón medicinal hacia el pecho, manteniendo los codos cerca del cuerpo. Empuja el balón medicinal explosivamente hacia arriba, extendiendo completamente los brazos y lanzando el balón lo más alto posible. Atrapa el balón medicinal y repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1750-Al3tP0D.jpg', 'videos/1750-Al3tP0D.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0627', 'mixed grip chin-up', 'back', 'back', 'body weight', 'Grab the pull-up bar with an underhand grip (palms facing towards you) and your hands slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your feet off the ground. Engage your back muscles and pull your body up towards the bar, leading with your chest. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position with control. Repeat for the desired number of repetitions.', 'Agarra la barra de dominadas con un agarre supino (las palmas hacia ti) y las manos un poco más separadas que la anchura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y los pies fuera del suelo. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0627-T8UpLkb.jpg', 'videos/0627-T8UpLkb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3217', 'modified hindu push-up (male)', 'chest', 'chest', 'body weight', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet hip-width apart. Lower your body towards the ground, bending your elbows and keeping your core engaged. As you lower your body, shift your weight back and lift your hips up towards the ceiling, creating an inverted V shape with your body. Continue to lower your body until your chest is just above the ground, then reverse the movement, pushing your hips back down and extending your arms to return to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies separados a la altura de las caderas. Baja el cuerpo hacia el suelo, flexionando los codos y manteniendo el core activado. Mientras bajas el cuerpo, desplaza el peso hacia atrás y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo. Sigue bajando el cuerpo hasta que el pecho quede justo por encima del suelo y luego invierte el movimiento, empujando las caderas hacia abajo y extendiendo los brazos para volver a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/3217-epOSYUZ.jpg', 'videos/3217-epOSYUZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1421', 'modified push up to lower arms', 'lower arms', 'lower arms', 'body weight', 'Start in a push-up position with your hands directly under your shoulders and your body in a straight line. Lower your body down towards the ground by bending your elbows, keeping them close to your sides. Once your elbows are at a 90-degree angle, lower your forearms to the ground, keeping your elbows directly under your shoulders. Pause for a moment, then push through your palms to lift your forearms back up to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de flexión con las manos directamente debajo de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de tu costado. Cuando los codos formen un ángulo de 90 grados, baja los antebrazos hasta el suelo, manteniendo los codos justo debajo de los hombros. Haz una pausa por un momento y luego empuja con las palmas para llevar los antebrazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","chest","shoulders"]'::jsonb, 'forearms', 'images/1421-arvaszz.jpg', 'videos/1421-arvaszz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0628', 'monster walk', 'upper legs', 'upper legs', 'body weight', 'Place a resistance band around your ankles. Stand with your feet shoulder-width apart and slightly bend your knees. Take a step to the side with your right foot, maintaining tension on the resistance band. Follow with your left foot, stepping to the side to return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Coloca una banda elástica alrededor de los tobillos. Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas. Da un paso hacia el lado con el pie derecho, manteniendo la tensión en la banda elástica. Continúa con el pie izquierdo, dando un paso lateral para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/0628-O95afRA.jpg', 'videos/0628-O95afRA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0630', 'mountain climber', 'cardio', 'cardio', 'body weight', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Engage your core and bring your right knee towards your chest, then quickly switch and bring your left knee towards your chest. Continue alternating legs in a running motion, keeping your hips low and your core engaged. Maintain a steady pace and breathe evenly throughout the exercise. Repeat for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Activa el core y lleva la rodilla derecha hacia el pecho, luego cambia rápidamente y lleva la rodilla izquierda hacia el pecho. Continúa alternando las piernas con un movimiento de carrera, manteniendo las caderas bajas y el core activado. Mantén un ritmo constante y respira de forma regular durante todo el ejercicio. Repite el número de repeticiones deseado.', 'core', '["core","shoulders","triceps"]'::jsonb, 'cardiovascular system', 'images/0630-RJgzwny.jpg', 'videos/0630-RJgzwny.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0631', 'muscle up', 'back', 'back', 'body weight', 'Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended. Engage your core and pull your body up towards the bar, leading with your chest. As you reach the top of the movement, transition your grip so that your palms are facing towards you. Continue pulling yourself up until your chest is above the bar and your arms are fully flexed. Reverse the movement by slowly lowering yourself back down to the starting position. Repeat for the desired number of repetitions.', 'Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti. Sigue tirando hacia arriba hasta que el pecho quede por encima de la barra y los brazos estén completamente flexionados. Invierte el movimiento bajando lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps","shoulders","chest"]'::jsonb, 'lats', 'images/0631-yJUHKTn.jpg', 'videos/0631-yJUHKTn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1401', 'muscle-up (on vertical bar)', 'back', 'back', 'body weight', 'Start by hanging from a vertical bar with your palms facing away from you and your arms fully extended. Engage your core and pull your body up towards the bar, leading with your chest. As you pull yourself up, lean back slightly and bring your elbows towards your sides. Continue pulling until your chest reaches the bar and your elbows are fully bent. Pause for a moment at the top, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', 'Comienza colgándote de una barra vertical con las palmas hacia afuera y los brazos completamente extendidos. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Al subir tu cuerpo, inclínate ligeramente hacia atrás y lleva los codos hacia los costados. Sigue tirando hasta que el pecho llegue a la barra y los codos estén completamente flexionados. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps","forearms"]'::jsonb, 'lats', 'images/1401-Af0EW2I.jpg', 'videos/1401-Af0EW2I.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2328', 'narrow push-up on exercise ball', 'upper arms', 'upper arms', 'stability ball', 'Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart. Engage your core and keep your body in a straight line from head to toe. Lower your chest towards the ball by bending your elbows, keeping them close to your body. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Coloca el balón de estabilidad en el suelo y ponte en posición de flexión con las manos sobre el balón, un poco más juntas que la anchura de los hombros. Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies. Baja el pecho hacia el balón flexionando los codos, manteniéndolos cerca del cuerpo. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/2328-4cWjYEN.jpg', 'videos/2328-4cWjYEN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1403', 'neck side stretch', 'neck', 'neck', 'body weight', 'Stand or sit up straight with your shoulders relaxed. Tilt your head to one side, bringing your ear towards your shoulder. Hold the stretch for 15-30 seconds. Repeat on the other side. Perform 2-4 sets on each side.', 'Ponte de pie o siéntate erguido con los hombros relajados. Inclina la cabeza hacia un lado, llevando la oreja hacia el hombro. Mantén el estiramiento durante 15-30 segundos. Repite del otro lado. Realiza de 2 a 4 series por cada lado.', 'trapezius', '["trapezius","sternocleidomastoid"]'::jsonb, 'levator scapulae', 'images/1403-x2chWLO.jpg', 'videos/1403-x2chWLO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0634', 'negative crunch', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0634-szIn2UK.jpg', 'videos/0634-szIn2UK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1495', 'oblique crunch v. 2', 'waist', 'waist', 'body weight', 'Lie on your back with your knees bent and feet flat on the ground. Place your hands behind your head or cross them over your chest. Engage your abs and lift your shoulder blades off the ground, rotating your torso to one side. Pause for a moment, then lower your shoulder blades back down to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado. Haz una pausa por un momento y luego baja las escápulas de nuevo a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/1495-cJgSTmh.jpg', 'videos/1495-cJgSTmh.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0635', 'oblique crunches floor', 'waist', 'waist', 'body weight', 'Lie on your back with your knees bent and feet flat on the floor. Place your hands behind your head or cross them over your chest. Engage your abs and lift your shoulder blades off the floor, rotating your torso to one side. Pause for a moment, then lower your shoulder blades back down to the floor. Repeat on the other side, alternating sides with each repetition.', 'Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el abdomen y levanta las escápulas del suelo, rotando el torso hacia un lado. Haz una pausa por un momento y luego baja las escápulas de nuevo hasta el suelo. Repite hacia el otro lado, alternando los lados en cada repetición.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0635-QUDd8WS.jpg', 'videos/0635-QUDd8WS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0636', 'olympic barbell hammer curl', 'upper arms', 'upper arms', 'olympic barbell', 'Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip. Let the barbell hang at arm''s length in front of your thighs, with your palms facing your body. Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Inhale and slowly begin to lower the barbell back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra olímpica con un agarre prono. Deja que la barra cuelgue a la altura de los brazos frente a tus muslos, con las palmas hacia tu cuerpo. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0636-o1ntciW.jpg', 'videos/0636-o1ntciW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0637', 'olympic barbell triceps extension', 'upper arms', 'upper arms', 'olympic barbell', 'Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip. Raise the barbell above your head, fully extending your arms. Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows. Pause for a moment, then extend your arms back to the starting position. Repeat for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra con un agarre prono. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0637-wu5LXwz.jpg', 'videos/0637-wu5LXwz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1355', 'one arm against wall', 'back', 'back', 'body weight', 'Stand facing a wall with your feet shoulder-width apart. Extend one arm straight out in front of you and place your palm against the wall. Engage your core and lean your body forward, keeping your arm straight and your back flat. Slowly push against the wall with your palm, activating your lat muscles. Hold the position for a few seconds, then release and repeat with the other arm.', 'Ponte de pie frente a una pared con los pies separados a la altura de los hombros. Extiende un brazo recto hacia adelante y coloca la palma contra la pared. Activa el core e inclina el cuerpo hacia adelante, manteniendo el brazo recto y la espalda plana. Empuja lentamente la pared con la palma, activando los dorsales. Mantén la posición durante unos segundos, luego suelta y repite con el otro brazo.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'lats', 'images/1355-ZZTGMKh.jpg', 'videos/1355-ZZTGMKh.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0638', 'one arm chin-up', 'back', 'back', 'body weight', 'Stand facing a pull-up bar with your feet shoulder-width apart. Reach up and grab the bar with an underhand grip, with one hand gripping the bar and the other hand holding your wrist for support. Hang from the bar with your arm fully extended, keeping your body straight and your core engaged. Pull yourself up towards the bar by bending your elbow and squeezing your back muscles. Continue pulling until your chin is above the bar, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions, then switch arms and repeat.', 'Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros. Estírate y agarra la barra con un agarre supino, con una mano sujetando la barra y la otra sosteniendo la muñeca como apoyo. Cuélgate de la barra con el brazo completamente extendido, manteniendo el cuerpo recto y el core activado. Tira de tu cuerpo hacia la barra flexionando el codo y contrayendo los músculos de la espalda. Continúa subiendo hasta que la barbilla quede por encima de la barra, luego bájate lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo y repite.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0638-HjdqmZa.jpg', 'videos/0638-HjdqmZa.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0639', 'one arm dip', 'upper arms', 'upper arms', 'body weight', 'Stand facing away from a bench or chair, with your feet shoulder-width apart. Place one hand on the bench or chair behind you, fingers pointing towards your body. Extend your legs out in front of you, keeping your heels on the ground. Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair. Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position. Repeat for the desired number of repetitions, then switch sides and repeat with the other arm.', 'Ponte de pie de espaldas a un banco o silla, con los pies separados a la altura de los hombros. Coloca una mano en el banco o silla detrás de ti, con los dedos apuntando hacia tu cuerpo. Extiende las piernas hacia adelante, manteniendo los talones en el suelo. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco o silla. Haz una pausa por un momento en la parte baja y luego empuja con las palmas para estirar los brazos y volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0639-FAoIFMw.jpg', 'videos/0639-FAoIFMw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0640', 'one arm slam (with medicine ball)', 'waist', 'waist', 'medicine ball', 'Stand with your feet shoulder-width apart, holding the medicine ball with one hand in front of your waist. Bend your knees slightly and engage your core. Raise the medicine ball above your head, fully extending your arm. Forcefully slam the medicine ball down to the ground, using your core and shoulders to generate power. Catch the medicine ball on the bounce and repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo el balón medicinal con una mano frente a la cintura. Flexiona ligeramente las rodillas y activa el core. Eleva el balón medicinal por encima de la cabeza, extendiendo completamente el brazo. Lanza con fuerza el balón medicinal contra el suelo, usando el core y los hombros para generar potencia. Atrapa el balón medicinal al rebotar y repite el número de repeticiones deseado.', 'shoulders', '["shoulders","back"]'::jsonb, 'abs', 'images/0640-jCrtE9b.jpg', 'videos/0640-jCrtE9b.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1773', 'one arm towel row', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart, knees slightly bent, and hold a towel with one hand. Bend forward at the waist, keeping your back straight and your core engaged. Extend your arm fully, allowing the towel to hang in front of you. Pull the towel towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the towel back to the starting position. Repeat for the desired number of repetitions, then switch arms.', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende completamente el brazo, dejando que la toalla cuelgue frente a ti. Tira de la toalla hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1773-bKWbrTA.jpg', 'videos/1773-bKWbrTA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1386', 'one leg donkey calf raise', 'lower legs', 'lower legs', 'body weight', 'Stand with your feet shoulder-width apart, toes pointing forward. Place your hands on a stable surface for support, such as a wall or a bar. Lift one leg off the ground, keeping your knee slightly bent. Raise your heel as high as possible, using your calf muscles. Pause for a moment at the top, then slowly lower your heel back down. Repeat for the desired number of repetitions, then switch legs.', 'Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante. Coloca las manos sobre una superficie estable para apoyarte, como una pared o una barra. Levanta una pierna del suelo, manteniendo la rodilla ligeramente flexionada. Eleva el talón lo más alto posible, usando los músculos de la pantorrilla. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo. Repite el número de repeticiones deseado, luego cambia de pierna.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1386-A2upspL.jpg', 'videos/1386-A2upspL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1387', 'one leg floor calf raise', 'lower legs', 'lower legs', 'body weight', 'Stand with your feet hip-width apart and place your hands on a wall or sturdy object for balance. Lift one foot off the ground and balance on the other foot. Slowly raise your heel off the ground, lifting your body up onto the ball of your foot. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', 'Ponte de pie con los pies separados a la altura de las caderas y coloca las manos en una pared u objeto firme para mantener el equilibrio. Levanta un pie del suelo y mantén el equilibrio sobre el otro pie. Levanta lentamente el talón del suelo, elevando el cuerpo sobre las puntas de los pies. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'ankles', '["ankles","feet"]'::jsonb, 'calves', 'images/1387-0jp9Rlz.jpg', 'videos/1387-0jp9Rlz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1476', 'one leg squat', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart. Extend one leg forward, keeping it off the ground. Bend your standing leg and lower your body down as if sitting back into a chair. Keep your chest up and your back straight. Push through your heel to return to the starting position. Repeat with the other leg.', 'Ponte de pie con los pies separados a la altura de los hombros. Extiende una pierna hacia adelante, manteniéndola elevada del suelo. Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla. Mantén el pecho arriba y la espalda recta. Empuja con el talón para regresar a la posición inicial. Repite con la otra pierna.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1476-C31LMnP.jpg', 'videos/1476-C31LMnP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0641', 'otis up', 'waist', 'waist', 'weighted', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/0641-UVL20oz.jpg', 'videos/0641-UVL20oz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0642', 'outside leg kick push-up', 'upper legs', 'upper legs', 'body weight', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together. Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged. As you push back up, kick one leg out to the side, extending it fully and engaging your glutes. Return your leg to the starting position and repeat the push-up, alternating legs with each repetition. Continue alternating leg kicks and push-ups for the desired number of repetitions.', 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado. Al empujar de vuelta hacia arriba, lanza una pierna hacia el lado, extendiéndola completamente y activando los glúteos. Vuelve a colocar la pierna en la posición inicial y repite la flexión, alternando las piernas en cada repetición. Continúa alternando las patadas de pierna y las flexiones el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0642-jNU1gFQ.jpg', 'videos/0642-jNU1gFQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0643', 'overhead triceps stretch', 'upper arms', 'upper arms', 'body weight', 'Stand or sit upright with your feet shoulder-width apart. Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade. With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps. Hold the stretch for 15-30 seconds, then release. Repeat on the other side.', 'Ponte de pie o siéntate erguido con los pies separados a la altura de los hombros. Extiende un brazo por encima de la cabeza, flexionando el codo de modo que la mano llegue hacia la escápula opuesta. Con la otra mano, tira suavemente del codo del brazo extendido hacia el lado opuesto de la cabeza, sintiendo un estiramiento en el tríceps. Mantén el estiramiento durante 15-30 segundos, luego suelta. Repite del otro lado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0643-Z5YStHW.jpg', 'videos/0643-Z5YStHW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3147', 'pelvic tilt', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands by your sides. Engage your abs and tilt your pelvis upward, pressing your lower back into the ground. Hold this position for a few seconds, focusing on contracting your abs. Release the tilt and return to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos a los lados del cuerpo. Activa el abdomen e inclina la pelvis hacia arriba, presionando la zona lumbar contra el suelo. Mantén esta posición durante unos segundos, concentrándote en contraer el abdomen. Deshaz la inclinación y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'lower back', '["lower back"]'::jsonb, 'abs', 'images/3147-NKJ8o6x.jpg', 'videos/3147-NKJ8o6x.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1422', 'pelvic tilt into bridge', 'upper legs', 'upper legs', 'body weight', 'Lie on your back with your knees bent and feet flat on the ground. Place your arms by your sides with your palms facing down. Engage your glutes and core muscles. Tilt your pelvis upward, lifting your hips off the ground. Hold the bridge position for a few seconds. Slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca los brazos a los lados del cuerpo con las palmas hacia abajo. Activa los glúteos y los músculos del core. Inclina la pelvis hacia arriba, levantando las caderas del suelo. Mantén la posición de puente durante unos segundos. Baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","core"]'::jsonb, 'glutes', 'images/1422-D9qe7CM.jpg', 'videos/1422-D9qe7CM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1388', 'peroneals stretch', 'lower legs', 'lower legs', 'rope', 'Sit on the ground with your legs extended in front of you. Loop the rope around the ball of your foot and hold the ends of the rope with your hands. Gently pull the rope towards you, flexing your foot and stretching your calf muscles. Hold the stretch for 15-30 seconds. Release the tension on the rope and repeat the stretch on the other leg. Repeat for the desired number of repetitions.', 'Siéntate en el suelo con las piernas extendidas frente a ti. Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos. Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla. Mantén el estiramiento durante 15-30 segundos. Suelta la tensión de la cuerda y repite el estiramiento en la otra pierna. Repite el número de repeticiones deseado.', 'ankles', '["ankles","feet"]'::jsonb, 'calves', 'images/1388-XhfS1DZ.jpg', 'videos/1388-XhfS1DZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3662', 'pike-to-cobra push-up', 'upper legs', 'upper legs', 'body weight', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together. Engage your core and lift your hips up towards the ceiling, forming an inverted V shape with your body. Lower your upper body towards the ground by bending your elbows, keeping them close to your body. As you lower down, shift your weight forward and transition into a cobra pose by straightening your arms and lifting your chest up. Reverse the movement by bending your elbows and lowering your chest back down towards the ground. Push through your hands to return to the inverted V position. Continue the movement by lowering your hips back down towards the ground, returning to the starting push-up position. Repeat for the desired number of repetitions.', 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Activa el core y eleva las caderas hacia el techo, formando una V invertida con tu cuerpo. Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Al bajar, desplaza el peso hacia adelante y haz la transición a una postura de cobra estirando los brazos y elevando el pecho. Invierte el movimiento flexionando los codos y bajando el pecho de nuevo hacia el suelo. Empuja con las manos para volver a la posición de V invertida. Continúa el movimiento bajando las caderas de nuevo hacia el suelo, volviendo a la posición inicial de flexión. Repite el número de repeticiones deseado.', 'core', '["core","shoulders","triceps"]'::jsonb, 'glutes', 'images/3662-XPUDTt7.jpg', 'videos/3662-XPUDTt7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1306', 'plyo push up', 'chest', 'chest', 'body weight', 'Start in a high plank position with your hands slightly wider than shoulder-width apart. Lower your chest towards the ground by bending your elbows, keeping your body in a straight line. Push explosively off the ground, using your chest muscles to propel your upper body off the ground. Land softly with your hands back in the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de plancha alta con las manos un poco más separadas que el ancho de los hombros. Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta. Empuja explosivamente contra el suelo, usando los músculos del pecho para impulsar la parte superior del cuerpo fuera del suelo. Aterriza suavemente con las manos de vuelta en la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/1306-Snj1wSv.jpg', 'videos/1306-Snj1wSv.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1687', 'posterior step to overhead reach', 'waist', 'waist', 'body weight', 'Stand with your feet hip-width apart and your arms by your sides. Take a step back with your right foot, landing on the ball of your foot. Bend your left knee and lower your body into a lunge position. As you lower into the lunge, simultaneously reach your arms overhead. Pause for a moment at the bottom of the lunge, then return to the starting position by pushing through your left heel and bringing your right foot forward. Repeat the movement on the other side, stepping back with your left foot and bending your right knee. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de las caderas y los brazos a los lados del cuerpo. Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie. Flexiona la rodilla izquierda y baja el cuerpo a una posición de zancada. Mientras bajas a la zancada, lleva simultáneamente los brazos por encima de la cabeza. Haz una pausa por un momento en la parte baja de la zancada y luego vuelve a la posición inicial empujando con el talón izquierdo y llevando el pie derecho hacia adelante. Repite el movimiento hacia el otro lado, retrocediendo con el pie izquierdo y flexionando la rodilla derecha. Continúa alternando lados durante el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","quadriceps","shoulders"]'::jsonb, 'abs', 'images/1687-ErqK3UL.jpg', 'videos/1687-ErqK3UL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1389', 'posterior tibialis stretch', 'lower legs', 'lower legs', 'rope', 'Sit on the ground with your legs extended in front of you. Loop the rope around the ball of your foot and hold the ends of the rope with your hands. Gently pull the rope towards you, flexing your foot and stretching your calf muscles. Hold the stretch for 20-30 seconds. Release the tension on the rope and relax your foot. Repeat the stretch on the other leg.', 'Siéntate en el suelo con las piernas extendidas frente a ti. Enrolla la cuerda alrededor de la planta del pie y sujeta los extremos de la cuerda con las manos. Tira suavemente de la cuerda hacia ti, flexionando el pie y estirando los músculos de la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Suelta la tensión de la cuerda y relaja el pie. Repite el estiramiento en la otra pierna.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'calves', 'images/1389-DEEqoI2.jpg', 'videos/1389-DEEqoI2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3119', 'potty squat', 'waist', 'waist', 'body weight', 'Stand with your feet shoulder-width apart, toes pointing slightly outward. Lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair. Keep your chest up and your back straight throughout the movement. Lower yourself until your thighs are parallel to the ground or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla. Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento. Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","glutes"]'::jsonb, 'abs', 'images/3119-75Bgtjy.jpg', 'videos/3119-75Bgtjy.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3132', 'potty squat with support', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart, toes pointing slightly outward. Hold onto a stable support, such as a chair or wall, for balance. Lower your body down into a squat position by bending your knees and pushing your hips back. Keep your chest up and your back straight throughout the movement. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Sujétate de un apoyo estable, como una silla o una pared, para mantener el equilibrio. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3132-b63ZzGe.jpg', 'videos/3132-b63ZzGe.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0648', 'power clean', 'upper legs', 'upper legs', 'barbell', 'Start with the barbell on the ground in front of you, with your feet shoulder-width apart. Bend down and grip the barbell with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and chest up as you lift the barbell off the ground, extending your hips and knees. As the barbell reaches your mid-thigh, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides. As the barbell reaches its highest point, quickly drop underneath it, rotating your elbows around and catching the barbell on your shoulders in a front squat position. Stand up with the barbell, fully extending your hips and knees. Lower the barbell back down to the starting position, keeping control of the weight throughout the movement. Repeat for the desired number of repetitions.', 'Comienza con la barra en el suelo frente a ti, con los pies separados a la altura de los hombros. Agáchate y agarra la barra con un agarre prono, un poco más separado que la anchura de los hombros. Mantén la espalda recta y el pecho hacia arriba al levantar la barra del suelo, extendiendo las caderas y las rodillas. Cuando la barra llegue a la mitad del muslo, tira de ella explosivamente hacia arriba, encogiendo los hombros y llevando los codos hacia arriba y hacia los lados. Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, rotando los codos y atrapando la barra sobre los hombros en una posición de sentadilla frontal. Ponte de pie con la barra, extendiendo completamente las caderas y las rodillas. Baja la barra de nuevo a la posición inicial, manteniendo el control del peso durante todo el movimiento. Repite el número de repeticiones deseado.', 'glutes', '["glutes","quadriceps","calves"]'::jsonb, 'hamstrings', 'images/0648-SiWCcTN.jpg', 'videos/0648-SiWCcTN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3665', 'power point plank', 'waist', 'waist', 'body weight', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe. Engage your core and squeeze your glutes to maintain a stable position. Lower your body down onto your forearms, one arm at a time, maintaining a straight line from head to toe. Hold this position for the desired amount of time, keeping your core and glutes engaged. To return to the starting position, push through your forearms and lift your body back up into a high plank position. Repeat for the desired number of repetitions.', 'Comienza en posición de plancha alta con las manos directamente debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies. Activa el core y aprieta los glúteos para mantener una posición estable. Baja el cuerpo hasta los antebrazos, un brazo a la vez, manteniendo una línea recta de la cabeza a los pies. Mantén esta posición durante el tiempo deseado, con el core y los glúteos activados. Para volver a la posición inicial, empuja con los antebrazos y eleva el cuerpo de nuevo a una posición de plancha alta. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps","glutes"]'::jsonb, 'abs', 'images/3665-hCjGsRQ.jpg', 'videos/3665-hCjGsRQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3203', 'prisoner half sit-up (male)', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/3203-mgejmGP.jpg', 'videos/3203-mgejmGP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1707', 'prone twist on stability ball', 'waist', 'waist', 'stability ball', 'Start by lying face down on a stability ball with your feet shoulder-width apart and your toes touching the ground. Place your hands behind your head or cross them over your chest. Engage your core muscles and slowly lift your upper body off the ball, keeping your back straight. Rotate your torso to one side, bringing your shoulder towards your hip. Keep your hips and legs stable throughout the movement. Pause for a moment, then return to the starting position. Repeat the rotation to the other side. Continue alternating sides for the desired number of repetitions.', 'Comienza tumbándote boca abajo sobre un balón de estabilidad con los pies separados a la altura de los hombros y los dedos de los pies tocando el suelo. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa los músculos del core y eleva lentamente la parte superior del cuerpo del balón, manteniendo la espalda recta. Rota el torso hacia un lado, llevando el hombro hacia la cadera. Mantén las caderas y las piernas estables durante todo el movimiento. Haz una pausa breve y luego vuelve a la posición inicial. Repite la rotación hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/1707-1IG6gVF.jpg', 'videos/1707-1IG6gVF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0651', 'pull up (neutral grip)', 'back', 'back', 'body weight', 'Hang from a pull-up bar with a neutral grip (palms facing each other) and your arms fully extended. Engage your core and squeeze your shoulder blades together. Pull your body up towards the bar by bending your elbows and driving your elbows down towards your hips. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position with control. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con un agarre neutro (las palmas enfrentadas) y los brazos completamente extendidos. Activa el core y junta los omóplatos. Tira de tu cuerpo hacia la barra flexionando los codos y llevándolos hacia las caderas. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte alta y luego baja lentamente tu cuerpo, con control, hasta la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0651-0V2YQjW.jpg', 'videos/0651-0V2YQjW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0650', 'pull-in (on stability ball)', 'waist', 'waist', 'stability ball', 'Start by sitting on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Place your hands on the sides of the stability ball for support. Engage your abs and slowly roll your hips forward, bringing your knees towards your chest. Pause for a moment at the top of the movement, then slowly extend your legs back to the starting position. Repeat for the desired number of repetitions.', 'Comienza sentándote en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas a un ángulo de 90 grados. Coloca las manos a los lados del balón de estabilidad para mayor apoyo. Activa el abdomen y rueda lentamente las caderas hacia adelante, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte alta del movimiento y luego extiende lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0650-UQr48Oi.jpg', 'videos/0650-UQr48Oi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0652', 'pull-up', 'back', 'back', 'body weight', 'Hang from a pull-up bar with your palms facing away from you and your arms fully extended. Engage your core and squeeze your shoulder blades together. Pull your body up towards the bar by bending your elbows and bringing your chest towards the bar. Pause at the top of the movement, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos. Activa el core y junta los omóplatos. Tira de tu cuerpo hacia la barra flexionando los codos y llevando el pecho hacia la barra. Haz una pausa en la parte alta del movimiento y luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0652-lBDjFxJ.jpg', 'videos/0652-lBDjFxJ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1689', 'push and pull bodyweight', 'chest', 'chest', 'body weight', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your body in a straight line. Lower your chest towards the ground by bending your elbows, keeping your body straight. Push through your palms to extend your arms and return to the starting position. From the push-up position, pull your chest towards the ground by bending your elbows, keeping your body straight. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Desde la posición de flexión, tira del pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","deltoids"]'::jsonb, 'pectorals', 'images/1689-wXvUZC8.jpg', 'videos/1689-wXvUZC8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3638', 'push to run', 'cardio', 'cardio', 'body weight', 'Start in a push-up position with your hands shoulder-width apart and your body in a straight line. Lower your chest towards the ground by bending your elbows, keeping your body straight. Push through your hands to extend your arms and return to the starting position. Quickly bring one knee towards your chest, then quickly switch and bring the other knee towards your chest. Continue alternating knees as fast as you can while maintaining good form. Continue for the desired duration or number of repetitions.', 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo flexionando los codos, manteniendo el cuerpo recto. Empuja con las manos para extender los brazos y volver a la posición inicial. Lleva rápidamente una rodilla hacia el pecho, luego cambia rápidamente y lleva la otra rodilla hacia el pecho. Continúa alternando las rodillas tan rápido como puedas manteniendo una buena forma. Continúa durante el tiempo o el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/3638-PrQbjvB.jpg', 'videos/3638-PrQbjvB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1307', 'push up on bosu ball', 'chest', 'chest', 'bosu ball', 'Place the bosu ball on the ground with the flat side facing up. Position yourself in a push-up position with your hands on the outer edges of the bosu ball. Engage your core and lower your body down towards the bosu ball by bending your elbows. Push yourself back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', 'Coloca el bosu en el suelo con el lado plano hacia arriba. Colócate en posición de flexión con las manos en los bordes exteriores del bosu. Activa el core y baja el cuerpo hacia el bosu flexionando los codos. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/1307-wVompEp.jpg', 'videos/1307-wVompEp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0662', 'push-up', 'chest', 'chest', 'body weight', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together. Engage your core and lower your body towards the ground by bending your elbows, keeping your body in a straight line. Pause for a moment when your chest is just above the ground, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo el cuerpo en línea recta. Haz una pausa cuando el pecho esté justo por encima del suelo y luego empújate de vuelta a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","deltoids","core"]'::jsonb, 'pectorals', 'images/0662-I4hDWkc.jpg', 'videos/0662-I4hDWkc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0653', 'push-up (bosu ball)', 'chest', 'chest', 'bosu ball', 'Place the bosu ball on the ground with the flat side facing up. Position yourself in a push-up position with your hands on the outer edges of the bosu ball. Engage your core and lower your body down towards the bosu ball by bending your elbows. Push yourself back up to the starting position by extending your arms. Repeat for the desired number of repetitions.', 'Coloca el bosu en el suelo con el lado plano hacia arriba. Colócate en posición de flexión con las manos en los bordes exteriores del bosu. Activa el core y baja el cuerpo hacia el bosu flexionando los codos. Empuja tu cuerpo de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/0653-2kr2lWy.jpg', 'videos/0653-2kr2lWy.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0655', 'push-up (on stability ball)', 'chest', 'chest', 'stability ball', 'Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart. Extend your legs straight out behind you, balancing on your toes. Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Coloca el balón de estabilidad en el suelo y ponte boca abajo con las manos sobre el balón, separadas a la altura de los hombros. Extiende las piernas rectas detrás de ti, equilibrándote sobre los dedos de los pies. Activa el core y baja el pecho hacia el balón flexionando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/0655-Y4BRNQF.jpg', 'videos/0655-Y4BRNQF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0656', 'push-up (on stability ball)', 'chest', 'chest', 'stability ball', 'Place the stability ball on the ground and position yourself facing down with your hands on the ball, shoulder-width apart. Extend your legs straight out behind you, balancing on your toes. Engage your core and lower your chest towards the ball by bending your elbows, keeping your body in a straight line. Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Coloca el balón de estabilidad en el suelo y ponte boca abajo con las manos sobre el balón, separadas a la altura de los hombros. Extiende las piernas rectas detrás de ti, equilibrándote sobre los dedos de los pies. Activa el core y baja el pecho hacia el balón flexionando los codos, manteniendo el cuerpo en línea recta. Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/0656-tgryw5Y.jpg', 'videos/0656-tgryw5Y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0659', 'push-up (wall)', 'chest', 'chest', 'body weight', 'Stand facing a wall, about arm''s length away. Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart. Step back a few feet, keeping your body straight and your feet hip-width apart. Bend your elbows and lower your chest towards the wall, keeping your body in a straight line. Push back up to the starting position, straightening your arms. Repeat for the desired number of repetitions.', 'Ponte de pie frente a una pared, a una distancia aproximada de un brazo. Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros. Da un paso atrás, manteniendo el cuerpo recto y los pies separados a la altura de las caderas. Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo en línea recta. Empuja de vuelta a la posición inicial, estirando los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","deltoids"]'::jsonb, 'pectorals', 'images/0659-LEH9jxP.jpg', 'videos/0659-LEH9jxP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0658', 'push-up (wall) v. 2', 'chest', 'chest', 'body weight', 'Stand facing a wall, about arm''s length away. Place your hands on the wall at shoulder height, slightly wider than shoulder-width apart. Step back with your feet, keeping them hip-width apart. Engage your core and keep your body in a straight line from head to heels. Bend your elbows and lower your chest towards the wall, keeping your body straight. Pause for a moment, then push yourself back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a una pared, a una distancia aproximada de un brazo. Coloca las manos en la pared a la altura de los hombros, un poco más separadas que la anchura de los hombros. Retrocede con los pies, manteniéndolos separados a la altura de las caderas. Activa el core y mantén el cuerpo en línea recta desde la cabeza hasta los talones. Flexiona los codos y baja el pecho hacia la pared, manteniendo el cuerpo recto. Haz una pausa por un momento y luego empújate de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0658-NCmbLCw.jpg', 'videos/0658-NCmbLCw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0660', 'push-up close-grip off dumbbell', 'upper arms', 'upper arms', 'dumbbell', 'Start in a push-up position with your hands placed close together, directly under your shoulders. Hold a dumbbell in each hand, resting them on the ground. Lower your body towards the ground by bending your elbows, keeping them close to your sides. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de flexión con las manos juntas, directamente debajo de los hombros. Sostén una mancuerna en cada mano, apoyándolas en el suelo. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0660-KZXAtKQ.jpg', 'videos/0660-KZXAtKQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0661', 'push-up inside leg kick', 'upper legs', 'upper legs', 'body weight', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together. Lower your body towards the ground by bending your elbows, keeping your back straight and your core engaged. As you push back up, lift one leg off the ground and kick it out to the side, keeping it straight. Lower your leg back down and repeat the push-up, then switch to the other leg. Continue alternating leg kicks with each push-up repetition.', 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado. Al empujar de vuelta hacia arriba, levanta una pierna del suelo y lánzala hacia el lado, manteniéndola recta. Baja la pierna de nuevo y repite la flexión, luego cambia a la otra pierna. Continúa alternando las patadas de pierna en cada repetición de la flexión.', 'quadriceps', '["quadriceps","hamstrings","calves","core"]'::jsonb, 'glutes', 'images/0661-0br45wL.jpg', 'videos/0661-0br45wL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0663', 'push-up medicine ball', 'chest', 'chest', 'medicine ball', 'Start in a high plank position with your hands on the medicine ball, shoulder-width apart. Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/0663-W8KAlkI.jpg', 'videos/0663-W8KAlkI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1467', 'push-up on lower arms', 'upper arms', 'upper arms', 'body weight', 'Start in a plank position with your forearms on the ground and elbows directly below your shoulders. Engage your core and keep your body in a straight line from head to toe. Lower your chest towards the ground by bending your elbows, keeping them close to your body. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de plancha con los antebrazos en el suelo y los codos directamente debajo de los hombros. Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1467-4Jt8QsQ.jpg', 'videos/1467-4Jt8QsQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3145', 'push-up plus', 'chest', 'chest', 'body weight', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels. Lower your body towards the ground by bending your elbows, keeping them close to your sides. Once your chest is just above the ground, push through your hands to extend your arms and lift your upper body up. At the top of the movement, protract your shoulder blades by pushing your upper back towards the ceiling. Pause for a moment, then reverse the movement by retracting your shoulder blades and lowering your body back down to the starting position. Repeat for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Cuando el pecho esté justo por encima del suelo, empuja con las manos para extender los brazos y levantar la parte superior del cuerpo. En la parte alta del movimiento, separa las escápulas empujando la parte superior de la espalda hacia el techo. Haz una pausa por un momento y luego invierte el movimiento juntando las escápulas y bajando el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/3145-pvBMLHA.jpg', 'videos/3145-pvBMLHA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0664', 'push-up to side plank', 'waist', 'waist', 'body weight', 'Start in a push-up position with your hands shoulder-width apart and your body in a straight line. Lower your body towards the ground by bending your elbows, keeping your core engaged. Push back up to the starting position. Shift your weight onto your left hand and rotate your body to the right, lifting your right arm towards the ceiling. Hold the side plank position for a few seconds, then return to the starting position. Repeat the push-up and side plank on the opposite side. Continue alternating sides for the desired number of repetitions.', 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y el cuerpo en línea recta. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo el core activado. Empuja hacia arriba para volver a la posición inicial. Desplaza el peso hacia la mano izquierda y rota el cuerpo hacia la derecha, elevando el brazo derecho hacia el techo. Mantén la posición de plancha lateral durante unos segundos y luego vuelve a la posición inicial. Repite la flexión y la plancha lateral en el lado opuesto. Continúa alternando lados durante el número de repeticiones deseado.', 'shoulders', '["shoulders","chest","triceps"]'::jsonb, 'abs', 'images/0664-KhHJ338.jpg', 'videos/0664-KhHJ338.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3533', 'quads', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart. Lower your body by bending your knees and pushing your hips back as if sitting on a chair. Keep your chest up and your back straight. Lower yourself until your thighs are parallel to the ground. Push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo flexionando las rodillas y empujando las caderas hacia atrás como si te sentaras en una silla. Mantén el pecho arriba y la espalda recta. Baja hasta que los muslos queden paralelos al suelo. Empuja con los talones para volver a ponerte de pie en la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'quads', 'images/3533-6YUfHPL.jpg', 'videos/3533-6YUfHPL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3201', 'quarter sit-up', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/3201-enxnJcM.jpg', 'videos/3201-enxnJcM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3552', 'quick feet v. 2', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart and your arms by your sides. Begin by rapidly moving your feet up and down, as if you were running in place. Keep your movements quick and light, focusing on staying on the balls of your feet. Continue for the desired duration or number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados. Comienza moviendo los pies rápidamente hacia arriba y hacia abajo, como si estuvieras corriendo en el sitio. Mantén los movimientos rápidos y ligeros, concentrándote en quedarte sobre la punta de los pies. Continúa durante el tiempo o el número de repeticiones deseado.', 'calves', '["calves","hamstrings"]'::jsonb, 'quads', 'images/3552-mweqJin.jpg', 'videos/3552-mweqJin.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0666', 'raise single arm push-up', 'chest', 'chest', 'body weight', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together. Extend one arm straight out to the side, parallel to the ground. Lower your body towards the ground by bending your elbows, keeping your back straight and core engaged. Push back up to the starting position, using your chest muscles to lift your body. Repeat with the other arm extended.', 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Extiende un brazo hacia el lado, paralelo al suelo. Baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta y el core activado. Empuja de vuelta a la posición inicial, usando los músculos del pecho para elevar el cuerpo. Repite con el otro brazo extendido.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/0666-13TpY4H.jpg', 'videos/0666-13TpY4H.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0668', 'rear decline bridge', 'upper legs', 'upper legs', 'body weight', 'Lie on your back with your feet flat on the ground and your knees bent. Place your arms by your sides with your palms facing down. Engage your glutes and hamstrings, and lift your hips off the ground until your body forms a straight line from your knees to your shoulders. Hold this position for a few seconds, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba con los pies planos en el suelo y las rodillas flexionadas. Coloca los brazos a los lados del cuerpo con las palmas hacia abajo. Activa los glúteos y los isquiotibiales, y eleva las caderas del suelo hasta que tu cuerpo forme una línea recta desde las rodillas hasta los hombros. Mantén esta posición durante unos segundos y luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0668-UpAlold.jpg', 'videos/0668-UpAlold.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0669', 'rear deltoid stretch', 'shoulders', 'shoulders', 'body weight', 'Stand tall with your feet shoulder-width apart. Extend your right arm across your chest, placing your left hand on your right elbow. Gently pull your right arm towards your left shoulder, feeling a stretch in your right shoulder. Hold the stretch for 15-30 seconds, then release. Repeat on the other side.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende el brazo derecho a través del pecho, colocando la mano izquierda sobre el codo derecho. Tira suavemente del brazo derecho hacia el hombro izquierdo, sintiendo un estiramiento en el hombro derecho. Mantén el estiramiento durante 15-30 segundos, luego suelta. Repite del otro lado.', 'trapezius', '["trapezius","rhomboids"]'::jsonb, 'delts', 'images/0669-xifhB5W.jpg', 'videos/0669-xifhB5W.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0670', 'rear pull-up', 'back', 'back', 'body weight', 'Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0670-CbFSYC1.jpg', 'videos/0670-CbFSYC1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1582', 'reclining big toe pose with rope', 'upper legs', 'upper legs', 'rope', 'Lie on your back with your legs extended and your arms by your sides. Loop the rope around the ball of your right foot and hold the ends of the rope with your hands. Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed. Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position. Repeat with your left leg. Continue alternating legs for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Enrolla la cuerda alrededor de la planta del pie derecho y sujeta los extremos de la cuerda con las manos. Eleva lentamente la pierna derecha hacia el pecho, manteniendo la rodilla recta y el pie flexionado. Mantén el estiramiento durante unos segundos y luego baja lentamente la pierna de vuelta a la posición inicial. Repite con la pierna izquierda. Continúa alternando las piernas durante el número de repeticiones deseado.', 'calves', '["calves","glutes"]'::jsonb, 'hamstrings', 'images/1582-K5xgdvI.jpg', 'videos/1582-K5xgdvI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3236', 'resistance band hip thrusts on knees (female)', 'upper legs', 'upper legs', 'resistance band', 'Start by kneeling on the ground with your knees hip-width apart and your feet flexed. Wrap the resistance band around your thighs, just above your knees. Place your hands on your hips or extend them out in front of you for balance. Engage your glutes and core muscles. Push your hips forward and squeeze your glutes as you lift your knees off the ground, extending your hips until your thighs are parallel to the ground. Hold the position for a moment, then slowly lower your knees back down to the starting position. Repeat for the desired number of repetitions.', 'Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas y los pies flexionados. Envuelve la banda elástica alrededor de los muslos, justo por encima de las rodillas. Coloca las manos en las caderas o extiéndelas frente a ti para mantener el equilibrio. Activa los glúteos y los músculos del core. Empuja las caderas hacia adelante y aprieta los glúteos mientras levantas las rodillas del suelo, extendiendo las caderas hasta que los muslos queden paralelos al suelo. Mantén la posición por un momento y luego baja lentamente las rodillas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/3236-Pjbc0Kt.jpg', 'videos/3236-Pjbc0Kt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3007', 'resistance band leg extension', 'upper legs', 'upper legs', 'resistance band', 'Attach the resistance band to a sturdy anchor point and secure it around your ankle. Stand facing the anchor point with your feet shoulder-width apart. Keeping your core engaged and your upper body stable, extend your leg straight out in front of you. Pause for a moment at the top, then slowly return your leg to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Sujeta la banda elástica a un punto de anclaje firme y asegúrala alrededor de tu tobillo. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Manteniendo el core activado y la parte superior del cuerpo estable, extiende la pierna recta frente a ti. Haz una pausa por un momento en la parte alta y luego vuelve lentamente la pierna a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'hamstrings', '["hamstrings"]'::jsonb, 'quads', 'images/3007-Y1MsI1l.jpg', 'videos/3007-Y1MsI1l.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3123', 'resistance band seated biceps curl', 'upper arms', 'upper arms', 'resistance band', 'Sit on a chair or bench with your back straight and feet flat on the ground. Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides. Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the resistance band back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Sostén la banda elástica con un agarre supino, con las palmas hacia arriba y los brazos extendidos a los lados del cuerpo. Manteniendo la parte superior de los brazos inmóvil, exhala y flexiona la banda elástica hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la banda elástica de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/3123-XFc3vpY.jpg', 'videos/3123-XFc3vpY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3124', 'resistance band seated chest press', 'chest', 'chest', 'resistance band', 'Sit on a chair or bench with your back straight and feet flat on the ground. Hold the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle. Extend your arms forward, pushing the resistance band away from your chest. Pause for a moment at the end of the movement, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Sostén las asas de la banda elástica en cada mano, con las palmas hacia abajo y los codos flexionados en un ángulo de 90 grados. Extiende los brazos hacia adelante, alejando la banda elástica de tu pecho. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/3124-4x5Okof.jpg', 'videos/3124-4x5Okof.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3006', 'resistance band seated hip abduction', 'upper legs', 'upper legs', 'resistance band', 'Sit on a chair or bench with your back straight and feet flat on the ground. Wrap the resistance band around your thighs, just above your knees. Place your hands on the sides of the chair or bench for support. Engage your abductors (outer thigh muscles) and slowly push your knees apart, against the resistance of the band. Pause for a moment at the end of the movement, then slowly bring your knees back together. Repeat for the desired number of repetitions.', 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Envuelve la banda elástica alrededor de los muslos, justo por encima de las rodillas. Coloca las manos en los lados de la silla o el banco para mayor apoyo. Activa los abductores (los músculos externos del muslo) y empuja lentamente las rodillas hacia afuera, contra la resistencia de la banda. Haz una pausa al final del movimiento y luego junta lentamente las rodillas de nuevo. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'abductors', 'images/3006-0xDpB4L.jpg', 'videos/3006-0xDpB4L.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3122', 'resistance band seated shoulder press', 'shoulders', 'shoulders', 'resistance band', 'Sit on a chair or bench with your back straight and feet flat on the ground. Hold the resistance band with both hands, palms facing forward, and bring it up to shoulder level. Press the band overhead, extending your arms fully. Pause for a moment at the top, then slowly lower the band back down to shoulder level. Repeat for the desired number of repetitions.', 'Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo. Sostén la banda elástica con ambas manos, con las palmas hacia adelante, y elévala hasta la altura de los hombros. Empuja la banda por encima de la cabeza, extendiendo completamente los brazos. Haz una pausa por un momento en la parte alta y luego baja lentamente la banda hasta la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/3122-S93zLTG.jpg', 'videos/3122-S93zLTG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3144', 'resistance band seated straight back row', 'back', 'back', 'resistance band', 'Sit on the floor with your legs extended and loop the resistance band around your feet. Hold the ends of the resistance band with your hands, palms facing each other. Keep your back straight and lean slightly back, engaging your core. Pull the resistance band towards your chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly release the tension and return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el suelo con las piernas extendidas y enrolla la banda elástica alrededor de los pies. Sostén los extremos de la banda elástica con las manos, con las palmas enfrentadas. Mantén la espalda recta e inclínate ligeramente hacia atrás, activando el core. Tira de la banda elástica hacia el pecho, juntando las escápulas. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/3144-Nu7jqFE.jpg', 'videos/3144-Nu7jqFE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0872', 'reverse crunch', 'waist', 'waist', 'body weight', 'Lie flat on your back with your arms extended along your sides. Bend your knees and lift your feet off the ground, bringing your thighs perpendicular to the floor. Contract your abs and curl your hips off the floor, bringing your knees towards your chest. Pause for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba con los brazos extendidos a los lados del cuerpo. Flexiona las rodillas y levanta los pies del suelo, llevando los muslos perpendiculares al suelo. Contrae el abdomen y eleva las caderas del suelo, llevando las rodillas hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0872-nCU1Ekp.jpg', 'videos/0872-nCU1Ekp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0672', 'reverse dip', 'upper arms', 'upper arms', 'body weight', 'Position yourself between two parallel bars with your arms fully extended and your body straight. Lower your body by bending your elbows until your upper arms are parallel to the ground. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0672-NZ5Qqkz.jpg', 'videos/0672-NZ5Qqkz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0673', 'reverse grip machine lat pulldown', 'back', 'back', 'leverage machine', 'Adjust the seat height and position yourself on the machine with your knees under the pads and your feet flat on the ground. Grasp the handles with an underhand grip, slightly wider than shoulder-width apart. Sit upright with your chest out and shoulders back, maintaining a slight arch in your lower back. Pull the handles down towards your chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con las rodillas debajo de las almohadillas y los pies planos en el suelo. Sujeta las asas con un agarre supino, un poco más separadas que la altura de los hombros. Siéntate erguido con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar. Tira de las asas hacia el pecho, juntando las escápulas. Haz una pausa breve en la parte baja del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0673-ecpY0rH.jpg', 'videos/0673-ecpY0rH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0674', 'reverse grip pull-up', 'back', 'back', 'body weight', 'Grab the pull-up bar with an underhand grip, hands shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your back muscles and pull your body up towards the bar, leading with your chest. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Agarra la barra de dominadas con un agarre supino, con las manos separadas a la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0674-YAk5dIw.jpg', 'videos/0674-YAk5dIw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0675', 'reverse hyper extension (on stability ball)', 'upper legs', 'upper legs', 'stability ball', 'Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you. Place your hands on the ground in front of you for stability. Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y las piernas extendidas rectas detrás de ti. Coloca las manos en el suelo frente a ti para mayor estabilidad. Activando los glúteos y los isquiotibiales, eleva las piernas hacia el techo tan alto como puedas. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0675-vM5YS2g.jpg', 'videos/0675-vM5YS2g.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1423', 'reverse hyper on flat bench', 'upper legs', 'upper legs', 'body weight', 'Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench. Hold onto the bench for stability. Keeping your legs straight, raise them up towards the ceiling as high as you can. Squeeze your glutes at the top of the movement. Slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo en un banco plano con las caderas en el borde y las piernas colgando del banco. Sujétate del banco para mantener la estabilidad. Manteniendo las piernas rectas, elévalas hacia el techo tan alto como puedas. Aprieta los glúteos en la parte alta del movimiento. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/1423-OrETs32.jpg', 'videos/1423-OrETs32.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3663', 'reverse plank with leg lift', 'waist', 'waist', 'body weight', 'Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet. Press through your hands and lift your hips off the ground, coming into a reverse plank position. Engage your core and lift one leg off the ground, extending it straight up towards the ceiling. Hold for a moment, then lower your leg back down. Repeat with the other leg. Continue alternating legs for the desired number of repetitions.', 'Siéntate en el suelo con las piernas extendidas frente a ti y las manos apoyadas en el suelo detrás de ti, con los dedos apuntando hacia los pies. Presiona con las manos y levanta las caderas del suelo, llegando a una posición de plancha inversa. Activa el core y levanta una pierna del suelo, extendiéndola recta hacia el techo. Mantén la posición por un momento y luego baja la pierna de nuevo. Repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","shoulders"]'::jsonb, 'abs', 'images/3663-tFToB7l.jpg', 'videos/3663-tFToB7l.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0677', 'ring dips', 'upper arms', 'upper arms', 'body weight', 'Start by hanging from the rings with your arms fully extended and your body straight. Lower your body by bending your elbows until your shoulders are below your elbows. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Comienza colgándote de las anillas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0677-ezTvXcr.jpg', 'videos/0677-ezTvXcr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2571', 'rocking frog stretch', 'upper legs', 'upper legs', 'body weight', 'Start by kneeling on the ground with your knees hip-width apart. Place your hands on the ground in front of you for support. Slowly lean forward, shifting your weight onto your hands and extending your legs behind you. Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling. Hold this position for a few seconds, feeling a stretch in your glutes. Slowly return to the starting position by bending your knees and lowering your hips back down. Repeat for the desired number of repetitions.', 'Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas. Coloca las manos en el suelo frente a ti para mayor apoyo. Inclínate lentamente hacia adelante, desplazando el peso hacia las manos y extendiendo las piernas detrás de ti. Mantén la espalda recta y activa los glúteos mientras empujas las caderas hacia atrás y hacia arriba en dirección al techo. Mantén esta posición durante unos segundos, sintiendo un estiramiento en los glúteos. Vuelve lentamente a la posición inicial flexionando las rodillas y bajando las caderas de nuevo. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/2571-2Dk4xQV.jpg', 'videos/2571-2Dk4xQV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0678', 'rocky pull-up pulldown', 'back', 'back', 'body weight', 'Stand in front of a pull-up bar with your feet shoulder-width apart. Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your back muscles and pull your body up towards the bar, leading with your chest. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a una barra de dominadas con los pies separados a la altura de los hombros. Estira los brazos hacia arriba y agarra la barra con agarre prono, ligeramente más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0678-cQ19bBP.jpg', 'videos/0678-cQ19bBP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2208', 'roller back stretch', 'back', 'back', 'roller', 'Start by sitting on the ground with your legs extended in front of you. Place the roller perpendicular to your body, just below your glutes. Slowly roll your body backwards, allowing the roller to move up your back. Continue rolling until the roller reaches your upper back. Pause for a moment, then slowly roll back to the starting position. Repeat for the desired number of repetitions.', 'Comienza sentándote en el suelo con las piernas extendidas frente a ti. Coloca el rodillo perpendicular a tu cuerpo, justo debajo de los glúteos. Rueda lentamente el cuerpo hacia atrás, dejando que el rodillo se desplace hacia arriba por tu espalda. Continúa rodando hasta que el rodillo llegue a la parte superior de tu espalda. Haz una pausa por un momento y luego rueda lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'spine', 'images/2208-isofgzg.jpg', 'videos/2208-isofgzg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2204', 'roller body saw', 'waist', 'waist', 'roller', 'Start in a plank position with your forearms on the roller and your body in a straight line. Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control. Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de plancha con los antebrazos sobre el rodillo y el cuerpo en línea recta. Activa el core y rueda lentamente el rodillo hacia adelante, extendiendo el cuerpo tanto como puedas mientras mantienes el control. Haz una pausa por un momento en el punto más lejano y luego rueda lentamente el rodillo de vuelta hacia tu posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps","core"]'::jsonb, 'abs', 'images/2204-XeMvLgE.jpg', 'videos/2204-XeMvLgE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2205', 'roller hip lat stretch', 'upper legs', 'upper legs', 'roller', 'Start by kneeling on the ground with the roller positioned under your hips. Place your hands on the roller for support. Slowly roll the roller forward, extending your hips and stretching your glutes. Hold the stretch for a few seconds, then roll back to the starting position. Repeat for the desired number of repetitions.', 'Comienza arrodillándote en el suelo con el rodillo colocado debajo de las caderas. Coloca las manos sobre el rodillo para mayor apoyo. Rueda lentamente el rodillo hacia adelante, extendiendo las caderas y estirando los glúteos. Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/2205-0L2KwtI.jpg', 'videos/2205-0L2KwtI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2202', 'roller hip stretch', 'upper legs', 'upper legs', 'roller', 'Start by sitting on the ground with your legs extended in front of you. Place the roller under your glutes, just above your knees. Lean back and place your hands on the ground behind you for support. Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest. Pause for a moment at the end of the movement, feeling a stretch in your glutes. Slowly roll the roller back to the starting position, extending your legs. Repeat for the desired number of repetitions.', 'Comienza sentándote en el suelo con las piernas extendidas frente a ti. Coloca el rodillo debajo de los glúteos, justo por encima de las rodillas. Inclínate hacia atrás y coloca las manos en el suelo detrás de ti para apoyarte. Activa los glúteos y rueda lentamente el rodillo hacia adelante, flexionando las rodillas y llevándolas hacia el pecho. Haz una pausa al final del movimiento, sintiendo un estiramiento en los glúteos. Rueda lentamente el rodillo de vuelta a la posición inicial, extendiendo las piernas. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/2202-oMypNrz.jpg', 'videos/2202-oMypNrz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2206', 'roller reverse crunch', 'waist', 'waist', 'roller', 'Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you. Place the roller between your feet and grip it with your toes. Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body. Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body. Repeat for the desired number of repetitions.', 'Túmbate boca arriba con los brazos extendidos rectos por encima de la cabeza y las piernas rectas frente a ti. Coloca el rodillo entre los pies y sujétalo con los dedos de los pies. Activando el abdomen, levanta las piernas del suelo y flexiona las rodillas hacia el pecho, rodando el rodillo hacia tu cuerpo. Haz una pausa por un momento en la parte alta y luego baja lentamente las piernas de vuelta a la posición inicial, rodando el rodillo alejándolo de tu cuerpo. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/2206-SKXQAx3.jpg', 'videos/2206-SKXQAx3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2203', 'roller seated shoulder flexor depresor retractor', 'chest', 'chest', 'roller', 'Sit on a flat surface with your legs extended in front of you. Hold the roller with both hands, palms facing down, and place it on your thighs. Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you. Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs. Repeat for the desired number of repetitions.', 'Siéntate sobre una superficie plana con las piernas extendidas frente a ti. Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos. Inclínate ligeramente hacia delante y aleja el rodillo de tu cuerpo, extendiendo los brazos rectos frente a ti. Haz una pausa por un momento, luego rueda el rodillo lentamente de vuelta hacia tu cuerpo, doblando los brazos y trayéndolo de nuevo hacia los muslos. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/2203-8coXSYU.jpg', 'videos/2203-8coXSYU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2209', 'roller seated single leg shoulder flexor depresor retractor', 'chest', 'chest', 'roller', 'Sit on a flat surface with your legs extended in front of you. Hold the roller with both hands, palms facing down, and place it on your thighs. Lean back slightly and engage your core muscles. Raise the roller up to shoulder level, keeping your arms straight. Slowly lower the roller back down to your thighs. Repeat for the desired number of repetitions.', 'Siéntate sobre una superficie plana con las piernas extendidas frente a ti. Sostén el rodillo con ambas manos, con las palmas hacia abajo, y colócalo sobre tus muslos. Inclínate ligeramente hacia atrás y contrae los músculos del core. Eleva el rodillo hasta la altura de los hombros, manteniendo los brazos rectos. Baja lentamente el rodillo de nuevo hacia los muslos. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","triceps"]'::jsonb, 'pectorals', 'images/2209-CjETvlw.jpg', 'videos/2209-CjETvlw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2207', 'roller side lat stretch', 'back', 'back', 'roller', 'Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats. Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta el rodillo con ambas manos frente al cuerpo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Extiende los brazos hacia delante y rueda el rodillo hacia los pies, sintiendo un estiramiento en los dorsales. Mantén el estiramiento durante unos segundos, luego rueda el rodillo lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'lats', 'images/2207-c3Pfhti.jpg', 'videos/2207-c3Pfhti.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0680', 'rope climb', 'back', 'back', 'rope', 'Stand facing the rope with your feet shoulder-width apart. Grab the rope with both hands, palms facing towards you. Bend your knees slightly and engage your core. Begin pulling yourself up the rope by alternating hand-over-hand movements. Use your legs to assist in the upward movement. Continue climbing until you reach the desired height or the top of the rope. To descend, reverse the hand-over-hand movement while controlling your descent. Repeat for the desired number of repetitions.', 'Ponte de pie frente a la cuerda con los pies separados a la altura de los hombros. Sujeta la cuerda con ambas manos, con las palmas mirando hacia ti. Flexiona ligeramente las rodillas y activa el core. Comienza a subir por la cuerda alternando los movimientos de las manos. Usa las piernas para ayudar en el movimiento ascendente. Continúa trepando hasta alcanzar la altura deseada o la parte superior de la cuerda. Para descender, invierte el movimiento alterno de las manos mientras controlas tu descenso. Repite el número de repeticiones deseado.', 'forearms', '["forearms","biceps","shoulders"]'::jsonb, 'upper back', 'images/0680-yaAxcQr.jpg', 'videos/0680-yaAxcQr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0685', 'run', 'cardio', 'cardio', 'body weight', 'Start by standing upright with your feet hip-width apart. Engage your core and keep your upper body relaxed. Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet. Maintain a steady pace and continue jogging for the desired duration or distance. Remember to breathe deeply and maintain good posture throughout the exercise.', 'Comienza de pie con los pies separados a la altura de la cadera. Activa el core y mantén la parte superior del cuerpo relajada. Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies. Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada. Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/0685-oLrKqDH.jpg', 'videos/0685-oLrKqDH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0684', 'run (equipment)', 'cardio', 'cardio', 'body weight', 'Start by standing upright with your feet hip-width apart. Engage your core and keep your upper body relaxed. Begin jogging in place, lifting your knees up towards your chest and landing softly on the balls of your feet. Maintain a steady pace and continue jogging for the desired duration or distance. Remember to breathe deeply and maintain good posture throughout the exercise.', 'Comienza de pie con los pies separados a la altura de la cadera. Activa el core y mantén la parte superior del cuerpo relajada. Comienza a trotar en el lugar, levantando las rodillas hacia el pecho y aterrizando suavemente sobre la punta de los pies. Mantén un ritmo constante y continúa trotando durante la duración o distancia deseada. Recuerda respirar profundamente y mantener una buena postura durante todo el ejercicio.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/0684-y5p0H8a.jpg', 'videos/0684-y5p0H8a.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1585', 'runners stretch', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet hip-width apart. Take a step forward with your right foot, keeping your left foot planted. Bend your right knee and lower your body down, keeping your left leg straight. Place your hands on your right thigh for support. Hold the stretch for 20-30 seconds, then switch sides and repeat.', 'Ponte de pie con los pies separados a la altura de la cadera. Da un paso hacia delante con el pie derecho, manteniendo el pie izquierdo firme en el suelo. Dobla la rodilla derecha y baja el cuerpo, manteniendo la pierna izquierda recta. Coloca las manos sobre el muslo derecho para apoyarte. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', 'calves', '["calves","quadriceps"]'::jsonb, 'hamstrings', 'images/1585-0mB6wHO.jpg', 'videos/1585-0mB6wHO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0687', 'russian twist', 'waist', 'waist', 'body weight', 'Sit on the ground with your knees bent and feet flat on the floor. Lean back slightly while keeping your back straight and your core engaged. Hold your hands together in front of your chest or hold a weight if desired. Lift your feet off the ground, balancing on your sit bones. Twist your torso to the right, bringing your hands or weight towards the right side of your body. Pause for a moment, then twist your torso to the left, bringing your hands or weight towards the left side of your body. Continue alternating sides for the desired number of repetitions.', 'Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo. Inclínate ligeramente hacia atrás manteniendo la espalda recta y el core activado. Junta las manos frente al pecho o sujeta una pesa si lo deseas. Levanta los pies del suelo, equilibrándote sobre los isquiones. Gira el torso hacia la derecha, llevando las manos o la pesa hacia el lado derecho del cuerpo. Haz una pausa por un momento, luego gira el torso hacia la izquierda, llevando las manos o la pesa hacia el lado izquierdo del cuerpo. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0687-XVDdcoj.jpg', 'videos/0687-XVDdcoj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3012', 'scapula dips', 'back', 'back', 'body weight', 'Start by standing with your feet shoulder-width apart and your arms extended in front of you. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them. Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position. Repeat for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja el cuerpo doblando los codos y retrayendo las escápulas, como si intentaras apretar un lápiz entre ellas. Haz una pausa por un momento en la posición baja, luego empuja con las manos para extender los codos y volver a la posición inicial. Repite el número de repeticiones deseado.', 'rhomboids', '["rhomboids","deltoids"]'::jsonb, 'traps', 'images/3012-7xeukSt.jpg', 'videos/3012-7xeukSt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3021', 'scapula push-up', 'chest', 'chest', 'body weight', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Lower your chest towards the ground, keeping your elbows close to your body. As you lower, squeeze your shoulder blades together and push your chest forward. Pause for a moment at the bottom, then push back up to the starting position. Repeat for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. A medida que bajas, junta las escápulas y empuja el pecho hacia delante. Haz una pausa por un momento en la posición baja, luego empuja de nuevo hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'serratus anterior', 'images/3021-jV65tKx.jpg', 'videos/3021-jV65tKx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0688', 'scapular pull-up', 'back', 'back', 'body weight', 'Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended. Retract your shoulder blades by pulling them down and back. Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Comienza colgándote de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos. Retrae las escápulas llevándolas hacia abajo y atrás. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, enfocándote en juntar las escápulas. Haz una pausa breve en la parte superior del movimiento, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'traps', 'images/0688-uTBt1HV.jpg', 'videos/0688-uTBt1HV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3219', 'scissor jumps (male)', 'cardio', 'cardio', 'body weight', 'Stand with your feet shoulder-width apart. Jump off the ground and simultaneously cross your right leg in front of your left leg. As you land, quickly switch legs, crossing your left leg in front of your right leg. Continue alternating legs and jumping as quickly as possible. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Salta del suelo y al mismo tiempo cruza la pierna derecha por delante de la pierna izquierda. Al aterrizar, cambia rápidamente de pierna, cruzando la pierna izquierda por delante de la pierna derecha. Continúa alternando las piernas y saltando lo más rápido posible. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/3219-Eh2v5Iu.jpg', 'videos/3219-Eh2v5Iu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1390', 'seated calf stretch (male)', 'lower legs', 'lower legs', 'body weight', 'Sit on the edge of a chair or bench with your feet flat on the ground. Extend one leg straight out in front of you, keeping your heel on the ground. Lean forward slightly, feeling a stretch in your calf muscle. Hold the stretch for 20-30 seconds. Switch legs and repeat the stretch.', 'Siéntate en el borde de una silla o banco con los pies planos sobre el suelo. Extiende una pierna recta frente a ti, manteniendo el talón en el suelo. Inclínate ligeramente hacia delante, sintiendo un estiramiento en la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Cambia de pierna y repite el estiramiento.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/1390-17bqEXD.jpg', 'videos/1390-17bqEXD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1424', 'seated glute stretch', 'upper legs', 'upper legs', 'body weight', 'Sit on the ground with your legs extended in front of you. Bend your right knee and cross your right ankle over your left thigh. Place your right hand on the ground behind you for support. With your left hand, gently press down on your right knee to deepen the stretch. Hold the stretch for 30 seconds to 1 minute. Switch sides and repeat.', 'Siéntate en el suelo con las piernas extendidas frente a ti. Dobla la rodilla derecha y cruza el tobillo derecho sobre el muslo izquierdo. Coloca la mano derecha en el suelo detrás de ti para apoyarte. Con la mano izquierda, presiona suavemente la rodilla derecha para profundizar el estiramiento. Mantén el estiramiento durante 30 segundos a 1 minuto. Cambia de lado y repite.', 'hamstrings', '["hamstrings"]'::jsonb, 'glutes', 'images/1424-DeDThfG.jpg', 'videos/1424-DeDThfG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0689', 'seated leg raise', 'waist', 'waist', 'body weight', 'Sit on a flat bench with your back straight and your feet flat on the ground. Place your hands on the sides of the bench for support. Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco plano con la espalda recta y los pies planos sobre el suelo. Coloca las manos a los lados del banco para apoyarte. Manteniendo las piernas rectas, levántalas lentamente frente a ti hasta que queden paralelas al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0689-Hgs6Nl1.jpg', 'videos/0689-Hgs6Nl1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0690', 'seated lower back stretch', 'back', 'back', 'body weight', 'Sit on the edge of a chair with your feet flat on the ground. Place your hands on your thighs or on the sides of the chair for support. Slowly lean forward from your hips, keeping your back straight. Feel the stretch in your lower back and hold for 20-30 seconds. Slowly return to the starting position and repeat for the desired number of repetitions.', 'Siéntate en el borde de una silla con los pies planos sobre el suelo. Coloca las manos sobre los muslos o a los lados de la silla para apoyarte. Inclínate lentamente hacia delante desde la cadera, manteniendo la espalda recta. Siente el estiramiento en la zona lumbar y mantén la posición durante 20-30 segundos. Regresa lentamente a la posición inicial y repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'lats', 'images/0690-QFmz6ch.jpg', 'videos/0690-QFmz6ch.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2567', 'seated piriformis stretch', 'upper legs', 'upper legs', 'body weight', 'Sit on the ground with your legs extended in front of you. Bend your right knee and place your right foot on the outside of your left knee. Place your left elbow on the outside of your right knee and gently twist your torso to the right. Hold the stretch for 20-30 seconds, then switch sides and repeat.', 'Siéntate en el suelo con las piernas extendidas frente a ti. Dobla la rodilla derecha y coloca el pie derecho en la parte exterior de la rodilla izquierda. Coloca el codo izquierdo en la parte exterior de la rodilla derecha y gira suavemente el torso hacia la derecha. Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite.', 'hamstrings', '["hamstrings"]'::jsonb, 'glutes', 'images/2567-QY39eBr.jpg', 'videos/2567-QY39eBr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0691', 'seated side crunch (wall)', 'waist', 'waist', 'body weight', 'Sit on the floor with your back against a wall and your legs extended in front of you. Bend your knees and place your feet flat on the floor, hip-width apart. Place your hands behind your head with your elbows pointing outwards. Engage your abs and lean to one side, bringing your elbow towards your hip. Pause for a moment, then return to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', 'Siéntate en el suelo con la espalda contra una pared y las piernas extendidas frente a ti. Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Contrae el abdomen e inclínate hacia un lado, llevando el codo hacia la cadera. Haz una pausa breve y luego vuelve a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0691-Y9hNPcN.jpg', 'videos/0691-Y9hNPcN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1587', 'seated wide angle pose sequence', 'upper legs', 'upper legs', 'body weight', 'Sit on the ground with your legs extended in a wide angle. Flex your feet and engage your quadriceps. Place your hands on the ground behind you for support. Keeping your back straight, lean forward from your hips. Continue leaning forward until you feel a stretch in your hamstrings. Hold this position for a few breaths. Slowly release the stretch and return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el suelo con las piernas extendidas formando un ángulo amplio. Flexiona los pies y contrae los cuádriceps. Coloca las manos en el suelo detrás de ti para apoyarte. Manteniendo la espalda recta, inclínate hacia delante desde la cadera. Continúa inclinándote hacia delante hasta sentir un estiramiento en los isquiotibiales. Mantén esta posición durante unas cuantas respiraciones. Libera lentamente el estiramiento y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","calves"]'::jsonb, 'hamstrings', 'images/1587-HIgYKAB.jpg', 'videos/1587-HIgYKAB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0697', 'self assisted inverse leg curl', 'upper legs', 'upper legs', 'body weight', 'Lie flat on your back on a mat or bench with your legs extended. Place your hands by your sides or under your glutes for support. Bend your knees and lift your feet off the ground, bringing your thighs towards your chest. Pause for a moment at the top, then slowly lower your legs back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba sobre una esterilla o banco con las piernas extendidas. Coloca las manos a los lados o debajo de los glúteos para apoyarte. Dobla las rodillas y levanta los pies del suelo, llevando los muslos hacia el pecho. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","calves"]'::jsonb, 'hamstrings', 'images/0697-GwYwElT.jpg', 'videos/0697-GwYwElT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1766', 'self assisted inverse leg curl', 'upper legs', 'upper legs', 'body weight', 'Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever. Place your hands on the side handles of the machine for support. Keeping your upper body stationary, exhale and curl your legs upward as far as possible. Hold the contracted position for a brief pause as you squeeze your hamstrings. Slowly lower your legs back to the starting position while inhaling. Repeat for the desired number of repetitions.', 'Túmbate boca abajo en una máquina de curl femoral con las piernas extendidas y los tobillos enganchados bajo la palanca acolchada. Coloca las manos en las asas laterales de la máquina para apoyarte. Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia arriba lo más posible. Mantén la posición contraída durante una pausa breve mientras aprietas los isquiotibiales. Baja lentamente las piernas de vuelta a la posición inicial mientras inhalas. Repite el número de repeticiones deseado.', 'glutes', '["glutes","calves"]'::jsonb, 'hamstrings', 'images/1766-ZSY3MsL.jpg', 'videos/1766-ZSY3MsL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0696', 'self assisted inverse leg curl (on floor)', 'upper legs', 'upper legs', 'body weight', 'Lie flat on your back with your legs extended and your arms by your sides. Bend your knees and place your feet flat on the ground, hip-width apart. Lift your hips off the ground, engaging your glutes and hamstrings. Slowly curl your legs towards your glutes, keeping your hips lifted. Pause for a moment at the top, then slowly extend your legs back to the starting position. Lower your hips back down to the ground. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera. Levanta las caderas del suelo, activando los glúteos y los isquiotibiales. Flexiona lentamente las piernas hacia los glúteos, manteniendo las caderas elevadas. Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial. Baja las caderas de nuevo hacia el suelo. Repite el número de repeticiones deseado.', 'glutes', '["glutes","calves"]'::jsonb, 'hamstrings', 'images/0696-E4PwJqI.jpg', 'videos/0696-E4PwJqI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3222', 'semi squat jump (male)', 'cardio', 'cardio', 'body weight', 'Stand with your feet shoulder-width apart. Bend your knees and lower your body into a squat position. Jump explosively, extending your hips and knees while swinging your arms for momentum. Land softly on the balls of your feet and immediately go into the next repetition. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla. Salta de forma explosiva, extendiendo las caderas y las rodillas mientras balanceas los brazos para generar impulso. Aterriza suavemente sobre la punta de los pies y pasa de inmediato a la siguiente repetición. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/3222-6FMU51h.jpg', 'videos/3222-6FMU51h.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3656', 'short stride run', 'cardio', 'cardio', 'body weight', 'Find an open space or a treadmill to perform the exercise. Stand tall with your feet hip-width apart. Start jogging in place, lifting your knees high and pumping your arms. After a few seconds, start taking short strides forward, maintaining a quick pace. Continue running with short strides for the desired duration or distance.', 'Busca un espacio abierto o una cinta de correr para realizar el ejercicio. Ponte de pie con los pies separados a la altura de la cadera. Comienza a trotar en el lugar, levantando las rodillas alto y moviendo los brazos. Después de unos segundos, comienza a dar pasos cortos hacia delante, manteniendo un ritmo rápido. Continúa corriendo con pasos cortos durante la duración o distancia deseada.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/3656-CcWEoWV.jpg', 'videos/3656-CcWEoWV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1763', 'shoulder grip pull-up', 'back', 'back', 'body weight', 'Grab the pull-up bar with a shoulder-width grip, palms facing away from you. Hang freely with your arms fully extended. Engage your back muscles and pull your body up towards the bar until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la barra de dominadas con un agarre a la altura de los hombros, con las palmas mirando hacia fuera. Cuélgate libremente con los brazos completamente extendidos. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra hasta que la barbilla quede por encima de ella. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/1763-YtgD7Xq.jpg', 'videos/1763-YtgD7Xq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3699', 'shoulder tap', 'waist', 'waist', 'body weight', 'Start in a high plank position with your hands directly under your shoulders and your body in a straight line. Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder. Place your right hand back on the ground and repeat with your left hand tapping your right shoulder. Continue alternating shoulder taps while keeping your hips and torso stable. Repeat for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Activa el core y levanta la mano derecha del suelo, extendiéndola para tocar el hombro izquierdo. Coloca la mano derecha de nuevo en el suelo y repite tocando el hombro derecho con la mano izquierda. Continúa alternando los toques de hombro mientras mantienes las caderas y el torso estables. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'abs', 'images/3699-yRpV5TC.jpg', 'videos/3699-yRpV5TC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0699', 'shoulder tap push-up', 'chest', 'chest', 'body weight', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels. Lower your body towards the ground by bending your elbows, keeping them close to your sides. As you push back up, lift your right hand off the ground and tap your left shoulder. Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder. Continue alternating shoulder taps with each push-up repetition. Maintain a stable core and avoid excessive hip rotation throughout the exercise. Repeat for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones. Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Mientras empujas hacia arriba, levanta la mano derecha del suelo y toca el hombro izquierdo. Vuelve a colocar la mano derecha en el suelo y repite la flexión, esta vez levantando la mano izquierda y tocando el hombro derecho. Continúa alternando los toques de hombro en cada repetición de la flexión. Mantén el core estable y evita una rotación excesiva de la cadera durante todo el ejercicio. Repite el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'pectorals', 'images/0699-qEse6fe.jpg', 'videos/0699-qEse6fe.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1774', 'side bridge hip abduction', 'upper legs', 'upper legs', 'body weight', 'Lie on your side with your legs extended and stacked on top of each other. Prop yourself up on your forearm, keeping your elbow directly below your shoulder. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet. While keeping your core engaged, lift your top leg as high as possible without rotating your hips. Pause for a moment at the top, then lower your leg back down. Repeat for the desired number of repetitions, then switch sides.', 'Túmbate de lado con las piernas extendidas y una sobre la otra. Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Manteniendo el core activado, levanta la pierna superior lo más alto posible sin rotar las caderas. Haz una pausa por un momento en la posición alta, luego baja la pierna de nuevo. Repite el número de repeticiones deseado, luego cambia de lado.', 'glutes', '["glutes","obliques"]'::jsonb, 'abductors', 'images/1774-WL4EmxJ.jpg', 'videos/1774-WL4EmxJ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0705', 'side bridge v. 2', 'waist', 'waist', 'body weight', 'Lie on your side with your legs extended and stacked on top of each other. Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet. Hold this position for the desired amount of time. Lower your hips back down to the starting position. Repeat on the other side.', 'Túmbate de lado con las piernas extendidas y una sobre la otra. Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Mantén esta posición durante el tiempo deseado. Baja las caderas de vuelta a la posición inicial. Repite del otro lado.', 'obliques', '["obliques","glutes"]'::jsonb, 'abs', 'images/0705-RKjH6Lt.jpg', 'videos/0705-RKjH6Lt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0709', 'side hip (on parallel bars)', 'waist', 'waist', 'body weight', 'Stand between two parallel bars with your feet shoulder-width apart. Place your hands on the bars and lift your body off the ground, supporting your weight on your arms. Engage your abs and slowly lift your legs to the side, keeping them straight. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie entre dos barras paralelas con los pies separados a la altura de los hombros. Coloca las manos sobre las barras y levanta el cuerpo del suelo, apoyando tu peso en los brazos. Contrae el abdomen y levanta lentamente las piernas hacia el lado, manteniéndolas rectas. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques","hip flexors"]'::jsonb, 'abs', 'images/0709-jTkSc6o.jpg', 'videos/0709-jTkSc6o.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0710', 'side hip abduction', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart and your hands on your hips. Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight. Pause for a moment at the top, then slowly lower your leg back down to the starting position. Repeat on the other side. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las manos en las caderas. Traslada el peso a una pierna y levanta la pierna opuesta hacia el lado, manteniéndola recta. Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial. Repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'glutes', '["glutes","quadriceps"]'::jsonb, 'abductors', 'images/0710-7WaDzyL.jpg', 'videos/0710-7WaDzyL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1358', 'side lying floor stretch', 'back', 'back', 'body weight', 'Lie on your side with your legs straight and your bottom arm extended straight overhead. Bend your top knee and place your foot on the ground in front of your bottom leg. Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture. Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side. Hold the stretch for 20-30 seconds, then slowly lower your leg back down. Repeat on the other side.', 'Túmbate de lado con las piernas rectas y el brazo de abajo extendido recto por encima de la cabeza. Dobla la rodilla de arriba y coloca el pie en el suelo frente a la pierna de abajo. Extiende el brazo de arriba por encima de la cabeza y agárrate a algo estable, como una pared o un mueble. Levanta lentamente la pierna de abajo del suelo, manteniéndola recta, hasta sentir un estiramiento en el costado. Mantén el estiramiento durante 20-30 segundos, luego baja lentamente la pierna de nuevo. Repite del otro lado.', 'obliques', '["obliques","glutes"]'::jsonb, 'lats', 'images/1358-jDOKRM5.jpg', 'videos/1358-jDOKRM5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3667', 'side lying hip adduction (male)', 'upper legs', 'upper legs', 'body weight', 'Lie on your side with your legs straight and stacked on top of each other. Place your bottom arm under your head for support. Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward. Pause for a moment at the top, then slowly lower your leg back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Túmbate de lado con las piernas rectas y apiladas una sobre la otra. Coloca el brazo de abajo bajo la cabeza para apoyarte. Activa los aductores y levanta la pierna de arriba lo más alto posible sin rotar las caderas ni inclinarte hacia atrás. Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'adductors', 'images/3667-c8f5cSY.jpg', 'videos/3667-c8f5cSY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1775', 'side plank hip adduction', 'upper legs', 'upper legs', 'body weight', 'Start by lying on your side with your legs extended and stacked on top of each other. Prop yourself up on your forearm, keeping your elbow directly below your shoulder. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet. While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight. Slowly lower your leg back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Manteniendo la posición de plancha lateral, levanta la pierna de arriba hacia el techo, manteniéndola recta. Baja lentamente la pierna de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'obliques', '["obliques","glutes"]'::jsonb, 'adductors', 'images/1775-VO2qeJg.jpg', 'videos/1775-VO2qeJg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0716', 'side push neck stretch', 'neck', 'neck', 'body weight', 'Stand or sit up straight with your shoulders relaxed. Tilt your head to the right, bringing your right ear towards your right shoulder. Place your right hand on the left side of your head and gently apply pressure to increase the stretch. Hold the stretch for 15-30 seconds. Repeat on the other side, tilting your head to the left and applying pressure with your left hand. Repeat the stretch 2-3 times on each side.', 'Ponte de pie o siéntate erguido con los hombros relajados. Inclina la cabeza hacia la derecha, llevando la oreja derecha hacia el hombro derecho. Coloca la mano derecha en el lado izquierdo de la cabeza y aplica una presión suave para aumentar el estiramiento. Mantén el estiramiento durante 15-30 segundos. Repite hacia el otro lado, inclinando la cabeza hacia la izquierda y aplicando presión con la mano izquierda. Repite el estiramiento 2-3 veces en cada lado.', 'trapezius', '["trapezius","sternocleidomastoid"]'::jsonb, 'levator scapulae', 'images/0716-oQRJYkC.jpg', 'videos/0716-oQRJYkC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0717', 'side push-up', 'upper arms', 'upper arms', 'body weight', 'Start by lying on your side with your legs extended and stacked on top of each other. Place your bottom hand on the ground directly under your shoulder, fingers pointing forward. Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged. Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels. Lower your body back down to the starting position with control. Repeat for the desired number of repetitions, then switch sides.', 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Coloca la mano de abajo en el suelo directamente debajo del hombro, con los dedos apuntando hacia delante. Empuja con la mano de abajo para levantar el cuerpo del suelo, manteniendo las piernas rectas y el core activado. Extiende el brazo de arriba recto hacia el techo, formando una línea recta desde la cabeza hasta los talones. Baja el cuerpo de nuevo a la posición inicial con control. Repite el número de repeticiones deseado, luego cambia de lado.', 'shoulders', '["shoulders","chest","core"]'::jsonb, 'triceps', 'images/0717-wpbD28t.jpg', 'videos/0717-wpbD28t.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0721', 'side wrist pull stretch', 'lower arms', 'lower arms', 'body weight', 'Stand with your feet shoulder-width apart and your arms extended in front of you. Extend your right arm out to the side, parallel to the ground, with your palm facing down. With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm. Hold the stretch for 15-30 seconds, then release. Repeat on the other side.', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti. Extiende el brazo derecho hacia el lado, paralelo al suelo, con la palma hacia abajo. Con la mano izquierda, sujeta la mano derecha y tira de ella suavemente hacia tu cuerpo, sintiendo un estiramiento en el antebrazo derecho. Mantén el estiramiento durante 15-30 segundos, luego suelta. Repite del otro lado.', 'wrists', '["wrists","hands"]'::jsonb, 'forearms', 'images/0721-UtmIqcI.jpg', 'videos/0721-UtmIqcI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0720', 'side-to-side chin', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart and your knees slightly bent. Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body relaxed. Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight. Once your chin is above the bar, lower yourself back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra de dominadas con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo relajado. Levántate doblando los codos y llevando la barbilla hacia la barra, manteniendo el cuerpo recto. Una vez que la barbilla esté por encima de la barra, bájate de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0720-isAAZWA.jpg', 'videos/0720-isAAZWA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3213', 'side-to-side toe touch (male)', 'waist', 'waist', 'body weight', 'Stand with your feet shoulder-width apart and your arms extended to the sides. Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side. Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side. Repeat the side-to-side bending motion for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados. Dobla la cintura hacia la derecha, llevando la mano derecha hacia el pie derecho mientras mantienes la mano izquierda extendida hacia el lado. Vuelve a la posición inicial y luego dobla la cintura hacia la izquierda, llevando la mano izquierda hacia el pie izquierdo mientras mantienes la mano derecha extendida hacia el lado. Repite el movimiento de flexión lateral el número de repeticiones deseado.', 'obliques', '["obliques","hip flexors"]'::jsonb, 'abs', 'images/3213-WCAvOfC.jpg', 'videos/3213-WCAvOfC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0725', 'single arm push-up', 'chest', 'chest', 'body weight', 'Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other. Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight. As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side. Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground. Repeat the movement, alternating the arm you extend with each repetition.', 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y una mano colocada un poco más ancha que la otra. Activa el core y baja el cuerpo hacia el suelo flexionando los codos, manteniendo la espalda recta. Al bajar, traslada el peso hacia un lado y levanta el brazo opuesto del suelo, extendiéndolo recto hacia el lado. Empuja con el pecho y los tríceps para subir el cuerpo de nuevo a la posición inicial, mientras bajas simultáneamente el brazo extendido de vuelta al suelo. Repite el movimiento, alternando el brazo que extiendes en cada repetición.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/0725-MUic5zN.jpg', 'videos/0725-MUic5zN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3645', 'single leg bridge with outstretched leg', 'upper legs', 'upper legs', 'body weight', 'Lie on your back with your knees bent and feet flat on the ground. Extend one leg straight out in front of you. Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders. Hold for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende una pierna recta hacia delante. Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros. Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'glutes', 'images/3645-rmEukuS.jpg', 'videos/3645-rmEukuS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0727', 'single leg calf raise (on a dumbbell)', 'lower legs', 'lower legs', 'dumbbell', 'Stand with your feet hip-width apart and hold a dumbbell in one hand. Lift one foot off the ground and balance on the other foot. Slowly raise your heel as high as possible, using your calf muscles. Pause for a moment at the top, then slowly lower your heel back down. Repeat for the desired number of repetitions, then switch to the other leg.', 'Ponte de pie con los pies separados a la altura de la cadera y sujeta una mancuerna en una mano. Levanta un pie del suelo y mantén el equilibrio sobre el otro pie. Eleva lentamente el talón lo más alto posible, usando los músculos de la pantorrilla. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta hacia abajo. Repite el número de repeticiones deseado, luego cambia a la otra pierna.', 'ankles', '["ankles","feet"]'::jsonb, 'calves', 'images/0727-fKZgDEO.jpg', 'videos/0727-fKZgDEO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0730', 'single leg platform slide', 'upper legs', 'upper legs', 'body weight', 'Start by standing with one foot on a platform or slide board. Bend your knee slightly and slide the foot on the platform backward, extending your leg. Keep your core engaged and maintain a straight posture throughout the movement. Slowly return to the starting position by sliding your foot back to the initial position. Repeat the movement for the desired number of repetitions, then switch legs.', 'Comienza de pie con un pie sobre una plataforma o tabla deslizante. Dobla ligeramente la rodilla y desliza el pie sobre la plataforma hacia atrás, extendiendo la pierna. Mantén el core activado y conserva una postura recta durante todo el movimiento. Vuelve lentamente a la posición inicial deslizando el pie de regreso a la posición inicial. Repite el movimiento el número de repeticiones deseado y luego cambia de pierna.', 'glutes', '["glutes","quadriceps"]'::jsonb, 'hamstrings', 'images/0730-LNE3wfo.jpg', 'videos/0730-LNE3wfo.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1759', 'single leg squat (pistol) male', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart and arms extended in front of you. Lift your right foot off the ground and extend it forward. Slowly lower your body down by bending your left knee and pushing your hips back. Keep your chest up and your back straight as you lower yourself down. Lower until your left thigh is parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your left heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos frente a ti. Levanta el pie derecho del suelo y extiéndelo hacia delante. Baja lentamente el cuerpo doblando la rodilla izquierda y empujando las caderas hacia atrás. Mantén el pecho elevado y la espalda recta mientras bajas el cuerpo. Baja hasta que el muslo izquierdo quede paralelo al suelo, o lo más abajo que puedas llegar cómodamente. Haz una pausa por un momento en la posición baja, luego empuja con el talón izquierdo para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1759-nqs5HGV.jpg', 'videos/1759-nqs5HGV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1489', 'sissy squat', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart and your toes pointing slightly outward. Hold onto a stable object for balance if needed. Slowly lower your body by bending your knees and leaning back, keeping your torso upright. Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujétate de un objeto estable para mantener el equilibrio si es necesario. Baja lentamente el cuerpo doblando las rodillas e inclinándote hacia atrás, manteniendo el torso erguido. Continúa bajando hasta que los muslos queden paralelos al suelo o tan lejos como puedas llegar cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'calves', '["calves","glutes"]'::jsonb, 'quads', 'images/1489-xdYPUtE.jpg', 'videos/1489-xdYPUtE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0735', 'sit-up v. 2', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0735-Bn6TXyO.jpg', 'videos/0735-Bn6TXyO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3679', 'sit-up with arms on chest', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Cross your arms over your chest. Engaging your abs, lift your upper body off the ground towards your knees. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Cruza los brazos sobre el pecho. Contrayendo el abdomen, levanta la parte superior del cuerpo del suelo hacia las rodillas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/3679-6ZCiYWQ.jpg', 'videos/3679-6ZCiYWQ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3361', 'skater hops', 'cardio', 'cardio', 'body weight', 'Stand with your feet shoulder-width apart. Bend your knees slightly and jump to the right, landing on your right foot. As you land, swing your left leg behind your right leg and tap the ground with your left toes. Immediately jump to the left, landing on your left foot. As you land, swing your right leg behind your left leg and tap the ground with your right toes. Continue alternating sides, jumping and tapping the ground with each leg. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Dobla ligeramente las rodillas y salta hacia la derecha, aterrizando sobre el pie derecho. Al aterrizar, balancea la pierna izquierda detrás de la pierna derecha y toca el suelo con los dedos del pie izquierdo. Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo. Al aterrizar, balancea la pierna derecha detrás de la pierna izquierda y toca el suelo con los dedos del pie derecho. Continúa alternando los lados, saltando y tocando el suelo con cada pierna. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","glutes","calves"]'::jsonb, 'cardiovascular system', 'images/3361-zfNHMN9.jpg', 'videos/3361-zfNHMN9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2142', 'ski ergometer', 'upper arms', 'upper arms', 'skierg machine', 'Adjust the seat height and footrests to a comfortable position. Grasp the handles with an overhand grip, palms facing down. Sit up straight with your feet flat on the footrests. Extend your arms straight out in front of you, keeping your elbows slightly bent. Engage your triceps and push the handles down towards your thighs. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y los apoyapiés a una posición cómoda. Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo. Siéntate erguido con los pies planos sobre los apoyapiés. Extiende los brazos rectos frente a ti, manteniendo los codos ligeramente flexionados. Activa los tríceps y empuja las asas hacia abajo, hacia los muslos. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","forearms"]'::jsonb, 'triceps', 'images/2142-vpQaQkH.jpg', 'videos/2142-vpQaQkH.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3671', 'ski step', 'cardio', 'cardio', 'body weight', 'Stand with your feet shoulder-width apart. Bend your knees slightly and keep your back straight. Jump to the right, landing on your right foot while swinging your left leg behind your right leg. Immediately jump to the left, landing on your left foot while swinging your right leg behind your left leg. Continue alternating jumps from side to side, mimicking a skiing motion. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Dobla ligeramente las rodillas y mantén la espalda recta. Salta hacia la derecha, aterrizando sobre el pie derecho mientras balanceas la pierna izquierda detrás de la pierna derecha. Salta inmediatamente hacia la izquierda, aterrizando sobre el pie izquierdo mientras balanceas la pierna derecha detrás de la pierna izquierda. Continúa alternando los saltos de lado a lado, imitando un movimiento de esquí. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","glutes","calves"]'::jsonb, 'cardiovascular system', 'images/3671-5MRH8H2.jpg', 'videos/3671-5MRH8H2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3304', 'skin the cat', 'back', 'back', 'body weight', 'Start by hanging from a bar with your arms fully extended and your body relaxed. Engage your core and lift your legs up, bringing your knees towards your chest. Continue to lift your legs up and over your head, allowing your body to pass through the arms. Once your legs are fully extended over your head, begin to lower them back down towards the starting position. As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again. Repeat for the desired number of repetitions.', 'Comienza colgándote de una barra con los brazos completamente extendidos y el cuerpo relajado. Activa el core y levanta las piernas, llevando las rodillas hacia el pecho. Continúa levantando las piernas por encima de la cabeza, permitiendo que el cuerpo pase entre los brazos. Una vez que las piernas estén completamente extendidas por encima de la cabeza, comienza a bajarlas de nuevo hacia la posición inicial. Mientras bajas las piernas, permite que el cuerpo pase de nuevo entre los brazos hasta quedar colgado con los brazos completamente extendidos otra vez. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","core"]'::jsonb, 'upper back', 'images/3304-MSfvriJ.jpg', 'videos/3304-MSfvriJ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1425', 'sled 45 degrees one leg press', 'upper legs', 'upper legs', 'sled machine', 'Adjust the sled machine to a 45-degree angle. Sit on the sled machine with your back against the pad and your feet on the footplate. Place one foot on the footplate and extend your leg, pushing the sled away from you. Slowly bend your knee and lower the sled back to the starting position. Repeat with the other leg. Continue alternating legs for the desired number of repetitions.', 'Ajusta la máquina de trineo a un ángulo de 45 grados. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la placa. Coloca un pie sobre la placa y extiende la pierna, empujando el trineo alejándolo de ti. Dobla lentamente la rodilla y baja el trineo de vuelta a la posición inicial. Repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1425-WWD6FzI.jpg', 'videos/1425-WWD6FzI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0738', 'sled 45в° calf press', 'lower legs', 'lower legs', 'sled machine', 'Adjust the sled machine to a 45-degree angle. Place your feet on the sled platform with your toes pointing forward. Push the sled platform away from you by extending your ankles and calves. Pause for a moment at the top, then slowly lower the sled platform back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de trineo a un ángulo de 45 grados. Coloca los pies sobre la plataforma del trineo con los dedos de los pies apuntando hacia delante. Empuja la plataforma del trineo alejándola de ti extendiendo los tobillos y las pantorrillas. Haz una pausa por un momento en la posición alta, luego baja lentamente la plataforma del trineo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/0738-qCNVnaU.jpg', 'videos/0738-qCNVnaU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0739', 'sled 45в° leg press', 'upper legs', 'upper legs', 'sled machine', 'Adjust the seat and footplate of the sled machine to a comfortable position. Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate. Grip the handles on the sides of the seat for stability. Push the footplate away from your body by extending your legs, keeping your heels on the footplate. Continue pushing until your legs are almost fully extended, but without locking your knees. Pause for a moment at the top of the movement, then slowly lower the footplate back towards your body by bending your knees. Repeat for the desired number of repetitions.', 'Ajusta el asiento y la placa de la máquina de trineo a una posición cómoda. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa. Sujeta las asas a los lados del asiento para mayor estabilidad. Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa. Continúa empujando hasta que las piernas estén casi completamente extendidas, pero sin bloquear las rodillas. Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la placa de vuelta hacia tu cuerpo doblando las rodillas. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0739-10Z2DXU.jpg', 'videos/0739-10Z2DXU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1464', 'sled 45в° leg press (back pov)', 'upper legs', 'upper legs', 'sled machine', 'Adjust the seat of the sled machine so that your knees are at a 45-degree angle. Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate. Grip the handles on the sides of the seat for stability. Push the footplate away from your body by extending your legs, keeping your heels on the footplate. Pause for a moment at the fully extended position. Slowly bend your knees and lower the footplate back towards your body, controlling the movement. Repeat for the desired number of repetitions.', 'Ajusta el asiento de la máquina de trineo de modo que las rodillas queden en un ángulo de 45 grados. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies separados a la altura de los hombros sobre la placa. Sujeta las asas a los lados del asiento para mayor estabilidad. Empuja la placa alejándola de tu cuerpo extendiendo las piernas, manteniendo los talones sobre la placa. Haz una pausa por un momento en la posición completamente extendida. Dobla lentamente las rodillas y baja la placa de vuelta hacia tu cuerpo, controlando el movimiento. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1464-yn2lLSI.jpg', 'videos/1464-yn2lLSI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1463', 'sled 45° leg press (side pov)', 'upper legs', 'upper legs', 'sled machine', 'Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate. Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate. Grip the handles on the sides of the seat for stability. Push against the footplate to extend your legs, straightening them completely. Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta el asiento de la máquina de trineo de modo que las rodillas queden en un ángulo de 90 grados cuando los pies estén sobre la placa. Siéntate en la máquina de trineo con la espalda plana contra el respaldo y los pies separados a la altura de los hombros sobre la placa. Sujeta las asas a los lados del asiento para mayor estabilidad. Empuja contra la placa para extender las piernas, estirándolas por completo. Haz una pausa por un momento en la posición alta, luego dobla lentamente las rodillas para bajar la placa de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1463-2Qh2J1e.jpg', 'videos/1463-2Qh2J1e.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0740', 'sled 45в° leg wide press', 'upper legs', 'upper legs', 'sled machine', 'Adjust the sled machine to a 45-degree angle. Sit on the sled machine with your back against the pad and your feet on the foot platform. Position your feet wider than shoulder-width apart. Push against the foot platform to extend your legs and straighten your knees. Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de trineo a un ángulo de 45 grados. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma. Coloca los pies más separados que el ancho de los hombros. Empuja contra la plataforma para extender las piernas y enderezar las rodillas. Haz una pausa por un momento al final del movimiento, luego dobla lentamente las rodillas para volver a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0740-tj41Nu6.jpg', 'videos/0740-tj41Nu6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1391', 'sled calf press on leg press', 'lower legs', 'lower legs', 'sled machine', 'Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled. Place your feet shoulder-width apart on the sled, with your toes pointing forward. Release the safety handles and push the sled away from you by extending your knees and ankles. Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles. Repeat for the desired number of repetitions.', 'Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo. Coloca los pies separados a la altura de los hombros sobre el trineo, con los dedos de los pies apuntando hacia delante. Suelta las asas de seguridad y empuja el trineo alejándolo de ti extendiendo las rodillas y los tobillos. Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente el trineo doblando las rodillas y los tobillos. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps"]'::jsonb, 'calves', 'images/1391-ykHcWme.jpg', 'videos/1391-ykHcWme.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0741', 'sled closer hack squat', 'upper legs', 'upper legs', 'sled machine', 'Adjust the sled machine to a comfortable weight and position yourself with your back against the pad. Place your feet shoulder-width apart on the platform, toes slightly pointed outwards. Grip the handles on the sides of the machine for stability. Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight. Continue lowering until your thighs are parallel to the ground or slightly below. Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de trineo a un peso cómodo y colócate con la espalda contra el respaldo. Coloca los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera. Sujeta las asas a los lados de la máquina para mayor estabilidad. Activa el core y baja lentamente el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento en la posición baja, luego empuja con los talones para extender las piernas y volver a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0741-gf3ZjB9.jpg', 'videos/0741-gf3ZjB9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0742', 'sled forward angled calf raise', 'lower legs', 'lower legs', 'sled machine', 'Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off. Place your hands on the handles or the sides of the machine for support. Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled. Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de trineo a un peso cómodo y colócate en la máquina con la punta de los pies sobre la plataforma y los talones colgando. Coloca las manos en las asas o a los lados de la máquina para apoyarte. Activa las pantorrillas y eleva lentamente los talones lo más alto posible, empujando contra la resistencia del trineo. Haz una pausa breve en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/0742-XDOiFns.jpg', 'videos/0742-XDOiFns.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0743', 'sled hack squat', 'upper legs', 'upper legs', 'sled machine', 'Adjust the sled machine to a comfortable position for your height. Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards. Hold onto the handles or bars for stability. Lower your body by bending your knees and hips, keeping your back straight and chest up. Continue lowering until your thighs are parallel to the ground or slightly below. Pause for a moment, then push through your heels to raise your body back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de trineo a una posición cómoda según tu altura. Ponte de pie con los pies separados a la altura de los hombros sobre la plataforma, con los dedos de los pies ligeramente apuntando hacia fuera. Sujétate de las asas o barras para mayor estabilidad. Baja el cuerpo doblando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento, luego empuja con los talones para subir el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0743-Qa55kX1.jpg', 'videos/0743-Qa55kX1.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2334', 'sled lying calf press', 'lower legs', 'lower legs', 'sled machine', 'Adjust the sled machine to a comfortable weight. Sit on the sled machine with your back against the pad and your feet on the platform. Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off. Push the platform away from you by extending your ankles, keeping your knees slightly bent. Continue pushing until your calves are fully contracted. Hold the contraction for a moment, then slowly lower the platform back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina de trineo a un peso adecuado. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la plataforma. Coloca la punta y la almohadilla de los pies en el borde de la plataforma, con los talones colgando. Empuja la plataforma alejándola de ti extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas. Continúa empujando hasta que las pantorrillas estén completamente contraídas. Mantén la contracción por un momento, luego baja lentamente la plataforma de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/2334-g376LuL.jpg', 'videos/2334-g376LuL.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0744', 'sled lying squat', 'upper legs', 'upper legs', 'sled machine', 'Adjust the sled machine to a comfortable weight. Lie on your back on the sled machine with your feet on the footplate. Position your feet shoulder-width apart and slightly angled outwards. Grip the handles of the sled machine for stability. Engage your glutes and core muscles. Push through your heels and extend your legs to lift the sled. Lower the sled back down by bending your knees and hips. Repeat for the desired number of repetitions.', 'Ajusta la máquina de trineo a un peso adecuado. Túmbate boca arriba en la máquina de trineo con los pies sobre la placa. Coloca los pies separados a la altura de los hombros y ligeramente angulados hacia fuera. Sujeta las asas de la máquina de trineo para mayor estabilidad. Activa los glúteos y los músculos del core. Empuja con los talones y extiende las piernas para levantar el trineo. Baja el trineo de nuevo doblando las rodillas y las caderas. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0744-9n2149Z.jpg', 'videos/0744-9n2149Z.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1392', 'sled one leg calf press on leg press', 'lower legs', 'lower legs', 'sled machine', 'Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled. Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart. Place your toes and the balls of your feet on the sled, keeping your heels off. Push the sled forward by extending your ankles, keeping your knees slightly bent. Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles. Repeat for the desired number of repetitions.', 'Ajusta el asiento de la máquina de prensa de piernas de modo que las rodillas queden ligeramente flexionadas cuando los pies estén sobre el trineo. Siéntate en la máquina con la espalda contra el respaldo y los pies sobre el trineo, separados a la altura de los hombros. Coloca la punta y la almohadilla de los pies sobre el trineo, manteniendo los talones levantados. Empuja el trineo hacia delante extendiendo los tobillos, manteniendo las rodillas ligeramente flexionadas. Haz una pausa por un momento en la posición alta, luego baja lentamente el trineo flexionando los tobillos. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1392-u0pLNgz.jpg', 'videos/1392-u0pLNgz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1496', 'sledge hammer', 'waist', 'waist', 'hammer', 'Stand with your feet shoulder-width apart and hold the sledge hammer with both hands. Engage your core and keep your back straight. Swing the sledge hammer down towards the ground, using your core and upper body strength. As you swing down, pivot your hips and transfer the force to the hammer. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta el mazo con ambas manos. Activa el core y mantén la espalda recta. Balancea el mazo hacia el suelo, usando la fuerza del core y de la parte superior del cuerpo. Mientras balanceas hacia abajo, gira las caderas y transfiere la fuerza al mazo. Repite el número de repeticiones deseado.', 'forearms', '["forearms","shoulders"]'::jsonb, 'abs', 'images/1496-REXmfVC.jpg', 'videos/1496-REXmfVC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0746', 'smith back shrug', 'back', 'back', 'smith machine', 'Stand with your feet shoulder-width apart and your knees slightly bent. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Keep your arms straight and allow the barbell to hang in front of your thighs. Lift your shoulders straight up towards your ears, squeezing your traps at the top. Hold for a moment, then lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Mantén los brazos rectos y deja que la barra cuelgue frente a los muslos. Levanta los hombros directamente hacia las orejas, contrayendo los trapecios en la parte alta. Mantén la posición por un momento, luego baja los hombros de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'traps', 'images/0746-MzNnwx9.jpg', 'videos/0746-MzNnwx9.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0747', 'smith behind neck press', 'shoulders', 'shoulders', 'smith machine', 'Adjust the seat height of the smith machine so that the bar is at shoulder level. Stand with your feet shoulder-width apart and your knees slightly bent. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Lift the bar off the rack and step back, maintaining a stable stance. Lower the bar down to the back of your neck, keeping your elbows pointing forward. Press the bar up overhead until your arms are fully extended. Pause for a moment at the top, then slowly lower the bar back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable. Baja la barra hacia la parte de atrás del cuello, manteniendo los codos apuntando hacia delante. Empuja la barra hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos. Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0747-Gpn4ADc.jpg', 'videos/0747-Gpn4ADc.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0748', 'smith bench press', 'chest', 'chest', 'smith machine', 'Adjust the height of the smith machine bar to chest level. Lie flat on the bench with your feet firmly planted on the ground. Grip the bar with an overhand grip slightly wider than shoulder-width apart. Unrack the bar and lower it towards your chest, keeping your elbows tucked in. Pause for a moment when the bar touches your chest. Push the bar back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ajusta la altura de la barra de la máquina Smith a la altura del pecho. Túmbate en el banco con los pies firmemente apoyados en el suelo. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Suelta la barra del soporte y bájala hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa por un momento cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0748-trqKQv2.jpg', 'videos/0748-trqKQv2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0749', 'smith bent knee good morning', 'upper legs', 'upper legs', 'smith machine', 'Start by standing with your feet shoulder-width apart, toes pointing forward. Place the barbell across your upper back, resting it on your traps. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings. Engage your glutes and hamstrings to raise your torso back up to the starting position. Repeat for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros, con los dedos de los pies apuntando hacia delante. Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales. Activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","lower back"]'::jsonb, 'glutes', 'images/0749-1bQkKZK.jpg', 'videos/0749-1bQkKZK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1359', 'smith bent over row', 'back', 'back', 'smith machine', 'Set up the smith machine with the bar at hip height. Stand facing the bar with your feet shoulder-width apart. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart. Pull the bar towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the bar back down to the starting position. Repeat for the desired number of repetitions.', 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Tira de la barra hacia la parte baja del pecho, juntando las escápulas. Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1359-ZX9UZmj.jpg', 'videos/1359-ZX9UZmj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0750', 'smith chair squat', 'upper legs', 'upper legs', 'smith machine', 'Adjust the height of the smith machine bar to a comfortable position. Stand with your feet shoulder-width apart, toes slightly turned out. Place the barbell across your upper back, resting it on your traps. Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura de la barra de la máquina Smith a una posición cómoda. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo doblando las rodillas y las caderas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/0750-Gu2rNJd.jpg', 'videos/0750-Gu2rNJd.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0751', 'smith close-grip bench press', 'upper arms', 'upper arms', 'smith machine', 'Adjust the seat height and position yourself on the bench with your feet flat on the ground. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart. Lower the barbell towards your chest, keeping your elbows close to your body. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0751-WcHl7ru.jpg', 'videos/0751-WcHl7ru.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0752', 'smith deadlift', 'upper legs', 'upper legs', 'smith machine', 'Set up the smith machine with the bar at hip height. Stand with your feet shoulder-width apart, toes pointing slightly outward. Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart. Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body. Stand up straight, fully extending your hips and knees. Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight. Repeat for the desired number of repetitions.', 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Dobla las caderas y las rodillas, manteniendo la espalda recta y el pecho elevado, y sujeta la barra con un agarre prono un poco más ancho que los hombros. Activa el core y levanta la barra extendiendo las caderas y las rodillas, manteniendo la barra cerca del cuerpo. Ponte de pie erguido, extendiendo por completo las caderas y las rodillas. Baja la barra de nuevo doblando las caderas y las rodillas, manteniendo el control y la espalda recta. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","lower back"]'::jsonb, 'glutes', 'images/0752-UfePqpx.jpg', 'videos/0752-UfePqpx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0753', 'smith decline bench press', 'chest', 'chest', 'smith machine', 'Adjust the decline bench to the desired angle. Lie down on the bench with your feet secured under the foot pads. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta el banco declinado al ángulo deseado. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0753-ETZfAbZ.jpg', 'videos/0753-ETZfAbZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0754', 'smith decline reverse-grip press', 'chest', 'chest', 'smith machine', 'Adjust the smith machine to a decline position. Lie down on the bench with your feet secured under the foot pads. Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart. Unrack the barbell and lower it towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina Smith a una posición declinada. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros. Suelta la barra y bájala hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0754-MY9P1WA.jpg', 'videos/0754-MY9P1WA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1433', 'smith front squat (clean grip)', 'upper legs', 'upper legs', 'smith machine', 'Set up the smith machine with the barbell at shoulder height. Stand facing the barbell with your feet shoulder-width apart. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids. Keep your chest up, back straight, and core engaged. Lower your body by bending at the knees and hips, as if sitting back into a chair. Continue lowering until your thighs are parallel to the ground or slightly below. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Configura la máquina Smith con la barra a la altura de los hombros. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Da un paso atrás y coloca la barra sobre los hombros delanteros, apoyándola en la clavícula y los deltoides. Mantén el pecho elevado, la espalda recta y el core activado. Baja el cuerpo doblando las rodillas y las caderas, como si te sentaras en una silla. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves","core"]'::jsonb, 'glutes', 'images/1433-lFhb2Rw.jpg', 'videos/1433-lFhb2Rw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3281', 'smith full squat', 'upper legs', 'upper legs', 'smith machine', 'Set up the smith machine with the barbell at shoulder height. Stand with your feet shoulder-width apart, toes slightly turned out. Step under the bar and position it across your upper back, resting on your traps. Grip the bar with your hands slightly wider than shoulder-width apart. Unrack the bar and take a step back, maintaining a stable stance. Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees. Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows. Pause for a moment at the bottom, then drive through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Configura la máquina Smith con la barra a la altura de los hombros. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios. Sujeta la barra con las manos un poco más separadas que el ancho de los hombros. Suelta la barra del soporte y da un paso atrás, manteniendo una postura estable. Manteniendo el pecho elevado y el core activado, inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas. Baja el cuerpo hasta que los muslos queden paralelos al suelo, o tan abajo como tu flexibilidad lo permita. Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3281-NNoHCEA.jpg', 'videos/3281-NNoHCEA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0755', 'smith hack squat', 'upper legs', 'upper legs', 'smith machine', 'Adjust the barbell on the smith machine to an appropriate height for your body. Stand with your feet shoulder-width apart, toes slightly pointed outwards. Position yourself under the barbell, resting it on your upper traps and shoulders. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Engage your core and keep your chest up as you unrack the barbell. Take a step back and position your feet slightly wider than shoulder-width apart. Bend your knees and lower your body down, keeping your chest up and back straight. Continue descending until your thighs are parallel to the ground or slightly below. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la barra de la máquina Smith a una altura adecuada para tu cuerpo. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Activa el core y mantén el pecho elevado mientras sueltas la barra del soporte. Da un paso atrás y coloca los pies un poco más separados que el ancho de los hombros. Dobla las rodillas y baja el cuerpo, manteniendo el pecho elevado y la espalda recta. Continúa descendiendo hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0755-ZuPXtCK.jpg', 'videos/0755-ZuPXtCK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0756', 'smith hip raise', 'waist', 'waist', 'smith machine', 'Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart. Place your hands on the barbell, slightly wider than shoulder-width apart. Engage your core and glutes, then push through your heels to raise your hips off the ground. Continue lifting until your body forms a straight line from your knees to your shoulders. Hold for a moment at the top, then slowly lower your hips back down to the starting position. Repeat for the desired number of repetitions.', 'Colócate en la máquina Smith con la espalda contra la almohadilla y los pies separados a la altura de los hombros. Coloca las manos en la barra, un poco más separadas que el ancho de los hombros. Activa el core y los glúteos, luego empuja con los talones para levantar las caderas del suelo. Continúa levantando hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Mantén la posición alta por un momento, luego baja lentamente las caderas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'abs', 'images/0756-CqhoytW.jpg', 'videos/0756-CqhoytW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0757', 'smith incline bench press', 'chest', 'chest', 'smith machine', 'Adjust the bench to a 30-45 degree incline. Sit on the bench with your back flat against the pad and feet firmly on the ground. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ajusta el banco a una inclinación de 30-45 grados. Siéntate en el banco con la espalda plana contra la almohadilla y los pies firmemente apoyados en el suelo. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Suelta la barra y bájala lentamente hacia la parte alta del pecho, manteniendo los codos ligeramente pegados al cuerpo. Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0757-5v7KYld.jpg', 'videos/0757-5v7KYld.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0758', 'smith incline reverse-grip press', 'chest', 'chest', 'smith machine', 'Adjust the seat of the smith machine to a comfortable incline angle. Sit on the machine with your back against the pad and your feet flat on the ground. Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart. Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment when the bar is just above your chest. Push the bar back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ajusta el asiento de la máquina Smith a un ángulo de inclinación cómodo. Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo. Sujeta la barra con un agarre prono un poco más ancho que el ancho de los hombros. Suelta la barra y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa por un momento cuando la barra esté justo por encima del pecho. Empuja la barra de vuelta a la posición inicial, extendiendo los brazos por completo. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0758-78VqWQK.jpg', 'videos/0758-78VqWQK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0759', 'smith incline shoulder raises', 'chest', 'chest', 'smith machine', 'Adjust the smith machine to an incline position. Stand facing the machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and core engaged. Raise the barbell up towards the ceiling, leading with your elbows. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina Smith a una posición inclinada. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Mantén la espalda recta y el core activado. Eleva la barra hacia el techo, guiando el movimiento con los codos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'deltoids', '["deltoids","trapezius"]'::jsonb, 'serratus anterior', 'images/0759-ayAHcEm.jpg', 'videos/0759-ayAHcEm.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0760', 'smith leg press', 'upper legs', 'upper legs', 'smith machine', 'Adjust the seat and footplate of the smith machine to a comfortable position. Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate. Grasp the handles or sides of the machine for stability. Push the footplate away from you by extending your legs, keeping your back against the backrest. Pause for a moment at the fully extended position. Slowly bend your knees and lower the footplate back towards you, returning to the starting position. Repeat for the desired number of repetitions.', 'Ajusta el asiento y la placa para los pies de la máquina Smith a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies. Sujeta las asas o los lados de la máquina para mayor estabilidad. Empuja la placa alejándola de ti extendiendo las piernas, manteniendo la espalda contra el respaldo. Haz una pausa por un momento en la posición completamente extendida. Dobla lentamente las rodillas y baja la placa de vuelta hacia ti, regresando a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0760-7zdxRTl.jpg', 'videos/0760-7zdxRTl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1434', 'smith low bar squat', 'upper legs', 'upper legs', 'smith machine', 'Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back. Stand with your feet shoulder-width apart, toes slightly turned outwards. Step under the bar and position it across your upper back, resting it on your traps. Grip the bar with your hands slightly wider than shoulder-width apart. Unrack the bar by straightening your legs and stepping back from the rack. Take a deep breath and brace your core. Initiate the squat by pushing your hips back and bending your knees. Lower your body until your thighs are parallel to the ground or slightly below. Keep your chest up and your back straight throughout the movement. Drive through your heels to stand back up, extending your hips and knees. Repeat for the desired number of repetitions.', 'Configura la máquina Smith con la barra a una altura que te permita apoyarla cómodamente en la parte alta de la espalda. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra y posiciónala sobre la parte alta de la espalda, apoyándola en los trapecios. Sujeta la barra con las manos un poco más separadas que el ancho de los hombros. Suelta la barra del soporte estirando las piernas y dando un paso atrás para alejarte del soporte. Respira profundamente y tensa el core. Inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas. Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo. Mantén el pecho hacia arriba y la espalda recta durante todo el movimiento. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1434-RGLscZM.jpg', 'videos/1434-RGLscZM.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1683', 'smith machine bicep curl', 'upper arms', 'upper arms', 'smith machine', 'Adjust the height of the smith machine bar to be at waist level. Stand facing the smith machine with your feet shoulder-width apart. Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart. Keep your elbows close to your sides and your upper arms stationary. Exhale and curl the bar up towards your shoulders, contracting your biceps. Pause for a moment at the top of the movement, squeezing your biceps. Inhale and slowly lower the bar back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura de la barra de la máquina Smith a la altura de la cintura. Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros. Sujeta la barra con un agarre supino, con las manos un poco más separadas que el ancho de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/1683-zILLZ98.jpg', 'videos/1683-zILLZ98.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1625', 'smith machine decline close grip bench press', 'upper arms', 'upper arms', 'smith machine', 'Adjust the bench on the smith machine to a decline position. Lie down on the bench with your feet firmly planted on the ground. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body. Pause for a moment when the barbell is just above your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ajusta el banco de la máquina Smith a una posición declinada. Túmbate en el banco con los pies firmemente apoyados en el suelo. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra esté justo encima del pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1625-yB9SvIF.jpg', 'videos/1625-yB9SvIF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1752', 'smith machine incline tricep extension', 'upper arms', 'upper arms', 'smith machine', 'Adjust the seat of the smith machine so that the bar is at shoulder height. Sit on the bench with your back against the pad and your feet flat on the ground. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Extend your arms fully, lifting the bar off the rack and holding it directly above your chest. Lower the bar slowly towards your forehead, keeping your elbows close to your head. Pause for a moment at the bottom, then push the bar back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta el asiento de la máquina Smith de modo que la barra quede a la altura de los hombros. Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Extiende los brazos por completo, levantando la barra del soporte y sosteniéndola directamente sobre el pecho. Baja la barra lentamente hacia la frente, manteniendo los codos cerca de la cabeza. Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/1752-o8aOcrz.jpg', 'videos/1752-o8aOcrz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1626', 'smith machine reverse decline close grip bench press', 'chest', 'chest', 'smith machine', 'Adjust the smith machine to a decline position. Lie down on the bench with your feet secured under the foot pads. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the barbell back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la máquina Smith a una posición declinada. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1626-QyO6Uma.jpg', 'videos/1626-QyO6Uma.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0761', 'smith narrow row', 'back', 'back', 'smith machine', 'Adjust the seat height and position yourself on the machine with your feet flat on the floor. Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart. Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con los pies planos sobre el suelo. Sujeta las asas con un agarre prono, un poco más estrecho que el ancho de los hombros. Mantén la espalda recta y el pecho elevado mientras tiras de las asas hacia tu cuerpo, juntando las escápulas. Haz una pausa por un momento en el punto máximo del movimiento, luego suelta lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rear deltoids"]'::jsonb, 'upper back', 'images/0761-JGKowMS.jpg', 'videos/0761-JGKowMS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1360', 'smith one arm row', 'back', 'back', 'smith machine', 'Adjust the height of the smith machine bar to waist level. Stand facing the smith machine with your feet shoulder-width apart. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Grasp the bar with one hand using an overhand grip, with your palm facing down. Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', 'Ajusta la altura de la barra de la máquina Smith a la altura de la cintura. Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la barra con una mano usando un agarre prono, con la palma hacia abajo. Mantén el codo cerca del cuerpo y tira de la barra hacia la cintura, juntando las escápulas. Haz una pausa por un momento en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1360-Q4DSJPC.jpg', 'videos/1360-Q4DSJPC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1393', 'smith one leg floor calf raise', 'lower legs', 'lower legs', 'smith machine', 'Position yourself on the floor under the smith machine bar, facing away from the machine. Place the balls of your feet on a raised surface, such as a weight plate or block. Position the smith machine bar across your lower legs, just above your ankles. Hold onto the bar with your hands for stability. Raise your heels off the ground by extending your ankles, lifting your body up. Pause at the top of the movement, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Colócate en el suelo debajo de la barra de la máquina Smith, mirando en dirección contraria a la máquina. Coloca la punta de los pies sobre una superficie elevada, como un disco de peso o un bloque. Coloca la barra de la máquina Smith sobre la parte baja de las piernas, justo por encima de los tobillos. Sujeta la barra con las manos para mayor estabilidad. Levanta los talones del suelo extendiendo los tobillos, elevando el cuerpo hacia arriba. Haz una pausa en la parte alta del movimiento, luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1393-9GXrTE6.jpg', 'videos/1393-9GXrTE6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0762', 'smith rear delt row', 'shoulders', 'shoulders', 'smith machine', 'Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart. Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together. Pause for a moment at the top of the movement, then slowly release the handles back to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies planos en el suelo. Agarra las agarraderas con un agarre prono, un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el core activado mientras tiras de las asas hacia el pecho, juntando las escápulas. Haz una pausa por un momento en la parte alta del movimiento, luego suelta lentamente las asas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'trapezius', '["trapezius","rhomboids","biceps"]'::jsonb, 'delts', 'images/0762-nFUwqG6.jpg', 'videos/0762-nFUwqG6.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0763', 'smith reverse calf raises', 'lower legs', 'lower legs', 'smith machine', 'Adjust the smith machine bar to a height just below your shoulders. Stand facing the bar with your feet hip-width apart and toes pointing forward. Place the balls of your feet on the edge of a step or platform, with your heels hanging off. Hold onto the bar for support, keeping your back straight and core engaged. Raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros. Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante. Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando. Sujétate de la barra para apoyarte, manteniendo la espalda recta y el core activado. Levanta los talones lo más alto posible, elevando el peso de tu cuerpo sobre las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/0763-ywaNfuh.jpg', 'videos/0763-ywaNfuh.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1394', 'smith reverse calf raises', 'lower legs', 'lower legs', 'smith machine', 'Adjust the smith machine bar to a height just below your shoulders. Stand facing the bar with your feet hip-width apart and toes pointing forward. Place the balls of your feet on the edge of a step or platform, with your heels hanging off. Hold onto the bar for support. Raise your heels as high as possible, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros. Ponte de pie frente a la barra con los pies separados a la altura de la cadera y los dedos de los pies apuntando hacia delante. Coloca la punta de los pies en el borde de un escalón o plataforma, con los talones colgando. Sujétate de la barra para apoyarte. Levanta los talones lo más alto posible, elevando el cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/1394-Lsqrgh4.jpg', 'videos/1394-Lsqrgh4.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1361', 'smith reverse grip bent over row', 'back', 'back', 'smith machine', 'Set up the smith machine with the bar at hip height. Stand facing the bar with your feet shoulder-width apart. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Grasp the bar with an underhand grip, hands shoulder-width apart. Pull the bar towards your lower chest, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower the bar back down to the starting position. Repeat for the desired number of repetitions.', 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Tira de la barra hacia la parte baja del pecho, juntando las escápulas. Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'upper back', 'images/1361-aaxA3cm.jpg', 'videos/1361-aaxA3cm.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0764', 'smith reverse-grip press', 'chest', 'chest', 'smith machine', 'Adjust the height of the smith machine bar to chest level. Stand facing the bar with your feet shoulder-width apart. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart. Step back and position yourself with a slight bend in your knees. Keep your chest up and core engaged throughout the exercise. Lower the bar towards your chest, keeping your elbows tucked in. Pause for a moment at the bottom, then push the bar back up to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura de la barra de la máquina Smith a la altura del pecho. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Da un paso atrás y colócate con una ligera flexión en las rodillas. Mantén el pecho elevado y el core activado durante todo el ejercicio. Baja la barra hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/0764-zK8Fu1W.jpg', 'videos/0764-zK8Fu1W.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1395', 'smith seated one leg calf raise', 'lower legs', 'lower legs', 'smith machine', 'Sit on the machine with your back against the pad and your feet on the footrest. Place one leg on the footrest and keep the other leg off the footrest. Using your calf muscles, raise your heel as high as possible. Pause for a moment at the top, then slowly lower your heel back down to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', 'Siéntate en la máquina con la espalda contra la almohadilla y los pies sobre el apoyapiés. Coloca una pierna sobre el apoyapiés y mantén la otra pierna fuera de él. Eleva el talón lo más alto posible, usando los músculos de la pantorrilla. Haz una pausa por un momento en la parte superior, luego baja lentamente el talón de vuelta a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'hamstrings', '["hamstrings"]'::jsonb, 'calves', 'images/1395-0S75mYG.jpg', 'videos/1395-0S75mYG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0765', 'smith seated shoulder press', 'shoulders', 'shoulders', 'smith machine', 'Adjust the seat height so that the handles are at shoulder level. Sit on the machine with your back against the pad and your feet flat on the floor. Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully. Lower the handles down to shoulder level, keeping your elbows slightly bent. Press the handles up overhead until your arms are fully extended. Pause for a moment at the top, then slowly lower the handles back down to shoulder level. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento de modo que las asas queden a la altura de los hombros. Siéntate en la máquina con la espalda contra la almohadilla y los pies planos sobre el suelo. Sujeta las asas con un agarre prono y levántalas de los soportes, extendiendo los brazos por completo. Baja las asas hasta la altura de los hombros, manteniendo los codos ligeramente flexionados. Empuja las asas hacia arriba, por encima de la cabeza, hasta que los brazos queden completamente extendidos. Haz una pausa por un momento en la parte alta y luego baja lentamente las agarraderas de vuelta a la altura del hombro. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0765-xUwnBMT.jpg', 'videos/0765-xUwnBMT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1426', 'smith seated wrist curl', 'lower arms', 'lower arms', 'smith machine', 'Sit on a bench in front of a Smith machine with your feet flat on the ground. Grasp the barbell with an underhand grip, hands shoulder-width apart. Rest your forearms on your thighs, allowing your wrists to hang off. Slowly curl your wrists upward, bringing the barbell towards your forearms. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco frente a una máquina Smith con los pies planos sobre el suelo. Sujeta la barra con un agarre supino, con las manos separadas a la altura de los hombros. Apoya los antebrazos sobre los muslos, permitiendo que las muñecas cuelguen. Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","brachialis"]'::jsonb, 'forearms', 'images/1426-B6dAO1t.jpg', 'videos/1426-B6dAO1t.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0766', 'smith shoulder press', 'shoulders', 'shoulders', 'smith machine', 'Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward. Press the bar upward until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the bar back down to shoulder level. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate en la máquina Smith con los pies separados a la altura de los hombros. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Levanta la barra del soporte y colócala a la altura de los hombros, con los codos flexionados y las palmas hacia delante. Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos por encima de la cabeza. Haz una pausa por un momento en la posición alta, luego baja lentamente la barra de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0766-903mzG8.jpg', 'videos/0766-903mzG8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0767', 'smith shrug', 'back', 'back', 'smith machine', 'Stand with your feet shoulder-width apart and your knees slightly bent. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Keep your arms straight and your shoulders relaxed. Lift your shoulders up towards your ears, squeezing your traps at the top. Hold for a moment, then slowly lower your shoulders back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Mantén los brazos rectos y los hombros relajados. Levanta los hombros hacia las orejas, contrayendo los trapecios en la parte alta. Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'traps', 'images/0767-OUQ0ZyW.jpg', 'videos/0767-OUQ0ZyW.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0768', 'smith single leg split squat', 'upper legs', 'upper legs', 'smith machine', 'Stand in front of the smith machine with your feet shoulder-width apart. Place one foot behind you on a bench or step, with your toes pointing forward. Hold onto the smith machine bar for stability. Bend your front knee and lower your body down into a lunge position, keeping your back straight. Pause for a moment at the bottom, then push through your front heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros. Coloca un pie detrás de ti sobre un banco o escalón, con los dedos del pie apuntando hacia delante. Sujétate de la barra de la máquina Smith para mayor estabilidad. Dobla la rodilla delantera y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta. Haz una pausa por un momento en la posición baja, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'quads', 'images/0768-wWFspEi.jpg', 'videos/0768-wWFspEi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0769', 'smith sprint lunge', 'upper legs', 'upper legs', 'smith machine', 'Set up the smith machine with the barbell at hip height. Stand facing away from the machine with your feet shoulder-width apart. Step back with your right foot and place it on the barbell, resting the top of your foot on the bar. Bend your left knee and lower your body into a lunge position, keeping your back straight. Push through your left heel to return to the starting position. Repeat on the other side, stepping back with your left foot. Continue alternating sides for the desired number of repetitions.', 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Da un paso atrás con el pie derecho y colócalo sobre la barra, apoyando la parte superior del pie en ella. Dobla la rodilla izquierda y baja el cuerpo hacia una posición de zancada, manteniendo la espalda recta. Empuja con el talón izquierdo para volver a la posición inicial. Repite del otro lado, dando un paso hacia atrás con el pie izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0769-HsjbB1z.jpg', 'videos/0769-HsjbB1z.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0770', 'smith squat', 'upper legs', 'upper legs', 'smith machine', 'Set up the smith machine with the barbell at an appropriate height for your squat. Stand with your feet shoulder-width apart, toes slightly turned out. Position yourself under the barbell, resting it on your upper traps and shoulders. Grip the barbell with a wide grip, slightly wider than shoulder-width apart. Engage your core and unrack the barbell, stepping back to clear the rack. Keeping your chest up and back straight, initiate the squat by bending at the hips and knees. Lower your body until your thighs are parallel to the ground or slightly below. Pause for a moment at the bottom, then drive through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Configura la máquina Smith con la barra a una altura adecuada para tu sentadilla. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Activa el core y suelta la barra del soporte, dando un paso atrás para alejarte del soporte. Manteniendo el pecho elevado y la espalda recta, inicia la sentadilla doblando las caderas y las rodillas. Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0770-jFtipLl.jpg', 'videos/0770-jFtipLl.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0771', 'smith standing back wrist curl', 'lower arms', 'lower arms', 'smith machine', 'Stand facing the smith machine with your feet shoulder-width apart. Grasp the barbell with an overhand grip, hands shoulder-width apart. Keep your back straight and your elbows close to your body. Slowly curl your wrists upwards, bringing the barbell towards your body. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos separadas a la altura de los hombros. Mantén la espalda recta y los codos cerca del cuerpo. Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps"]'::jsonb, 'forearms', 'images/0771-hfmQ0Tz.jpg', 'videos/0771-hfmQ0Tz.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0772', 'smith standing behind head military press', 'shoulders', 'shoulders', 'smith machine', 'Adjust the seat height of the smith machine so that the bar is at shoulder level. Stand with your feet shoulder-width apart and your knees slightly bent. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Lift the bar off the rack and step back, maintaining a stable stance. Position the bar behind your head, resting on your upper traps. Keep your core engaged and your chest lifted throughout the exercise. Press the bar overhead by extending your arms, fully straightening them. Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento de la máquina Smith de modo que la barra quede a la altura de los hombros. Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Levanta la barra del soporte y da un paso atrás, manteniendo una postura estable. Coloca la barra detrás de la cabeza, apoyándola en la parte alta de los trapecios. Mantén el core activado y el pecho elevado durante todo el ejercicio. Empuja la barra por encima de la cabeza extendiendo los brazos, estirándolos por completo. Haz una breve pausa en la parte alta del movimiento, luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0772-ht8xDrP.jpg', 'videos/0772-ht8xDrP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0773', 'smith standing leg calf raise', 'lower legs', 'lower legs', 'smith machine', 'Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar. Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward. Place your hands on the bar for stability. Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la barra de la máquina Smith a una altura que te permita estar de pie con los pies planos sobre el suelo y los hombros debajo de la barra. Colócate debajo de la barra con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante. Coloca las manos sobre la barra para mayor estabilidad. Activa las pantorrillas y levanta lentamente los talones del suelo, elevando el cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/0773-6MaEjVA.jpg', 'videos/0773-6MaEjVA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0774', 'smith standing military press', 'shoulders', 'shoulders', 'smith machine', 'Stand with your feet shoulder-width apart and your knees slightly bent. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart. Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward. Press the barbell upward until your arms are fully extended overhead. Pause for a moment at the top, then slowly lower the barbell back down to shoulder level. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Levanta la barra del soporte y bájala hasta la altura de los hombros, con las palmas hacia delante. Empuja la barra hacia arriba hasta que tus brazos queden completamente extendidos por encima de la cabeza. Haz una pausa de un momento en la parte superior y luego baja lentamente la barra de nuevo hasta la altura de los hombros. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0774-jjUPrze.jpg', 'videos/0774-jjUPrze.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3142', 'smith sumo squat', 'upper legs', 'upper legs', 'smith machine', 'Set up the smith machine with the barbell at hip height. Stand with your feet wider than shoulder-width apart, toes pointing outwards. Position yourself under the barbell, resting it on your upper back and shoulders. Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees. Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Configura la máquina Smith con la barra a la altura de la cadera. Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera. Colócate debajo de la barra, apoyándola sobre la parte superior de la espalda y los hombros. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3142-dzz6BiV.jpg', 'videos/3142-dzz6BiV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1396', 'smith toe raise', 'lower legs', 'lower legs', 'smith machine', 'Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground. Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart. Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart. Engage your core and keep your back straight throughout the exercise. Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la barra de la máquina Smith a una altura que te permita pararte cómodamente con los pies planos sobre el suelo. Colócate debajo de la barra con los hombros justo debajo de ella y los pies separados a la altura de los hombros. Coloca la planta de los pies sobre una plataforma elevada o discos de peso, dejando los talones colgando fuera del borde. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Activa el core y mantén la espalda recta durante todo el ejercicio. Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'ankles', '["ankles","shins"]'::jsonb, 'calves', 'images/1396-Y4QlY8z.jpg', 'videos/1396-Y4QlY8z.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0775', 'smith upright row', 'shoulders', 'shoulders', 'smith machine', 'Stand with your feet shoulder-width apart, facing the smith machine. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and your core engaged. Pull the barbell up towards your chin, leading with your elbows. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, de frente a la máquina Smith. Agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el core activado. Tira de la barra hacia tu barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'traps', '["traps","biceps"]'::jsonb, 'delts', 'images/0775-1DN3iz4.jpg', 'videos/0775-1DN3iz4.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1308', 'smith wide grip bench press', 'chest', 'chest', 'smith machine', 'Adjust the bench to a comfortable position on the smith machine. Lie down on the bench with your feet flat on the ground. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ajusta el banco a una posición cómoda en la máquina Smith. Túmbate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos hacia afuera a los costados. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1308-zoOvPcx.jpg', 'videos/1308-zoOvPcx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1309', 'smith wide grip decline bench press', 'chest', 'chest', 'smith machine', 'Adjust the decline bench to the desired angle. Lie down on the bench with your feet secured under the foot pads. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart. Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards. Pause for a moment when the barbell touches your chest. Push the barbell back up to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ajusta el banco declinado al ángulo deseado. Túmbate en el banco con los pies asegurados bajo las almohadillas para los pies. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Desengancha la barra y bájala lentamente hacia tu pecho, manteniendo los codos apuntando hacia afuera. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1309-wi2H9QX.jpg', 'videos/1309-wi2H9QX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0776', 'snatch pull', 'upper legs', 'upper legs', 'barbell', 'Stand with your feet shoulder-width apart and the barbell on the ground in front of you. Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip. Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees. As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides. As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position. Catch the barbell overhead with your arms fully extended and your knees bent. Stand up by extending your hips and knees, keeping the barbell overhead. Lower the barbell back down to the starting position by reversing the movement. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti. Flexiona las rodillas y dobla las caderas para bajar a una posición de sentadilla, agarrando la barra con un agarre prono. Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas. Cuando la barra llegue a la altura de la cadera, tira de ella hacia arriba de forma explosiva, encogiendo los hombros y llevando los codos altos y hacia los lados. Cuando la barra alcance su punto más alto, baja rápidamente debajo de ella, llevando tu cuerpo a una posición de sentadilla profunda. Recibe la barra por encima de la cabeza con los brazos completamente extendidos y las rodillas flexionadas. Ponte de pie extendiendo las caderas y las rodillas, manteniendo la barra por encima de la cabeza. Baja la barra de nuevo a la posición inicial invirtiendo el movimiento. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes","calves"]'::jsonb, 'quads', 'images/0776-dG5Smob.jpg', 'videos/0776-dG5Smob.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0777', 'spell caster', 'waist', 'waist', 'dumbbell', 'Stand with your feet shoulder-width apart and hold a dumbbell in one hand. Bend your knees slightly and hinge forward at the waist, keeping your back straight. Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so. Return to the starting position and repeat on the other side. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta. Extiende el brazo con la mancuerna hacia el pie opuesto, rotando el torso mientras lo haces. Regresa a la posición inicial y repite del otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0777-p9cCe2r.jpg', 'videos/0777-p9cCe2r.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1362', 'sphinx', 'back', 'back', 'body weight', 'Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders. Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor. Hold this position for a few seconds, making sure to keep your neck in a neutral position. Slowly lower your chest back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo en el suelo con los antebrazos planos sobre el piso y los codos justo debajo de los hombros. Activa el core y levanta el pecho del suelo, manteniendo los antebrazos y los dedos de los pies en el piso. Mantén esta posición durante unos segundos, asegurándote de mantener el cuello en una posición neutral. Baja lentamente el pecho de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'spine', 'images/1362-DIVyqrU.jpg', 'videos/1362-DIVyqrU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0778', 'spider crawl push up', 'upper legs', 'upper legs', 'body weight', 'Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together. Bring your right knee towards your right elbow, keeping it off the ground. As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows. Push back up to the starting position and repeat with your left knee towards your left elbow. Continue alternating sides for the desired number of repetitions.', 'Comienza en posición de flexión con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Lleva la rodilla derecha hacia el codo derecho, manteniéndola elevada del suelo. Mientras llevas la rodilla derecha hacia atrás, baja simultáneamente el cuerpo hacia el suelo flexionando los codos. Empuja de nuevo hacia arriba a la posición inicial y repite llevando la rodilla izquierda hacia el codo izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'core', '["core","chest","shoulders"]'::jsonb, 'glutes', 'images/0778-P9GFBME.jpg', 'videos/0778-P9GFBME.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1363', 'spine stretch', 'back', 'back', 'body weight', 'Sit on the ground with your legs extended in front of you. Place your hands on the ground behind you, fingers pointing towards your body. Engage your core and slowly lean back, keeping your back straight. Continue leaning back until you feel a stretch in your spine. Hold the stretch for a few seconds, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el suelo con las piernas extendidas frente a ti. Coloca las manos en el suelo detrás de ti, con los dedos apuntando hacia tu cuerpo. Activa el core e inclínate lentamente hacia atrás, manteniendo la espalda recta. Sigue inclinándote hacia atrás hasta que sientas un estiramiento en la columna. Mantén el estiramiento durante unos segundos, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'spine', 'images/1363-JbC2iaV.jpg', 'videos/1363-JbC2iaV.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2329', 'spine twist', 'waist', 'waist', 'body weight', 'Sit on the ground with your legs extended in front of you. Bend your knees and place your feet flat on the ground, hip-width apart. Place your hands behind your head with your elbows pointing outwards. Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee. Pause for a moment at the end of the twist, then slowly return to the starting position. Repeat the twist to the left side, bringing your left elbow towards your right knee. Continue alternating sides for the desired number of repetitions.', 'Siéntate en el suelo con las piernas extendidas frente a ti. Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activa el abdomen y gira lentamente el torso hacia la derecha, llevando el codo derecho hacia la rodilla izquierda. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el giro hacia el lado izquierdo, llevando el codo izquierdo hacia la rodilla derecha. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/2329-2jl9K55.jpg', 'videos/2329-2jl9K55.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2368', 'split squats', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart. Take a step forward with one foot and place it about two feet in front of the other foot. Lower your body by bending your knees and hips, keeping your back straight. Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground. Pause for a moment, then push through your front heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs and repeat.', 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso adelante con un pie y colócalo aproximadamente a dos pies de distancia por delante del otro pie. Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta. Sigue bajando hasta que el muslo delantero quede paralelo al suelo y la rodilla trasera quede justo por encima del suelo. Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/2368-9E25EOx.jpg', 'videos/2368-9E25EOx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0786', 'squat jerk', 'upper legs', 'upper legs', 'barbell', 'Start with the barbell resting on your shoulders, with your feet shoulder-width apart. Lower your body into a squat position, keeping your chest up and your knees tracking over your toes. As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead. As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back. Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground. Stand up from the split position, bringing your feet back together. Lower the barbell back to your shoulders and repeat for the desired number of repetitions.', 'Comienza con la barra apoyada sobre los hombros y los pies separados a la altura de los hombros. Baja el cuerpo a una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con la punta de los pies. Al llegar al punto más bajo de la sentadilla, empuja con fuerza a través de las piernas y eleva la barra por encima de la cabeza. Cuando la barra alcance su punto más alto, baja rápidamente a una posición de zancada dividida, con un pie adelante y otro atrás. Recibe la barra por encima de la cabeza con los brazos completamente extendidos y la rodilla trasera tocando ligeramente el suelo. Ponte de pie desde la posición dividida, juntando de nuevo los pies. Baja la barra de nuevo a los hombros y repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves","core"]'::jsonb, 'quads', 'images/0786-IMRsOCn.jpg', 'videos/0786-IMRsOCn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1705', 'squat on bosu ball', 'upper legs', 'upper legs', 'bosu ball', 'Place the bosu ball on the ground with the flat side up. Stand with your feet shoulder-width apart and position yourself on top of the bosu ball. Lower your body down by bending your knees and hips, as if sitting back into a chair. Keep your chest up and your weight on your heels. Lower yourself until your thighs are parallel to the ground. Pause for a moment, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Coloca el bosu en el suelo con el lado plano hacia arriba. Ponte de pie con los pies separados a la altura de los hombros y colócate encima del bosu. Baja el cuerpo flexionando las rodillas y las caderas, como si te sentaras en una silla. Mantén el pecho elevado y el peso en los talones. Baja hasta que los muslos queden paralelos al suelo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/1705-T2fA5Ir.jpg', 'videos/1705-T2fA5Ir.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1685', 'squat to overhead reach', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart and toes slightly turned out. Lower your body down into a squat position by bending your knees and pushing your hips back. As you come up from the squat, extend your arms overhead, reaching towards the ceiling. Return to the starting position by lowering your arms and bending your knees to squat down again. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Mientras te levantas de la sentadilla, extiende los brazos por encima de la cabeza, alcanzando hacia el techo. Vuelve a la posición inicial bajando los brazos y flexionando las rodillas para volver a hacer la sentadilla. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","core"]'::jsonb, 'quads', 'images/1685-QChZi3x.jpg', 'videos/1685-QChZi3x.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1686', 'squat to overhead reach with twist', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart and toes slightly turned out. Lower your body into a squat position by bending your knees and pushing your hips back. As you come up from the squat, raise your arms overhead and twist your torso to one side. Return to the starting position and repeat the squat, this time twisting your torso to the opposite side. Continue alternating sides with each squat repetition.', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Mientras te levantas de la sentadilla, eleva los brazos por encima de la cabeza y gira el torso hacia un lado. Vuelve a la posición inicial y repite la sentadilla, esta vez girando el torso hacia el lado opuesto. Continúa alternando los lados en cada repetición de la sentadilla.', 'glutes', '["glutes","hamstrings","core"]'::jsonb, 'quads', 'images/1686-5BZHW9s.jpg', 'videos/1686-5BZHW9s.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2297', 'stability ball crunch (full range hands behind head)', 'waist', 'waist', 'stability ball', 'Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees. Pause for a moment at the top, then slowly lower your upper body back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, curva lentamente la parte superior del cuerpo hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/2297-Gn5FwYT.jpg', 'videos/2297-Gn5FwYT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3291', 'stalder press', 'upper arms', 'upper arms', 'body weight', 'Start by standing with your feet shoulder-width apart and your arms extended overhead. Bend your knees slightly and engage your core. Lower your body down into a squat position while keeping your arms extended overhead. As you squat down, press your arms down towards the ground, engaging your triceps. Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead. Repeat for the desired number of repetitions.', 'Comienza de pie con los pies separados a la altura de los hombros y los brazos extendidos por encima de la cabeza. Flexiona ligeramente las rodillas y activa el core. Baja el cuerpo a una posición de sentadilla mientras mantienes los brazos extendidos por encima de la cabeza. Mientras bajas en la sentadilla, empuja los brazos hacia el suelo, activando los tríceps. Haz una pausa de un momento en la parte baja de la sentadilla, luego empuja con los talones para levantarte mientras al mismo tiempo elevas de nuevo los brazos por encima de la cabeza. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","core"]'::jsonb, 'triceps', 'images/3291-zd4P4B2.jpg', 'videos/3291-zd4P4B2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3669', 'standing archer', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart and your knees slightly bent. Extend your arms straight out in front of you at shoulder height, parallel to the ground. Rotate your torso to the right, keeping your arms extended and your back straight. As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring. Hold the position for a moment, then return to the starting position. Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back. Continue alternating sides for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Extiende los brazos rectos hacia adelante a la altura de los hombros, paralelos al suelo. Gira el torso hacia la derecha, manteniendo los brazos extendidos y la espalda recta. Mientras giras, extiende el brazo derecho hacia adelante y el brazo izquierdo hacia atrás, imitando el movimiento de tensar un arco. Mantén la posición por un momento y luego vuelve a la posición inicial. Repite el movimiento, esta vez girando el torso hacia la izquierda y extendiendo el brazo izquierdo hacia adelante y el brazo derecho hacia atrás. Continúa alternando lados durante el número de repeticiones deseado.', 'shoulders', '["shoulders","biceps","forearms"]'::jsonb, 'upper back', 'images/3669-JF8AkMX.jpg', 'videos/3669-JF8AkMX.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0788', 'standing behind neck press', 'shoulders', 'shoulders', 'barbell', 'Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip. Keep your back straight and core engaged. Press the barbell overhead by extending your arms, fully extending your elbows. Pause for a moment at the top, then slowly lower the barbell back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra detrás del cuello con un agarre prono. Mantén la espalda recta y el core activado. Empuja la barra por encima de la cabeza extendiendo los brazos, estirando completamente los codos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0788-xDh0lJr.jpg', 'videos/0788-xDh0lJr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1490', 'standing calf raise (on a staircase)', 'lower legs', 'lower legs', 'body weight', 'Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step. Hold onto a railing or wall for balance if needed. Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie en el borde de un escalón o una plataforma firme, con los talones colgando y la punta de los pies sobre el escalón. Sujétate de una baranda o pared para mantener el equilibrio si es necesario. Levanta lentamente los talones lo más alto posible, elevando el peso de tu cuerpo sobre la punta de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'ankles', '["ankles","feet"]'::jsonb, 'calves', 'images/1490-6HmFgmx.jpg', 'videos/1490-6HmFgmx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1397', 'standing calves', 'lower legs', 'lower legs', 'body weight', 'Stand with your feet shoulder-width apart, toes pointing forward. Raise your heels off the ground as high as possible, standing on your toes. Hold the position for a moment, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante. Levanta los talones del suelo lo más alto posible, apoyándote sobre la punta de los pies. Mantén la posición por un momento y luego baja lentamente los talones de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1397-XIHEoCG.jpg', 'videos/1397-XIHEoCG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1398', 'standing calves calf stretch', 'lower legs', 'lower legs', 'body weight', 'Stand facing a wall or sturdy object, about an arm''s length away. Place your hands on the wall or object at shoulder height. Step back with one foot, keeping your heel flat on the ground. Bend your front knee slightly and lean forward, keeping your back leg straight. You should feel a stretch in your calf muscle. Hold the stretch for 20-30 seconds. Repeat on the other leg.', 'Ponte de pie frente a una pared u objeto firme, a una distancia aproximada de un brazo. Coloca las manos sobre la pared o el objeto a la altura de los hombros. Da un paso hacia atrás con un pie, manteniendo el talón plano sobre el suelo. Flexiona ligeramente la rodilla delantera e inclínate hacia adelante, manteniendo la pierna trasera recta. Deberías sentir un estiramiento en el músculo de la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Repite con la otra pierna.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/1398-qOKcgVP.jpg', 'videos/1398-qOKcgVP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1599', 'standing hamstring and calf stretch with strap', 'upper legs', 'upper legs', 'rope', 'Stand upright with your feet shoulder-width apart. Hold the strap with both hands and place it around the ball of your foot. Keep your leg straight and slowly lean forward from your hips, keeping your back straight. Feel the stretch in your hamstring and calf muscles. Hold the stretch for 20-30 seconds. Release the stretch and repeat with the other leg. Repeat for the desired number of repetitions.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Sostén la correa con ambas manos y colócala alrededor de la parte anterior de la planta del pie. Mantén la pierna recta e inclínate lentamente hacia adelante desde las caderas, manteniendo la espalda recta. Siente el estiramiento en los isquiotibiales y en los músculos de la pantorrilla. Mantén el estiramiento durante 20-30 segundos. Suelta el estiramiento y repite con la otra pierna. Repite el número de repeticiones deseado.', 'calves', '["calves"]'::jsonb, 'hamstrings', 'images/1599-xTjr103.jpg', 'videos/1599-xTjr103.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0794', 'standing lateral stretch', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart and your knees slightly bent. Extend your arms straight out to the sides, parallel to the ground. Slowly lean your upper body to one side, feeling a stretch in your side and lats. Hold the stretch for 15-30 seconds. Return to the starting position and repeat on the other side. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Extiende los brazos hacia los lados, paralelos al suelo. Inclina lentamente la parte superior del cuerpo hacia un lado, sintiendo un estiramiento en el costado y los dorsales. Mantén el estiramiento durante 15-30 segundos. Regresa a la posición inicial y repite del otro lado. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","obliques"]'::jsonb, 'lats', 'images/0794-1jXLYEw.jpg', 'videos/0794-1jXLYEw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1364', 'standing pelvic tilt', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart and your knees slightly bent. Place your hands on your hips or let them hang by your sides. Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you. Hold the position for a few seconds, then release and return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Coloca las manos sobre las caderas o déjalas colgar a los lados. Activa los músculos del core e inclina la pelvis hacia adelante, empujando la zona lumbar hacia la pared detrás de ti. Mantén la posición durante unos segundos, luego suelta y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'abdominals', '["abdominals"]'::jsonb, 'spine', 'images/1364-cuKYxhu.jpg', 'videos/1364-cuKYxhu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0795', 'standing single leg curl', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet hip-width apart and your hands on your hips. Shift your weight onto your left leg and lift your right foot off the ground, bending your knee. Slowly curl your right heel towards your glutes, squeezing your hamstring. Pause for a moment at the top, then slowly lower your right foot back down to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Ponte de pie con los pies separados a la altura de las caderas y las manos en las caderas. Traslada tu peso a la pierna izquierda y levanta el pie derecho del suelo, flexionando la rodilla. Curva lentamente el talón derecho hacia los glúteos, contrayendo el isquiotibial. Haz una pausa de un momento en la parte superior y luego baja lentamente el pie derecho de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'glutes', '["glutes"]'::jsonb, 'hamstrings', 'images/0795-C5jncD2.jpg', 'videos/0795-C5jncD2.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0796', 'standing wheel rollerout', 'waist', 'waist', 'wheel roller', 'Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you. Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged. Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible. Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position. Repeat for the desired number of repetitions.', 'Comienza de pie, erguido, con los pies separados a la altura de los hombros y el rodillo frente a ti. Dobla la cintura y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el core activado. Continúa rodando hacia adelante hasta sentir un estiramiento en el abdomen y que tu cuerpo esté extendido lo máximo posible. Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia tu cuerpo, volviendo a la posición inicial. Repite el número de repeticiones deseado.', 'lower back', '["lower back","shoulders"]'::jsonb, 'abs', 'images/0796-KtRomty.jpg', 'videos/0796-KtRomty.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3223', 'star jump (male)', 'cardio', 'cardio', 'body weight', 'Stand with your feet shoulder-width apart and your arms by your sides. Bend your knees slightly and jump up explosively. As you jump, spread your legs and extend your arms out to the sides, forming a star shape with your body. Land softly on the balls of your feet with your knees slightly bent. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados. Flexiona ligeramente las rodillas y salta hacia arriba de forma explosiva. Mientras saltas, separa las piernas y extiende los brazos hacia los lados, formando una figura de estrella con tu cuerpo. Aterriza suavemente sobre la punta de los pies con las rodillas ligeramente flexionadas. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/3223-HtfCpfi.jpg', 'videos/3223-HtfCpfi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2138', 'stationary bike run v. 3', 'cardio', 'cardio', 'stationary bike', 'Adjust the seat height and position to ensure proper alignment. Place your feet on the pedals and secure them with the straps if available. Start pedaling at a comfortable pace. Maintain a steady rhythm and increase the resistance as desired. Engage your core muscles to maintain stability and proper posture. Continue pedaling for the desired duration of your workout. Gradually decrease the resistance and slow down before coming to a complete stop. Stretch your legs and cool down after the workout.', 'Ajusta la altura y la posición del asiento para asegurar una alineación correcta. Coloca los pies sobre los pedales y sujétalos con las correas si están disponibles. Comienza a pedalear a un ritmo cómodo. Mantén un ritmo constante y aumenta la resistencia según lo desees. Activa los músculos del core para mantener la estabilidad y una postura correcta. Continúa pedaleando durante la duración deseada de tu entrenamiento. Disminuye gradualmente la resistencia y reduce la velocidad antes de detenerte por completo. Estira las piernas y enfría después del entrenamiento.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/2138-H1PESYI.jpg', 'videos/2138-H1PESYI.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0798', 'stationary bike walk', 'cardio', 'cardio', 'leverage machine', 'Adjust the seat height and position on the stationary bike to ensure proper alignment. Place your feet on the pedals and secure them with the straps if available. Start pedaling at a comfortable pace, keeping your back straight and core engaged. Maintain a steady rhythm and increase the resistance level if desired. Continue pedaling for the desired duration of your cardio workout. Cool down by gradually reducing your pace and resistance level. Stretch your leg muscles after the workout to prevent tightness and promote recovery.', 'Ajusta la altura y la posición del asiento en la bicicleta estática para asegurar una alineación correcta. Coloca los pies sobre los pedales y sujétalos con las correas si están disponibles. Comienza a pedalear a un ritmo cómodo, manteniendo la espalda recta y el core activado. Mantén un ritmo constante y aumenta el nivel de resistencia si lo deseas. Continúa pedaleando durante la duración deseada de tu entrenamiento cardiovascular. Enfría reduciendo gradualmente tu ritmo y el nivel de resistencia. Estira los músculos de las piernas después del entrenamiento para prevenir la rigidez y favorecer la recuperación.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/0798-a8VDgLw.jpg', 'videos/0798-a8VDgLw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3314', 'straddle maltese', 'waist', 'waist', 'body weight', 'Start by hanging from a pair of rings with your arms fully extended and your body in a straight line. Spread your legs wide apart, forming a straddle position. Engage your core and slowly lower your body until your arms are parallel to the ground. Hold this position for a few seconds, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Comienza colgándote de un par de anillas con los brazos completamente extendidos y el cuerpo en línea recta. Separa bien las piernas, formando una posición a horcajadas. Activa el core y baja lentamente el cuerpo hasta que los brazos queden paralelos al suelo. Mantén esta posición durante unos segundos, luego empújate de nuevo hacia arriba a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","chest"]'::jsonb, 'abs', 'images/3314-HfqciZF.jpg', 'videos/3314-HfqciZF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3298', 'straddle planche', 'waist', 'waist', 'body weight', 'Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart. Engage your core and slowly shift your weight forward, bringing your shoulders over your hands. Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides. Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position. Repeat for the desired number of repetitions.', 'Comienza en posición de flexión con las manos separadas a la altura de los hombros y los pies bien separados. Activa el core y traslada lentamente tu peso hacia adelante, llevando los hombros por encima de las manos. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps","chest"]'::jsonb, 'abs', 'images/3298-BL3GHeY.jpg', 'videos/3298-BL3GHeY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1427', 'straight leg outer hip abductor', 'upper legs', 'upper legs', 'body weight', 'Lie on your side with your legs straight and stacked on top of each other. Place your bottom arm under your head for support. Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward. Pause for a moment at the top, then slowly lower your leg back down to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Túmbate de lado con las piernas rectas y apiladas una sobre la otra. Coloca el brazo de abajo bajo la cabeza para apoyarte. Activa el core y levanta la pierna superior lo más alto posible sin rotar las caderas ni inclinarte hacia atrás. Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'abductors', 'images/1427-mQ1tBXn.jpg', 'videos/1427-mQ1tBXn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0803', 'superman push-up', 'chest', 'chest', 'body weight', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together. Engage your core and lower your body towards the ground, keeping your elbows close to your sides. As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out. Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position. Repeat the movement, this time lifting your left arm and right leg. Continue alternating sides for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Mientras bajas el cuerpo, levanta simultáneamente el brazo derecho y la pierna izquierda del suelo, extendiéndolos completamente. Haz una pausa de un momento en la parte superior, luego baja el brazo y la pierna mientras te empujas de nuevo hacia arriba a la posición inicial. Repite el movimiento, esta vez levantando el brazo izquierdo y la pierna derecha. Continúa alternando lados durante el número de repeticiones deseado.', 'core', '["core","shoulders"]'::jsonb, 'pectorals', 'images/0803-4GqRrAk.jpg', 'videos/0803-4GqRrAk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0805', 'suspended abdominal fallout', 'waist', 'waist', 'body weight', 'Attach a suspension trainer to a high anchor point and adjust the straps to waist height. Stand facing away from the anchor point and hold the handles with your arms extended in front of you. Lean forward at the waist, keeping your body straight and your core engaged. Lower your body as far as you can while maintaining control and tension in your abs. Pause for a moment at the bottom, then slowly raise your body back up to the starting position. Repeat for the desired number of repetitions.', 'Sujeta un entrenador de suspensión a un punto de anclaje alto y ajusta las correas a la altura de la cintura. Ponte de pie de espaldas al punto de anclaje y sostén las asas con los brazos extendidos frente a ti. Inclínate hacia adelante desde la cintura, manteniendo el cuerpo recto y el core activado. Baja el cuerpo todo lo que puedas mientras mantienes el control y la tensión en el abdomen. Haz una pausa de un momento en la parte baja, luego eleva lentamente el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques","hip flexors"]'::jsonb, 'abs', 'images/0805-X3TCNEU.jpg', 'videos/0805-X3TCNEU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0806', 'suspended push-up', 'chest', 'chest', 'body weight', 'Find a suspension trainer and adjust it to an appropriate height. Stand facing away from the anchor point and hold the handles with an overhand grip. Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer. Keep your body straight from head to heels, engage your core, and lower your chest towards the handles. Push through your chest and arms to return to the starting position. Repeat for the desired number of repetitions.', 'Busca un entrenador de suspensión y ajústalo a una altura adecuada. Ponte de pie de espaldas al punto de anclaje y sostén las asas con un agarre prono. Camina hacia adelante con los pies, inclinando el cuerpo hacia adelante hasta que tu peso quede sostenido por el entrenador de suspensión. Mantén el cuerpo recto desde la cabeza hasta los talones, activa el core y baja el pecho hacia las asas. Empuja con el pecho y los brazos para volver a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders","core"]'::jsonb, 'pectorals', 'images/0806-IaGQCrC.jpg', 'videos/0806-IaGQCrC.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0807', 'suspended reverse crunch', 'waist', 'waist', 'body weight', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage. Pause for a moment at the top, then slowly lower your knees back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y sube las rodillas hacia el pecho, curvando la pelvis hacia la caja torácica. Haz una pausa de un momento en la parte superior, luego baja lentamente las rodillas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0807-R1WYG5D.jpg', 'videos/0807-R1WYG5D.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0808', 'suspended row', 'back', 'back', 'body weight', 'Set up a suspension trainer at an appropriate height. Stand facing the anchor point with your feet shoulder-width apart. Hold the handles with an overhand grip, palms facing each other. Lean back, keeping your body straight and your heels on the ground. Pull your chest towards the handles, squeezing your shoulder blades together. Pause for a moment at the top, then slowly lower yourself back to the starting position. Repeat for the desired number of repetitions.', 'Coloca un entrenador de suspensión a una altura adecuada. Ponte de pie frente al punto de anclaje con los pies separados a la altura de los hombros. Sostén las asas con un agarre prono, con las palmas mirándose entre sí. Inclínate hacia atrás, manteniendo el cuerpo recto y los talones en el suelo. Tira del pecho hacia las asas, apretando los omóplatos entre sí. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","shoulders"]'::jsonb, 'upper back', 'images/0808-4OaumBr.jpg', 'videos/0808-4OaumBr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0809', 'suspended split squat', 'upper legs', 'upper legs', 'body weight', 'Stand facing away from a suspension trainer with your feet shoulder-width apart. Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer. Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes. Push through your heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', 'Ponte de pie de espaldas a un entrenador de suspensión con los pies separados a la altura de los hombros. Extiende una pierna hacia adelante y coloca el empeine del pie en el soporte para pie del entrenador de suspensión. Flexiona la pierna de apoyo y baja el cuerpo a una posición de zancada, manteniendo el pecho elevado y la rodilla alineada con la punta del pie. Empuja con el talón para regresar a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/0809-QpXqiq8.jpg', 'videos/0809-QpXqiq8.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3433', 'swimmer kicks v. 2 (male)', 'upper legs', 'upper legs', 'body weight', 'Lie face down on a mat with your arms extended overhead. Engage your core and lift your chest and legs off the ground simultaneously. Kick your legs up and down in a fluttering motion, as if you were swimming. Continue kicking for the desired number of repetitions. Lower your chest and legs back down to the starting position.', 'Túmbate boca abajo sobre una esterilla con los brazos extendidos por encima de la cabeza. Activa el core y levanta el pecho y las piernas del suelo al mismo tiempo. Mueve las piernas hacia arriba y hacia abajo con un movimiento de aleteo, como si estuvieras nadando. Continúa el movimiento de patada el número de repeticiones deseado. Baja el pecho y las piernas de nuevo a la posición inicial.', 'hamstrings', '["hamstrings","quadriceps","calves"]'::jsonb, 'glutes', 'images/3433-SP3hUez.jpg', 'videos/3433-SP3hUez.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3318', 'swing 360', 'cardio', 'cardio', 'body weight', 'Stand with your feet shoulder-width apart and knees slightly bent. Hold your arms straight out in front of you, parallel to the ground. Engage your core and swing your arms in a circular motion, rotating your torso as you do so. Continue the circular motion, swinging your arms and rotating your torso for the desired number of repetitions. Remember to breathe throughout the exercise.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Mantén los brazos extendidos rectos frente a ti, paralelos al suelo. Activa el core y mueve los brazos en un movimiento circular, rotando el torso mientras lo haces. Continúa el movimiento circular, moviendo los brazos y rotando el torso el número de repeticiones deseado. Recuerda respirar durante todo el ejercicio.', 'shoulders', '["shoulders","core"]'::jsonb, 'cardiovascular system', 'images/3318-tnaj0mT.jpg', 'videos/3318-tnaj0mT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1753', 'three bench dip', 'upper arms', 'upper arms', 'body weight', 'Sit on a bench with your hands gripping the edge, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Bend your elbows and lower your body until your upper arms are parallel to the ground. Push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo. Empújate de vuelta hacia arriba hasta la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1753-DQ0cqkT.jpg', 'videos/1753-DQ0cqkT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2459', 'tire flip', 'upper legs', 'upper legs', 'tire', 'Stand with your feet shoulder-width apart, facing the tire. Bend your knees and hinge at the hips, lowering into a squat position. Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you. Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground. As the tire flips over, use your upper body strength to guide it and maintain control. Once the tire is fully flipped, quickly step back and reset your stance. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, de frente al neumático. Flexiona las rodillas y dobla las caderas, bajando a una posición de sentadilla. Agáchate y agarra el borde inferior del neumático con ambas manos, con los dedos apuntando hacia ti. Activa los glúteos y los músculos de las piernas, y empuja con fuerza a través de las piernas para levantar el neumático del suelo. Mientras el neumático se voltea, usa la fuerza de la parte superior del cuerpo para guiarlo y mantener el control. Una vez que el neumático esté completamente volteado, retrocede rápidamente y reinicia tu postura. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","core"]'::jsonb, 'glutes', 'images/2459-oZjMu1t.jpg', 'videos/2459-oZjMu1t.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0811', 'trap bar deadlift', 'upper legs', 'upper legs', 'trap bar', 'Stand with your feet shoulder-width apart and the trap bar on the ground in front of you. Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip. Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees. As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement. Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y la barra hexagonal en el suelo frente a ti. Flexiona las caderas y las rodillas para bajar y agarra las asas de la barra hexagonal con un agarre prono. Mantén la espalda recta y el pecho elevado mientras comienzas a levantar la barra hexagonal del suelo extendiendo las caderas y las rodillas. Al levantar, concéntrate en empujar con los talones y contraer los glúteos en la parte superior del movimiento. Baja la barra hexagonal de nuevo al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta durante todo el movimiento. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","quadriceps","lower back"]'::jsonb, 'glutes', 'images/0811-jQGwmxN.jpg', 'videos/0811-jQGwmxN.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0814', 'triceps dip', 'upper arms', 'upper arms', 'body weight', 'Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Bend your elbows and lower your body towards the ground, keeping your back close to the bench. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0814-X6C6i5Y.jpg', 'videos/0814-X6C6i5Y.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0812', 'triceps dip (bench leg)', 'upper arms', 'upper arms', 'body weight', 'Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward. Walk your feet forward, sliding your butt off the bench, and straighten your arms. Bend your elbows and lower your body towards the ground, keeping your back close to the bench. Push through your palms to straighten your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante. Camina con los pies hacia adelante, deslizando los glúteos fuera del banco, y estira los brazos. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Empuja con las palmas para estirar los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0812-VuoerH0.jpg', 'videos/0812-VuoerH0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0813', 'triceps dip (between benches)', 'upper arms', 'upper arms', 'body weight', 'Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Bend your elbows and lower your body towards the ground, keeping your back close to the bench. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en un banco con las manos agarrando el borde del banco, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0813-Wgbn9qo.jpg', 'videos/0813-Wgbn9qo.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0815', 'triceps dips floor', 'upper arms', 'upper arms', 'body weight', 'Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward. Slide your butt off the front of the chair with your legs extended in front of you. Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints. Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle. Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el borde de una silla o banco con las manos junto a las caderas, los dedos apuntando hacia adelante. Desliza los glúteos fuera del frente de la silla con las piernas extendidas frente a ti. Estira los brazos, manteniendo una ligera flexión en los codos para conservar la tensión en los tríceps y aliviarla en las articulaciones del codo. Flexiona lentamente los codos para bajar el cuerpo hacia el suelo hasta que los codos formen un ángulo de aproximadamente 90 grados. Cuando llegues al punto más bajo del movimiento, empuja hacia abajo contra la silla para estirar los codos, volviendo a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0815-7aVz15j.jpg', 'videos/0815-7aVz15j.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0816', 'triceps press', 'upper arms', 'upper arms', 'body weight', 'Stand with your feet shoulder-width apart and your knees slightly bent. Extend your arms straight out in front of you, parallel to the ground. Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Extiende los brazos rectos frente a ti, paralelos al suelo. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la parte superior de los brazos cerca de los costados. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0816-fSrPP6B.jpg', 'videos/0816-fSrPP6B.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0817', 'triceps stretch', 'upper arms', 'upper arms', 'body weight', 'Stand or sit upright with your back straight. Extend one arm overhead, bending it at the elbow. Place your opposite hand on the bent elbow and gently pull it towards your head. Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps. Release the stretch and repeat on the other arm.', 'Ponte de pie o siéntate erguido con la espalda recta. Extiende un brazo por encima de la cabeza, flexionándolo por el codo. Coloca la mano opuesta sobre el codo flexionado y tira de él suavemente hacia tu cabeza. Mantén el estiramiento de 15 a 30 segundos, sintiendo un estiramiento suave en el tríceps. Suelta el estiramiento y repite con el otro brazo.', 'shoulders', '["shoulders"]'::jsonb, 'triceps', 'images/0817-uOV3Itw.jpg', 'videos/0817-uOV3Itw.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0871', 'tuck crunch', 'waist', 'waist', 'body weight', 'Lie flat on your back with your knees bent and feet flat on the ground. Place your hands behind your head with your elbows pointing outwards. Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees. Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos detrás de la cabeza con los codos apuntando hacia afuera. Activando el abdomen, levanta los omóplatos del suelo y lleva las rodillas hacia el pecho, curvando al mismo tiempo la parte superior del cuerpo hacia las rodillas. Haz una pausa de un momento en la parte superior, luego baja lentamente los omóplatos y extiende las piernas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0871-BMMolZ3.jpg', 'videos/0871-BMMolZ3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0818', 'twin handle parallel grip lat pulldown', 'back', 'back', 'cable', 'Adjust the seat height and position yourself facing the cable machine. Grasp the handles with an overhand grip, hands shoulder-width apart. Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor. Lean back slightly and keep your chest up, maintaining a neutral spine. Pull the handles down towards your upper chest, squeezing your shoulder blades together. Pause for a moment at the bottom of the movement, feeling the contraction in your lats. Slowly release the handles and return to the starting position. Repeat for the desired number of repetitions.', 'Ajusta la altura del asiento y colócate de frente a la máquina de cable. Agarra las asas con un agarre prono, con las manos separadas a la altura de los hombros. Siéntate y coloca los muslos debajo de las almohadillas para muslos, manteniendo los pies planos sobre el suelo. Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando una columna neutral. Tira de las asas hacia la parte superior del pecho, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte inferior del movimiento, sintiendo la contracción en los dorsales. Suelta lentamente las asas y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","rhomboids","rear deltoids"]'::jsonb, 'lats', 'images/0818-rkg41Fb.jpg', 'videos/0818-rkg41Fb.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1466', 'twist hip lift', 'upper legs', 'upper legs', 'body weight', 'Lie on your back with your knees bent and feet flat on the ground. Place your hands by your sides for support. Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders. While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground. Return to the starting position and repeat the twist to the left side. Continue alternating twists for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos a los lados para mayor apoyo. Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros. Manteniendo las caderas elevadas, gira la parte inferior del cuerpo hacia el lado derecho, llevando las rodillas hacia el suelo. Vuelve a la posición inicial y repite el giro hacia el lado izquierdo. Continúa alternando los giros el número de repeticiones deseado.', 'obliques', '["obliques","hamstrings"]'::jsonb, 'glutes', 'images/1466-AX1kB0o.jpg', 'videos/1466-AX1kB0o.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2802', 'twisted leg raise', 'waist', 'waist', 'body weight', 'Lie flat on your back with your legs extended and your arms by your sides. Place your hands under your glutes for support. Engage your abs and lift both legs off the ground, keeping them straight. As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat the movement, this time twisting your hips to the other side. Continue alternating sides for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Coloca las manos debajo de los glúteos como apoyo. Activa el abdomen y levanta ambas piernas del suelo, manteniéndolas rectas. Mientras levantas las piernas, gira las caderas hacia un lado, llevando las piernas hacia el hombro opuesto. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el movimiento, esta vez girando las caderas hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","hip flexors"]'::jsonb, 'abs', 'images/2802-C0eCeEt.jpg', 'videos/2802-C0eCeEt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2801', 'twisted leg raise (female)', 'waist', 'waist', 'body weight', 'Lie flat on your back with your legs extended and your arms by your sides. Bend your knees and lift your legs off the ground, bringing them towards your chest. As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat the movement, this time twisting your hips to the other side. Continue alternating sides for the desired number of repetitions.', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Flexiona las rodillas y levanta las piernas del suelo, llevándolas hacia el pecho. Mientras levantas las piernas, gira las caderas hacia un lado, llevando las rodillas hacia el hombro opuesto. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el movimiento, esta vez girando las caderas hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","hip flexors"]'::jsonb, 'abs', 'images/2801-yT9tk17.jpg', 'videos/2801-yT9tk17.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3231', 'two toe touch (male)', 'back', 'back', 'body weight', 'Stand with your feet shoulder-width apart and your arms extended out to the sides. Bend forward at the waist, keeping your back straight and your knees slightly bent. Reach down towards your toes with both hands, keeping your legs straight. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos extendidos hacia los lados. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Estira los brazos hacia la punta de los pies con ambas manos, manteniendo las piernas rectas. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'spine', 'images/3231-p195zsJ.jpg', 'videos/3231-p195zsJ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1365', 'upper back stretch', 'back', 'back', 'body weight', 'Stand up straight with your feet shoulder-width apart. Extend your arms straight in front of you, parallel to the ground. Interlace your fingers and rotate your palms away from your body. Slowly raise your arms overhead, keeping them straight and parallel to each other. As you raise your arms, squeeze your shoulder blades together. Hold the stretch for 15-30 seconds, then release and repeat.', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Extiende los brazos rectos frente a ti, paralelos al suelo. Entrelaza los dedos y gira las palmas alejándolas de tu cuerpo. Eleva lentamente los brazos por encima de la cabeza, manteniéndolos rectos y paralelos entre sí. Mientras elevas los brazos, aprieta los omóplatos entre sí. Mantén el estiramiento de 15 a 30 segundos, luego suelta y repite.', 'shoulders', '["shoulders"]'::jsonb, 'upper back', 'images/1365-GSDioYu.jpg', 'videos/1365-GSDioYu.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1366', 'upward facing dog', 'back', 'back', 'body weight', 'Lie face down on the floor with your legs extended behind you. Place your hands on the floor next to your lower ribs, fingers pointing forward. Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground. Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling. Hold this position for a few breaths, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca abajo en el suelo con las piernas extendidas detrás de ti. Coloca las manos en el suelo junto a las costillas inferiores, con los dedos apuntando hacia adelante. Presiona las manos firmemente contra el suelo y estira los brazos, levantando el torso y los muslos del suelo. Lleva los hombros hacia atrás y hacia abajo, abriendo el pecho y elevando la mirada hacia el techo. Mantén esta posición durante unas cuantas respiraciones, luego baja lentamente el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","chest"]'::jsonb, 'spine', 'images/1366-01qpYSe.jpg', 'videos/1366-01qpYSe.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3420', 'v-sit on floor', 'waist', 'waist', 'body weight', 'Sit on the floor with your legs extended in front of you. Lean back slightly and lift your legs off the ground, keeping them straight. Simultaneously, lift your upper body off the ground and reach your arms towards your legs. Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el suelo con las piernas extendidas frente a ti. Inclínate ligeramente hacia atrás y levanta las piernas del suelo, manteniéndolas rectas. Al mismo tiempo, levanta la parte superior del cuerpo del suelo y extiende los brazos hacia las piernas. Mantén esta posición durante unos segundos, luego baja lentamente la parte superior del cuerpo y las piernas de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/3420-ZuXu4Eq.jpg', 'videos/3420-ZuXu4Eq.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0826', 'vertical leg raise (on parallel bars)', 'waist', 'waist', 'body weight', 'Hang from the parallel bars with your arms fully extended and your body straight. Engage your core and lift your legs up in front of you, keeping them straight. Continue lifting until your legs are parallel to the ground or slightly higher. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de las barras paralelas con los brazos completamente extendidos y el cuerpo recto. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors"]'::jsonb, 'abs', 'images/0826-ZNgOYQU.jpg', 'videos/0826-ZNgOYQU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2141', 'walk elliptical cross trainer', 'cardio', 'cardio', 'elliptical machine', 'Adjust the resistance level and incline of the elliptical machine to your desired settings. Step onto the pedals of the machine and grip the handles lightly. Begin by pushing down with your feet and pulling the handles towards your body. Continue this motion, alternating between pushing and pulling, to simulate a walking or running motion. Maintain a steady pace and keep your core engaged throughout the exercise. Continue for the desired duration of your cardio workout. Gradually decrease the intensity and speed of the machine before stepping off.', 'Ajusta el nivel de resistencia y la inclinación de la máquina elíptica a los valores deseados. Sube a los pedales de la máquina y agarra las asas con suavidad. Comienza empujando hacia abajo con los pies y tirando de las asas hacia tu cuerpo. Continúa con este movimiento, alternando entre empujar y tirar, para simular un movimiento de caminar o correr. Mantén un ritmo constante y conserva el core activado durante todo el ejercicio. Continúa durante la duración deseada de tu entrenamiento cardiovascular. Disminuye gradualmente la intensidad y la velocidad de la máquina antes de bajarte.', 'quadriceps', '["quadriceps","hamstrings","glutes","calves"]'::jsonb, 'cardiovascular system', 'images/2141-rjtuP6X.jpg', 'videos/2141-rjtuP6X.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3655', 'walking high knees lunge', 'cardio', 'cardio', 'body weight', 'Stand with your feet hip-width apart. Lift your right knee up towards your chest as high as you can while balancing on your left leg. Step forward with your right foot and lower your body into a lunge position, bending both knees to a 90-degree angle. Push off with your right foot and bring your left knee up towards your chest. Step forward with your left foot and lower your body into a lunge position. Continue alternating legs and lunging forward, keeping your core engaged and maintaining a steady pace. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de la cadera. Levanta la rodilla derecha hacia el pecho lo más alto que puedas mientras mantienes el equilibrio sobre la pierna izquierda. Da un paso adelante con el pie derecho y baja el cuerpo a una posición de zancada, flexionando ambas rodillas a un ángulo de 90 grados. Empújate con el pie derecho y lleva la rodilla izquierda hacia el pecho. Da un paso adelante con el pie izquierdo y baja el cuerpo a una posición de zancada. Continúa alternando las piernas y avanzando con zancadas, manteniendo el core activado y un ritmo constante. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","glutes","calves"]'::jsonb, 'cardiovascular system', 'images/3655-J9zIWig.jpg', 'videos/3655-J9zIWig.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1460', 'walking lunge', 'upper legs', 'upper legs', 'body weight', 'Stand with your feet shoulder-width apart. Take a step forward with your right leg, lowering your body into a lunge position. Keep your torso upright and your front knee aligned with your ankle. Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg. Continue alternating legs and walking forward, maintaining a controlled and steady pace. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso adelante con la pierna derecha, bajando el cuerpo a una posición de zancada. Mantén el torso erguido y la rodilla delantera alineada con el tobillo. Empújate con el pie derecho y lleva el pie izquierdo hacia adelante, entrando en una posición de zancada con la pierna izquierda. Continúa alternando las piernas y avanzando, manteniendo un ritmo controlado y constante. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/1460-IZVHb27.jpg', 'videos/1460-IZVHb27.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3666', 'walking on incline treadmill', 'cardio', 'cardio', 'leverage machine', 'Adjust the incline level on the treadmill to your desired intensity. Stand on the treadmill with your feet shoulder-width apart. Start walking at a comfortable pace, ensuring that you maintain proper form. Engage your core muscles and keep your back straight throughout the exercise. Continue walking on the incline treadmill for the desired duration of your cardio workout. Gradually decrease the incline and speed of the treadmill to cool down before stopping.', 'Ajusta el nivel de inclinación de la cinta de correr a la intensidad deseada. Ponte de pie sobre la cinta de correr con los pies separados a la altura de los hombros. Comienza a caminar a un ritmo cómodo, asegurándote de mantener una forma correcta. Activa los músculos del core y mantén la espalda recta durante todo el ejercicio. Continúa caminando en la cinta inclinada durante la duración deseada de tu entrenamiento cardiovascular. Disminuye gradualmente la inclinación y la velocidad de la cinta para enfriar antes de detenerte.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/3666-rjiM4L3.jpg', 'videos/3666-rjiM4L3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2311', 'walking on stepmill', 'cardio', 'cardio', 'stepmill machine', 'Adjust the stepmill machine to a comfortable level. Step onto the machine and place your hands on the handrails for support. Start walking by placing one foot on a step and then the other, alternating between legs. Maintain an upright posture and engage your core muscles. Continue walking for the desired duration or distance. Gradually increase the intensity or speed as you become more comfortable with the exercise. Remember to cool down and stretch after completing the exercise.', 'Ajusta la máquina de escalones a un nivel cómodo. Sube a la máquina y coloca las manos sobre los pasamanos para apoyarte. Comienza a caminar colocando un pie en un escalón y luego el otro, alternando entre las piernas. Mantén una postura erguida y activa los músculos del core. Continúa caminando durante la duración o distancia deseada. Aumenta gradualmente la intensidad o la velocidad a medida que te sientas más cómodo con el ejercicio. Recuerda enfriar y estirar después de completar el ejercicio.', 'quadriceps', '["quadriceps","hamstrings","glutes","calves"]'::jsonb, 'cardiovascular system', 'images/2311-j9Q5crt.jpg', 'videos/2311-j9Q5crt.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0830', 'weighted bench dip', 'upper arms', 'upper arms', 'weighted', 'Sit on a bench with your hands gripping the edge, fingers pointing forward. Slide your butt off the bench, supporting your weight with your hands. Lower your body by bending your elbows until your upper arms are parallel to the floor. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/0830-MU9HnE7.jpg', 'videos/0830-MU9HnE7.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2987', 'weighted close grip chin-up on dip cage', 'back', 'back', 'weighted', 'Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart. Hang from the bars with your arms fully extended, feet off the ground, and body straight. Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides. Continue pulling until your chin is above the bars, then pause for a moment. Slowly lower your body back down to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', 'Ponte de pie frente a la jaula de fondos y agarra las barras paralelas con un agarre supino, con las manos separadas a la altura de los hombros. Cuélgate de las barras con los brazos completamente extendidos, los pies levantados del suelo y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba en dirección a las barras, manteniendo los codos cerca de los costados. Continúa tirando hasta que tu barbilla quede por encima de las barras, luego haz una pausa de un momento. Baja lentamente el cuerpo de nuevo a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/2987-Gk1r408.jpg', 'videos/2987-Gk1r408.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3643', 'weighted cossack squats (male)', 'upper legs', 'upper legs', 'weighted', 'Stand with your feet wider than shoulder-width apart and toes pointing slightly outward. Hold a weight in front of your chest with both hands. Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight. Go as low as you can while maintaining balance and keeping your chest up. Push through the heel of the bent leg to return to the starting position. Repeat on the other side, alternating between legs.', 'Ponte de pie con los pies más separados que la anchura de los hombros y la punta de los pies apuntando ligeramente hacia afuera. Sostén un peso frente al pecho con ambas manos. Traslada tu peso hacia un lado y baja el cuerpo flexionando la rodilla del lado hacia el que te inclinaste, manteniendo la otra pierna recta. Baja todo lo que puedas mientras mantienes el equilibrio y el pecho elevado. Empuja con el talón de la pierna flexionada para volver a la posición inicial. Repite con el otro lado, alternando entre las piernas.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3643-GWoKnIm.jpg', 'videos/3643-GWoKnIm.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0832', 'weighted crunch', 'waist', 'waist', 'weighted', 'Lie flat on your back with your knees bent and feet flat on the ground. Hold a weight plate or dumbbell on your chest. Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Sostén un disco de peso o una mancuerna sobre el pecho. Activa el abdomen y levanta la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que los omóplatos se separen del suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques"]'::jsonb, 'abs', 'images/0832-s8nrDXF.jpg', 'videos/0832-s8nrDXF.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3670', 'weighted decline sit-up', 'waist', 'waist', 'weighted', 'Lie flat on a decline bench with your feet secured under the foot pads. Place your hands behind your head or across your chest. Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Túmbate boca arriba en un banco declinado con los pies sujetos debajo de las almohadillas para los pies. Coloca las manos detrás de la cabeza o cruzadas sobre el pecho. Activa el abdomen y levanta lentamente la parte superior del cuerpo del banco, curvándote hacia adelante hasta que el torso quede perpendicular al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/3670-EZeDVzO.jpg', 'videos/3670-EZeDVzO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0833', 'weighted donkey calf raise', 'lower legs', 'lower legs', 'weighted', 'Stand on a raised platform with your toes on the edge and your heels hanging off. Hold onto a stable object for support. Raise your heels as high as possible by extending your ankles. Pause for a moment at the top, then slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie sobre una plataforma elevada con la punta de los pies en el borde y los talones colgando. Sujétate de un objeto estable para mayor apoyo. Eleva los talones tan alto como puedas extendiendo los tobillos. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hamstrings', '["hamstrings","glutes"]'::jsonb, 'calves', 'images/0833-LmaFNZS.jpg', 'videos/0833-LmaFNZS.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1310', 'weighted drop push up', 'chest', 'chest', 'weighted', 'Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together. Lower your chest towards the ground, keeping your elbows close to your body. Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground. As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground. Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again. Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position. Continue alternating between the wider and narrower hand positions for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos un poco más separadas que la anchura de los hombros y los pies juntos. Baja el pecho hacia el suelo, manteniendo los codos cerca del cuerpo. Cuando el pecho esté justo por encima del suelo, empújate hacia arriba de forma explosiva, levantando las manos del suelo. Mientras te empujas hacia arriba, mueve rápidamente las manos hacia los lados y un poco hacia adelante, permitiendo que tu cuerpo caiga hacia el suelo. Recíbete con las manos en la posición más ancha y baja de nuevo el pecho inmediatamente hacia el suelo. Repite el movimiento de flexión, bajando y recibiéndote con las manos en la posición más estrecha. Continúa alternando entre las posiciones de manos más ancha y más estrecha el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1310-PSlvNMs.jpg', 'videos/1310-PSlvNMs.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2135', 'weighted front plank', 'waist', 'waist', 'weighted', 'Start by lying face down on the floor. Place your forearms on the ground, with your elbows directly under your shoulders. Extend your legs straight out behind you, with your toes on the ground. Engage your core and lift your body off the ground, balancing on your forearms and toes. Keep your body in a straight line from your head to your heels. Hold this position for the desired amount of time. Lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Comienza tumbándote boca abajo en el suelo. Coloca los antebrazos en el suelo, con los codos justo debajo de los hombros. Extiende las piernas rectas hacia atrás, con la punta de los pies en el suelo. Activa el core y levanta el cuerpo del suelo, equilibrándote sobre los antebrazos y la punta de los pies. Mantén el cuerpo en línea recta desde la cabeza hasta los talones. Mantén esta posición durante el tiempo deseado. Baja el cuerpo de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","lower back"]'::jsonb, 'abs', 'images/2135-VBAWRPG.jpg', 'videos/2135-VBAWRPG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0834', 'weighted front raise', 'shoulders', 'shoulders', 'weighted', 'Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs. Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en cada mano con las palmas hacia los muslos. Manteniendo los brazos rectos, exhala y levanta las mancuernas frente a ti hasta que queden a la altura de los hombros. Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'delts', 'images/0834-e4aFmFY.jpg', 'videos/0834-e4aFmFY.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0866', 'weighted hanging leg-hip raise', 'waist', 'waist', 'weighted', 'Hang from a pull-up bar with your arms fully extended and your palms facing away from you. Engage your core and lift your legs up in front of you, keeping them straight. Continue lifting until your legs are parallel to the ground or slightly higher. Pause for a moment at the top, then slowly lower your legs back down to the starting position. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas mirando hacia afuera. Activa el core y levanta las piernas frente a ti, manteniéndolas rectas. Continúa levantando hasta que las piernas queden paralelas al suelo o un poco más arriba. Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'hip flexors', '["hip flexors","lower back"]'::jsonb, 'abs', 'images/0866-QOA0FD0.jpg', 'videos/0866-QOA0FD0.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0835', 'weighted hyperextension (on stability ball)', 'back', 'back', 'weighted', 'Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability. Place your hands behind your head or cross them over your chest. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line. Pause for a moment at the top, then slowly lower your upper body back down to the starting position. Repeat for the desired number of repetitions.', 'Colócate boca abajo sobre un balón de estabilidad con las caderas apoyadas en el balón y los pies contra una pared para mayor estabilidad. Coloca las manos detrás de la cabeza o crúzalas sobre el pecho. Activa el core y levanta lentamente la parte superior del cuerpo del balón, extendiendo la espalda hasta que tu cuerpo forme una línea recta. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings"]'::jsonb, 'spine', 'images/0835-8urJS9b.jpg', 'videos/0835-8urJS9b.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3641', 'weighted kneeling step with swing', 'shoulders', 'shoulders', 'weighted', 'Start in a kneeling position with your knees hip-width apart and your back straight. Hold a weight in each hand, with your arms extended straight down in front of you. Engage your core and swing the weights up and overhead, keeping your arms straight. Lower the weights back down to the starting position and repeat for the desired number of repetitions.', 'Comienza en posición de rodillas con las rodillas separadas a la altura de las caderas y la espalda recta. Sostén un peso en cada mano, con los brazos extendidos rectos hacia abajo frente a ti. Activa el core y balancea los pesos hacia arriba y por encima de la cabeza, manteniendo los brazos rectos. Baja los pesos de nuevo a la posición inicial y repite el número de repeticiones deseado.', 'triceps', '["triceps","core"]'::jsonb, 'delts', 'images/3641-7uFJuXp.jpg', 'videos/3641-7uFJuXp.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3644', 'weighted lunge with swing', 'upper legs', 'upper legs', 'weighted', 'Stand with your feet shoulder-width apart, holding a weight in each hand. Take a step forward with your right foot, lowering your body into a lunge position. As you lunge forward, swing the weights forward and upward, keeping your arms straight. Push off with your right foot and return to the starting position, swinging the weights back down. Repeat with your left foot and continue alternating legs for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo un peso en cada mano. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mientras avanzas en la zancada, balancea los pesos hacia adelante y hacia arriba, manteniendo los brazos rectos. Empújate con el pie derecho y vuelve a la posición inicial, balanceando los pesos de nuevo hacia abajo. Repite con el pie izquierdo y continúa alternando las piernas el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3644-5WiFcYk.jpg', 'videos/3644-5WiFcYk.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3286', 'weighted muscle up', 'back', 'back', 'weighted', 'Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart. Engage your core and pull your body up towards the bar, leading with your chest. As you reach the top of the movement, transition your grip so that your palms are facing towards you. Continue pulling yourself up until your chest reaches the bar, then pause for a moment. Slowly lower yourself back down to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions.', 'Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros. Activa el core y tira de tu cuerpo hacia arriba, hacia la barra, guiando con el pecho. Al llegar a la parte alta del movimiento, cambia el agarre de modo que las palmas queden hacia ti. Continúa subiendo hasta que el pecho llegue a la barra, luego haz una pausa de un momento. Baja lentamente de nuevo a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps","shoulders","chest"]'::jsonb, 'lats', 'images/3286-JsOV1SU.jpg', 'videos/3286-JsOV1SU.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3312', 'weighted muscle up (on bar)', 'back', 'back', 'weighted', 'Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart. Engage your core and pull your shoulder blades down and back. Bend your elbows and pull your chest towards the bar, keeping your body straight. Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar. Pause at the top of the movement, then slowly lower yourself back down to the starting position. Repeat for the desired number of repetitions.', 'Comienza colgándote de una barra de dominadas con las palmas mirando hacia afuera y las manos un poco más separadas que la anchura de los hombros. Activa el core y lleva los omóplatos hacia abajo y atrás. Flexiona los codos y tira del pecho hacia la barra, manteniendo el cuerpo recto. Cuando tu pecho llegue a la barra, empuja hacia abajo con las manos y lleva los codos hacia atrás, elevando el cuerpo por encima de la barra. Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps","shoulders","forearms"]'::jsonb, 'lats', 'images/3312-MCkqdKE.jpg', 'videos/3312-MCkqdKE.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3290', 'weighted one hand pull up', 'back', 'back', 'weighted', 'Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arm fully extended and your body straight. Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles. Continue pulling until your chin is above the bar. Lower your body back down to the starting position with control. Repeat for the desired number of repetitions.', 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros. Cuélgate de la barra con un brazo completamente extendido y el cuerpo recto. Activa el core y tira de tu cuerpo hacia arriba en dirección a la barra flexionando el codo y contrayendo los músculos de la espalda. Continúa subiendo hasta que la barbilla quede por encima de la barra. Baja el cuerpo de nuevo a la posición inicial con control. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/3290-fXfqg1E.jpg', 'videos/3290-fXfqg1E.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0840', 'weighted overhead crunch (on stability ball)', 'waist', 'waist', 'weighted', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a weight plate or dumbbell with both hands and extend your arms overhead. Engage your abs and slowly curl your torso forward, bringing your chest towards your knees. Pause for a moment at the top, then slowly lower your torso back to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén un disco de peso o una mancuerna con ambas manos y extiende los brazos por encima de la cabeza. Activa el abdomen y curva lentamente el torso hacia adelante, llevando el pecho hacia las rodillas. Haz una pausa de un momento en la parte superior, luego baja lentamente el torso de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0840-xmM75XG.jpg', 'videos/0840-xmM75XG.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0841', 'weighted pull-up', 'back', 'back', 'weighted', 'Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Sujeta la barra de dominadas con un agarre prono, un poco más ancho que la altura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia arriba, hacia la barra, manteniendo los codos cerca del cuerpo. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/0841-HMzLjXx.jpg', 'videos/0841-HMzLjXx.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0844', 'weighted round arm', 'shoulders', 'shoulders', 'weighted', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight. Raise your arms out to the sides, keeping a slight bend in your elbows. Continue lifting your arms until they are parallel to the ground. Pause for a moment at the top, then slowly lower your arms back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Eleva los brazos hacia los lados, manteniendo una ligera flexión en los codos. Continúa elevando los brazos hasta que queden paralelos al suelo. Haz una pausa por un momento en la parte superior, luego baja lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","upper back"]'::jsonb, 'delts', 'images/0844-VLYXo8S.jpg', 'videos/0844-VLYXo8S.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0846', 'weighted russian twist', 'waist', 'waist', 'weighted', 'Sit on the ground with your knees bent and your feet flat on the floor. Hold a weight or medicine ball with both hands in front of your chest. Lean back slightly, keeping your back straight and your core engaged. Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side. Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side. Continue alternating sides for the desired number of repetitions.', 'Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo. Sostén un peso o un balón medicinal con ambas manos frente al pecho. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado. Gira lentamente el torso hacia la derecha, llevando el peso o el balón medicinal hacia el suelo a tu lado derecho. Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso o el balón medicinal hacia el suelo a tu lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0846-fZFZ704.jpg', 'videos/0846-fZFZ704.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0845', 'weighted russian twist (legs up)', 'waist', 'waist', 'weighted', 'Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together. Hold the weight with both hands in front of your chest, keeping your elbows slightly bent. Lean back slightly to engage your core muscles. Twist your torso to the right, bringing the weight towards the ground on your right side. Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side. Continue alternating sides for the desired number of repetitions.', 'Siéntate en el suelo con las rodillas flexionadas y los pies levantados del suelo, manteniendo las piernas juntas. Sostén el peso con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados. Inclínate ligeramente hacia atrás para activar los músculos del core. Gira el torso hacia la derecha, llevando el peso hacia el suelo a tu lado derecho. Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso hacia el suelo a tu lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","hip flexors"]'::jsonb, 'abs', 'images/0845-WU9BLIs.jpg', 'videos/0845-WU9BLIs.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2371', 'weighted russian twist v. 2', 'waist', 'waist', 'weighted', 'Sit on the ground with your knees bent and feet flat on the floor. Hold the weight with both hands in front of your chest. Lean back slightly to engage your core muscles. Twist your torso to the right, bringing the weight towards the right side of your body. Pause for a moment, then twist your torso to the left, bringing the weight towards the left side of your body. Continue alternating sides for the desired number of repetitions.', 'Siéntate en el suelo con las rodillas flexionadas y los pies apoyados en el suelo. Sostén el peso con ambas manos frente al pecho. Inclínate ligeramente hacia atrás para activar los músculos del core. Gira el torso hacia la derecha, llevando el peso hacia el lado derecho de tu cuerpo. Haz una pausa de un momento, luego gira el torso hacia la izquierda, llevando el peso hacia el lado izquierdo de tu cuerpo. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/2371-YIUAtYf.jpg', 'videos/2371-YIUAtYf.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0847', 'weighted seated bicep curl (on stability ball)', 'upper arms', 'upper arms', 'medicine ball', 'Sit on a stability ball with your feet flat on the ground and your back straight. Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides. Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders. Pause for a moment at the top, squeezing your biceps. Inhale and slowly lower the medicine ball back down to the starting position. Repeat for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta. Sostén un balón medicinal con un agarre supino, las palmas hacia arriba, y deja que los brazos cuelguen a los lados. Manteniendo la parte superior de los brazos quieta, exhala y curva el balón medicinal hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente el balón medicinal de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0847-b4b6afT.jpg', 'videos/0847-b4b6afT.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0849', 'weighted seated twist (on stability ball)', 'waist', 'waist', 'weighted', 'Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle. Hold a weight plate or dumbbell with both hands close to your chest. Engage your core and slowly rotate your torso to one side, keeping your hips stable. Pause for a moment at the end of the rotation, then slowly return to the starting position. Repeat the rotation to the other side. Continue alternating sides for the desired number of repetitions.', 'Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados. Sostén un disco de peso o una mancuerna con ambas manos cerca del pecho. Activa el core y rota lentamente el torso hacia un lado, manteniendo las caderas estables. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite la rotación hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0849-s34Y4LR.jpg', 'videos/0849-s34Y4LR.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0850', 'weighted side bend (on stability ball)', 'waist', 'waist', 'weighted', 'Sit on a stability ball with your feet shoulder-width apart and flat on the ground. Hold a weight in one hand and place your other hand on your hip. Engage your core and slowly bend sideways towards the weighted side, keeping your back straight. Pause for a moment at the bottom, then slowly return to the starting position. Repeat for the desired number of repetitions, then switch sides.', 'Siéntate sobre un balón de estabilidad con los pies separados a la altura de los hombros y planos sobre el suelo. Sostén un peso en una mano y coloca la otra mano sobre la cadera. Activa el core e inclínate lentamente hacia el lado del peso, manteniendo la espalda recta. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'obliques', '["obliques","lower back"]'::jsonb, 'abs', 'images/0850-6bOA1Oi.jpg', 'videos/0850-6bOA1Oi.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0851', 'weighted sissy squat', 'upper legs', 'upper legs', 'weighted', 'Stand with your feet shoulder-width apart and your toes pointing slightly outward. Hold a weight in front of your chest with both hands, or place a barbell across your upper back. Keeping your chest up and your core engaged, slowly lower your body down by bending at the knees and hips. Continue lowering until your thighs are parallel to the ground or as low as you can comfortably go. Pause for a moment at the bottom, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sostén un peso frente al pecho con ambas manos, o coloca una barra sobre la parte superior de la espalda. Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y las caderas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'glutes', '["glutes","hamstrings","calves"]'::jsonb, 'quads', 'images/0851-0lQnxMZ.jpg', 'videos/0851-0lQnxMZ.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0852', 'weighted squat', 'upper legs', 'upper legs', 'weighted', 'Stand with your feet shoulder-width apart, toes pointing slightly outward. Hold a weight in front of your chest or on your shoulders. Engage your core and keep your chest up as you lower your hips down and back, as if sitting into a chair. Lower until your thighs are parallel to the ground, or as low as you can comfortably go. Push through your heels to stand back up, squeezing your glutes at the top. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Sostén un peso frente al pecho o sobre los hombros. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia abajo y hacia atrás, como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte superior. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/0852-JZuApnB.jpg', 'videos/0852-JZuApnB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0853', 'weighted standing curl', 'upper arms', 'upper arms', 'weighted', 'Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward. Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level. Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante. Mantén los codos cerca del torso y exhala mientras curvas los pesos hasta la altura de los hombros. Haz una pausa de un momento en la parte superior, luego inhala mientras bajas lentamente los pesos de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'forearms', '["forearms"]'::jsonb, 'biceps', 'images/0853-M5Y7GPg.jpg', 'videos/0853-M5Y7GPg.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0854', 'weighted standing hand squeeze', 'lower arms', 'lower arms', 'weighted', 'Stand with your feet shoulder-width apart and hold a weight in each hand. Extend your arms straight in front of you, palms facing each other. Squeeze your hands together as hard as you can, engaging your forearms. Hold the squeeze for a few seconds, then release. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén un peso en cada mano. Extiende los brazos rectos hacia adelante, con las palmas mirándose entre sí. Aprieta las manos entre sí con la mayor fuerza posible, activando los antebrazos. Mantén la contracción durante unos segundos y luego suelta. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps"]'::jsonb, 'forearms', 'images/0854-bjqbauy.jpg', 'videos/0854-bjqbauy.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3313', 'weighted straight bar dip', 'chest', 'chest', 'weighted', 'Position yourself between parallel bars with your arms fully extended and your body straight. Lower your body by bending your elbows until your upper arms are parallel to the ground. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Colócate entre las barras paralelas con los brazos completamente extendidos y el cuerpo recto. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/3313-Ff18ItA.jpg', 'videos/3313-Ff18ItA.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3642', 'weighted stretch lunge', 'upper legs', 'upper legs', 'weighted', 'Stand with your feet shoulder-width apart. Take a step forward with your right foot, keeping your back straight. Lower your body by bending your knees until your right thigh is parallel to the ground. Push through your right heel to return to the starting position. Repeat with your left leg. Continue alternating legs for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros. Da un paso adelante con el pie derecho, manteniendo la espalda recta. Baja el cuerpo flexionando las rodillas hasta que el muslo derecho quede paralelo al suelo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda. Continúa alternando las piernas durante el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'glutes', 'images/3642-13VW2VO.jpg', 'videos/3642-13VW2VO.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0856', 'weighted svend press', 'chest', 'chest', 'weighted', 'Stand with your feet shoulder-width apart and hold a weight plate in front of your chest with both hands. Keep your elbows slightly bent and your palms facing each other. Press the weight plate straight out in front of you, fully extending your arms. Pause for a moment at the end of the movement, then slowly bring the weight plate back to the starting position. Repeat for the desired number of repetitions.', 'Ponte de pie con los pies separados a la altura de los hombros y sostén un disco de peso frente al pecho con ambas manos. Mantén los codos ligeramente flexionados y las palmas mirándose entre sí. Empuja el disco de peso recto hacia adelante, extendiendo completamente los brazos. Haz una pausa de un momento al final del movimiento, luego lleva lentamente el disco de peso de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'shoulders', '["shoulders","triceps"]'::jsonb, 'pectorals', 'images/0856-I1OBLnn.jpg', 'videos/0856-I1OBLnn.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1754', 'weighted three bench dips', 'upper arms', 'upper arms', 'weighted', 'Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward. Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms. Lower your body by bending your elbows, keeping your back close to the bench. Pause for a moment at the bottom, then push yourself back up to the starting position. Repeat for the desired number of repetitions.', 'Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante. Camina con los pies hacia adelante, deslizando los glúteos fuera del banco y sosteniendo tu peso con los brazos. Baja el cuerpo flexionando los codos, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1754-gtO1ErP.jpg', 'videos/1754-gtO1ErP.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1755', 'weighted tricep dips', 'upper arms', 'upper arms', 'weighted', 'Sit on the edge of a bench or chair with your hands gripping the edge next to your hips. Slide your butt off the front of the bench with your legs extended in front of you. Keep your back close to the bench and your elbows slightly bent. Lower your body by bending your elbows until your upper arms are parallel to the floor. Push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas. Desliza los glúteos fuera del frente del banco con las piernas extendidas frente a ti. Mantén la espalda cerca del banco y los codos ligeramente flexionados. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1755-bZq4bwK.jpg', 'videos/1755-bZq4bwK.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1767', 'weighted triceps dip on high parallel bars', 'upper arms', 'upper arms', 'weighted', 'Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended. Bend your elbows and lower your body until your upper arms are parallel to the ground. Pause for a moment, then push through your palms to straighten your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Colócate entre dos barras paralelas con las manos agarrando las barras y los brazos completamente extendidos. Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo. Haz una pausa de un momento, luego empuja con las palmas para estirar los brazos y volver a la posición inicial. Repite el número de repeticiones deseado.', 'chest', '["chest","shoulders"]'::jsonb, 'triceps', 'images/1767-K1vlode.jpg', 'videos/1767-K1vlode.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0857', 'wheel rollerout', 'waist', 'waist', 'wheel roller', 'Kneel on the floor and place the wheel roller in front of you. Place your hands on the handles of the wheel roller and extend your arms straight out in front of you. Engage your core muscles and slowly roll the wheel forward, keeping your back straight and your abs tight. Continue rolling forward until your body is fully extended and your arms are overhead. Pause for a moment, then slowly roll the wheel back towards your knees, maintaining control and keeping your abs engaged. Repeat for the desired number of repetitions.', 'Arrodíllate en el suelo y coloca el rodillo frente a ti. Coloca las manos en las asas del rodillo y extiende los brazos rectos hacia adelante. Activa los músculos del core y haz rodar lentamente el rodillo hacia adelante, manteniendo la espalda recta y el abdomen contraído. Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza. Haz una pausa de un momento, luego haz rodar lentamente el rodillo de regreso hacia las rodillas, manteniendo el control y el abdomen activado. Repite el número de repeticiones deseado.', 'lower back', '["lower back"]'::jsonb, 'abs', 'images/0857-NAgVB3t.jpg', 'videos/0857-NAgVB3t.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('3637', 'wheel run', 'cardio', 'cardio', 'body weight', 'Start in a plank position with your hands on the wheel and your body straight. Engage your core and start rolling the wheel forward by extending your arms. Continue rolling until your body is fully extended and your arms are overhead. Reverse the movement by pulling the wheel back towards your body, using your core and arms. Repeat for the desired number of repetitions.', 'Comienza en posición de plancha con las manos sobre el rodillo y el cuerpo recto. Activa el core y comienza a hacer rodar el rodillo hacia adelante extendiendo los brazos. Continúa rodando hasta que tu cuerpo quede completamente extendido y los brazos por encima de la cabeza. Invierte el movimiento tirando del rodillo de vuelta hacia tu cuerpo, usando el core y los brazos. Repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'cardiovascular system', 'images/3637-km2Ljzj.jpg', 'videos/3637-km2Ljzj.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1429', 'wide grip pull-up', 'back', 'back', 'body weight', 'Hang from a pull-up bar with your palms facing away from you and your hands wider than shoulder-width apart. Engage your core and squeeze your shoulder blades together. Pull your body up towards the bar until your chin is above the bar. Lower your body back down to the starting position with control. Repeat for the desired number of repetitions.', 'Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos más separadas que la anchura de los hombros. Activa el core y junta los omóplatos. Tira de tu cuerpo hacia arriba en dirección a la barra hasta que tu barbilla quede por encima de la barra. Baja el cuerpo de nuevo a la posición inicial con control. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/1429-Qqi7bko.jpg', 'videos/1429-Qqi7bko.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1367', 'wide grip rear pull-up', 'back', 'back', 'body weight', 'Grab the pull-up bar with a wide overhand grip, hands slightly wider than shoulder-width apart. Hang from the bar with your arms fully extended and your body straight. Engage your back muscles and pull your body up towards the bar, leading with your chest. Continue pulling until your chin is above the bar. Pause for a moment at the top, then slowly lower your body back down to the starting position. Repeat for the desired number of repetitions.', 'Agarra la barra de dominadas con un agarre prono amplio, las manos un poco más separadas que la anchura de los hombros. Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto. Activa los músculos de la espalda y tira de tu cuerpo hacia la barra, llevando el pecho por delante. Continúa subiendo hasta que la barbilla quede por encima de la barra. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","forearms"]'::jsonb, 'lats', 'images/1367-OYFhXVD.jpg', 'videos/1367-OYFhXVD.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1311', 'wide hand push up', 'chest', 'chest', 'body weight', 'Start in a high plank position with your hands wider than shoulder-width apart. Keep your body in a straight line from head to toe. Lower your chest towards the ground by bending your elbows, keeping them close to your sides. Push through your palms to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', 'Comienza en una posición de plancha alta con las manos más separadas que la anchura de los hombros. Mantén el cuerpo en línea recta de la cabeza a los pies. Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/1311-JmMVpR3.jpg', 'videos/1311-JmMVpR3.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('2363', 'wide-grip chest dip on high parallel bars', 'chest', 'chest', 'body weight', 'Position yourself on the parallel bars with your arms fully extended and your body suspended in the air. Lean forward slightly and lower your body by bending your elbows until your chest is just above the bars. Pause for a moment, then push yourself back up to the starting position by straightening your arms. Repeat for the desired number of repetitions.', 'Colócate sobre las barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire. Inclínate ligeramente hacia adelante y baja el cuerpo flexionando los codos hasta que el pecho quede justo por encima de las barras. Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos. Repite el número de repeticiones deseado.', 'triceps', '["triceps","shoulders"]'::jsonb, 'pectorals', 'images/2363-O2K9Vb5.jpg', 'videos/2363-O2K9Vb5.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0858', 'wind sprints', 'waist', 'waist', 'body weight', 'Find an open space or a track to perform the exercise. Start by standing with your feet shoulder-width apart. Begin running as fast as you can, pumping your arms and driving your knees up. Continue sprinting for a specific distance or time period. Rest and repeat for the desired number of repetitions.', 'Busca un espacio abierto o una pista para realizar el ejercicio. Comienza de pie con los pies separados a la altura de los hombros. Comienza a correr lo más rápido que puedas, bombeando los brazos y elevando las rodillas. Continúa el sprint durante una distancia o periodo de tiempo específico. Descansa y repite el número de repeticiones deseado.', 'quadriceps', '["quadriceps","hamstrings","calves"]'::jsonb, 'abs', 'images/0858-Qoujh3Q.jpg', 'videos/0858-Qoujh3Q.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1604', 'world greatest stretch', 'upper legs', 'upper legs', 'body weight', 'Start in a lunge position with your right foot forward and your left foot back. Place your hands on the ground on either side of your right foot. Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground. Rotate your torso to the right, reaching your right arm up towards the ceiling. Hold this position for a few seconds, then return to the starting position. Switch sides and repeat the stretch with your left foot forward.', 'Comienza en posición de zancada con el pie derecho adelante y el pie izquierdo atrás. Coloca las manos en el suelo a ambos lados de tu pie derecho. Baja la rodilla izquierda hacia el suelo y extiende la pierna derecha, manteniendo el pie derecho plano sobre el suelo. Gira el torso hacia la derecha, extendiendo el brazo derecho hacia el techo. Mantén esta posición durante unos segundos, luego vuelve a la posición inicial. Cambia de lado y repite el estiramiento con el pie izquierdo adelante.', 'glutes', '["glutes","quadriceps","calves"]'::jsonb, 'hamstrings', 'images/1604-DFGXwZr.jpg', 'videos/1604-DFGXwZr.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('1428', 'wrist circles', 'lower arms', 'lower arms', 'body weight', 'Extend your arms straight out in front of you. Make a fist with both hands. Rotate your wrists in a circular motion, keeping your arms still. Continue the wrist circles for the desired number of repetitions.', 'Extiende los brazos rectos frente a ti. Cierra ambas manos en un puño. Gira las muñecas en un movimiento circular, manteniendo los brazos quietos. Continúa los círculos de muñeca el número de repeticiones deseado.', 'hands', '["hands","wrists"]'::jsonb, 'forearms', 'images/1428-2zNKRUB.jpg', 'videos/1428-2zNKRUB.gif');
INSERT INTO exercise_details (id, name, category, body_part, equipment, instructions_en, instructions_es, muscle_group, secondary_muscles, target, image, gif_url) VALUES ('0859', 'wrist rollerer', 'lower arms', 'lower arms', 'weighted', 'Attach a weight to one end of a rope or bar. Hold the other end of the rope or bar with both hands, palms facing down. Stand with your feet shoulder-width apart and your arms fully extended in front of you. Slowly roll the weight up towards your hands by flexing your wrists. Pause for a moment at the top, then slowly lower the weight back down to the starting position. Repeat for the desired number of repetitions.', 'Sujeta un peso a un extremo de una cuerda o barra. Sostén el otro extremo de la cuerda o barra con ambas manos, con las palmas hacia abajo. Ponte de pie con los pies separados a la altura de los hombros y los brazos completamente extendidos frente a ti. Enrolla lentamente el peso hacia las manos flexionando las muñecas. Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'biceps', '["biceps","triceps"]'::jsonb, 'forearms', 'images/0859-bd5b860.jpg', 'videos/0859-bd5b860.gif');
